INSERT INTO questions (
    id, exam_version_id, exam, supported_exams, skill, type_id, type_name,
    title, prompt, context_passage, audio_transcript, prep_time_seconds,
    time_limit_seconds, options, correct_answers, blanks, model_answer,
    explanation, difficulty, points, tags, is_published
) VALUES
    ('q-pl90-sst-01', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Why taxes on fuel raise so much', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Why do governments tax cigarettes, alcohol and fuel so heavily? Part of the answer lies in a concept economists call price elasticity of demand, which measures how much the quantity people buy changes when the price changes. For some goods, demand is elastic: if the price of one brand of cereal rises, many shoppers simply switch to another. For others, demand is inelastic, because people feel they need the product or have few alternatives. Fuel is a good example in the short term, since most drivers still need to get to work. Taxes on goods with inelastic demand raise large amounts of revenue, because sales fall only slightly. However, this also means such taxes may do less to change behaviour than their supporters hope. Over longer periods, demand often becomes more elastic, as people buy more efficient cars, move closer to work or, in the case of cigarettes, eventually quit.', 7, 600, NULL, '["price elasticity", "inelastic", "revenue", "longer periods"]'::jsonb, NULL, 'Price elasticity of demand describes how much purchases change when prices change. Goods with inelastic demand, such as fuel in the short term, keep selling when taxed, so taxes on them raise large revenue but may change behaviour less than expected. Over longer periods, demand usually becomes more elastic as people find alternatives, such as efficient cars or quitting smoking.', 'Key points to include: price elasticity, inelastic, revenue, longer periods. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-02', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Targeting inflation', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Many central banks today are given a clear goal: to keep inflation, the rate at which prices rise, close to a target, often around two percent a year. New Zealand was the first country to adopt such a target, in 1990, and many others followed. The main tool is the interest rate. When inflation is too high, the central bank raises rates, making borrowing more expensive, which tends to reduce spending and cool the economy. When inflation is too low, it cuts rates to encourage borrowing and spending. Why not aim for zero inflation? Economists argue that a small, stable rate gives some room to cut interest rates in a downturn and avoids the danger of falling prices, which can cause people to delay purchases. The approach works best when people trust that the bank will act, because expectations about future prices influence how businesses set prices and workers negotiate wages.', 7, 600, NULL, '["inflation", "target", "interest rates", "expectations"]'::jsonb, NULL, 'Many central banks aim to keep inflation near a target, often about two percent, an approach New Zealand introduced in 1990. They raise interest rates to cool spending when inflation is high and cut them when it is low. A small positive target leaves room to cut rates and avoids falling prices, and success depends on trust shaping public expectations.', 'Key points to include: inflation, target, interest rates, expectations. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-03', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Who pays for tariffs', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'A tariff is a tax on imported goods. Politicians sometimes describe tariffs as a way of making foreign countries pay, but economists point out that the reality is more complicated. The tax is paid at the border by the company importing the goods, and much of the cost is usually passed on to consumers through higher prices. Foreign producers may absorb part of it by lowering their prices to stay competitive, but studies of recent tariffs have often found that most of the burden fell on buyers in the country that imposed them. Tariffs can protect particular domestic industries from competition, preserving some jobs. However, they can also raise costs for other domestic businesses that rely on imported materials, and they may provoke other countries to respond with tariffs of their own, harming exporters. For these reasons, economists generally regard tariffs as a costly way of supporting industry.', 7, 600, NULL, '["tariffs", "consumers", "protect", "retaliation"]'::jsonb, NULL, 'Tariffs are taxes on imports paid by importing companies, and much of the cost is usually passed on to domestic consumers rather than foreign producers. They can protect certain industries and jobs, but they raise costs for businesses using imported materials and may lead to retaliation that harms exporters, so economists generally see them as a costly form of support.', 'Key points to include: tariffs, consumers, protect, retaliation. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-04', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Public goods', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Economists use the term public good for something that has two special features. First, it is difficult to prevent anyone from benefiting from it. Second, one person''s use does not reduce the amount available to others. Street lighting is a common example. Once a street is lit, everyone who walks along it benefits, and one extra person does not make the light dimmer. This creates a problem known as free riding. If a private company tried to sell street lighting, many residents would refuse to pay, knowing they would benefit anyway, so the service would probably not be provided at all, even though most people want it. This is why public goods such as street lighting, national defence and flood defences are usually funded through taxes. Economists debate which goods truly fit this definition, but the idea helps explain why some services are provided by governments rather than markets.', 7, 600, NULL, '["public good", "street lighting", "free riding", "taxes"]'::jsonb, NULL, 'A public good is one that nobody can easily be excluded from and whose use by one person does not reduce it for others, such as street lighting. Because people can benefit without paying, free riding means private firms would rarely supply it, so such goods, including defence and flood protection, are usually funded through taxes.', 'Key points to include: public good, street lighting, free riding, taxes. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-05', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Moral hazard', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Moral hazard is a term from the insurance industry. It describes the risk that people become less careful when they are protected from the consequences of their actions. Someone with full insurance on a bicycle, for example, might be less careful about locking it. Insurers respond in several ways. They often require customers to pay the first part of any claim themselves, known as an excess, so that the customer still has an incentive to avoid losses. They may also offer lower prices to people who take precautions, such as fitting alarms. The idea became widely discussed after the financial crisis of 2008, when governments rescued large banks. Critics argued that if banks expect to be saved when things go wrong, they may take bigger risks in the future. Regulators have since introduced rules requiring banks to hold more of their own capital, so that they carry more of the cost of their mistakes.', 7, 600, NULL, '["moral hazard", "insurance", "excess", "capital"]'::jsonb, NULL, 'Moral hazard is the tendency for people to take less care when protected from the consequences of their actions. In insurance, companies reduce it with an excess and discounts for precautions. After the 2008 crisis, bank rescues raised fears that banks would take bigger risks, so regulators now require banks to hold more capital and bear more of their losses.', 'Key points to include: moral hazard, insurance, excess, capital. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-06', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'The market for lemons', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'In 1970, the economist George Akerlof published a paper about the market for used cars, which helped him win a Nobel Prize. His key point was that sellers usually know much more about the quality of a car than buyers do. A buyer cannot easily tell a reliable car from a poor one, known in American slang as a lemon, so they are only willing to pay an average price. But at that price, owners of good cars may decide not to sell, because they would receive less than the car is worth. As good cars leave the market, the average quality falls, buyers lower the price they will pay, and the problem gets worse. This process is called adverse selection. Many features of modern markets exist partly to reduce it, including warranties, inspection reports, online reviews and brand reputations, all of which give buyers more reliable information.', 7, 600, NULL, '["used cars", "adverse selection", "quality", "warranties"]'::jsonb, NULL, 'George Akerlof showed that in the market for used cars sellers know more about quality than buyers, so buyers pay only an average price. Owners of good cars then withdraw, lowering average quality and prices further, a process called adverse selection. Warranties, inspections, reviews and brand reputations help by giving buyers more reliable information about what they are buying.', 'Key points to include: used cars, adverse selection, quality, warranties. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-07', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Pigouvian taxes', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'When a factory pollutes a river, the people living downstream bear part of the cost, yet the factory does not pay for it. Economists call such a cost an externality. Because the factory does not pay the full cost of its activities, it may produce more pollution than society would choose. In the early twentieth century, the British economist Arthur Pigou suggested a solution: tax the activity causing the harm, at a level matching the damage it does. The polluter then has a financial reason to reduce pollution, and it is free to decide how, whether by installing new equipment, changing its processes or producing less. Many economists favour such taxes because they reduce harm at the lowest overall cost. Setting the right level can be difficult, however, because the damage is not always easy to measure, and taxes can be politically unpopular, especially when they raise prices for consumers.', 7, 600, NULL, '["externality", "pollution", "tax", "unpopular"]'::jsonb, NULL, 'An externality is a cost, such as pollution, that falls on others rather than on the business causing it, leading to too much harm. Arthur Pigou proposed a tax on such activities in line with the damage, giving polluters a reason to cut pollution in the cheapest way. However, damage is hard to measure and such taxes can be unpopular.', 'Key points to include: externality, pollution, tax, unpopular. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-08', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Automatic pension enrolment', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Many people know they should save for retirement, yet they put it off. Behavioural economists have found that the default option has a powerful effect on what people do. In traditional pension schemes, employees had to actively sign up, and many never did. When employers instead enrol workers automatically, while allowing them to leave the scheme if they wish, participation rises dramatically. The United Kingdom introduced automatic enrolment in workplace pensions from 2012, and the proportion of eligible employees saving into a pension increased substantially over the following years, particularly among young and lower-paid workers. Nobody is forced to save, because anyone can opt out, but inertia now works in favour of saving rather than against it. Critics point out that automatic enrolment does not guarantee that people save enough, and the default contribution rates may still leave many with modest retirement incomes.', 7, 600, NULL, '["default", "automatic enrolment", "opt out", "retirement"]'::jsonb, NULL, 'Because people often delay saving, the default option strongly affects pension participation. When the United Kingdom introduced automatic enrolment from 2012, allowing workers to opt out, the share of employees saving rose substantially, especially among young and lower-paid workers. However, critics note that default contribution rates may still leave many people with modest retirement incomes.', 'Key points to include: default, automatic enrolment, opt out, retirement. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-09', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Limits on rents', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Rent control, which limits how much landlords can charge or how quickly rents can rise, is popular with many tenants, who value the protection it offers against sudden increases. Most economists, however, have been sceptical of strict rent controls. They argue that when rents are held below market levels, landlords have less incentive to maintain their properties or to build new rental housing. Some owners may convert apartments into homes for sale, reducing the supply of rental housing. A well-known study of San Francisco found that tenants who benefited from rent control were more likely to stay in their homes, but landlords reduced the number of rental units available, which may have pushed rents up elsewhere in the city. Supporters of rent regulation respond that milder forms, such as limiting annual increases, can provide stability for tenants without the worst side effects, especially if combined with building more homes.', 7, 600, NULL, '["rent control", "tenants", "supply", "San Francisco"]'::jsonb, NULL, 'Rent control protects tenants from sudden increases and is popular, but many economists argue that holding rents below market levels discourages maintenance and new building. A San Francisco study found tenants stayed longer but landlords reduced rental supply, possibly raising rents elsewhere. Supporters say milder limits, combined with building more homes, can give stability with fewer drawbacks.', 'Key points to include: rent control, tenants, supply, San Francisco. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-10', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'M-Pesa', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'In 2007, a mobile phone company in Kenya launched a service called M-Pesa, which allowed people to send and receive money using simple text messages. Customers could deposit and withdraw cash at small shops acting as agents. At the time, most Kenyans did not have a bank account, and sending money to relatives in rural areas often meant trusting a bus driver with an envelope of cash. M-Pesa spread rapidly, and within a few years it was used by a majority of adults in the country. Research suggested that access to the service helped households cope with unexpected problems, such as illness or a poor harvest, because relatives could quickly send support. One study estimated that it helped lift a significant number of households out of poverty. The service has since expanded to other countries, and it is often cited as an example of technology developed in Africa shaping financial services elsewhere.', 7, 600, NULL, '["M-Pesa", "bank account", "households", "poverty"]'::jsonb, NULL, 'M-Pesa, launched in Kenya in 2007, let people send money by text message and use local shops to deposit and withdraw cash, serving many without a bank account. It spread rapidly, helping households cope with shocks such as illness or poor harvests through fast support from relatives, and research suggests it reduced poverty. It has since expanded to other countries.', 'Key points to include: M-Pesa, bank account, households, poverty. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-11', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'The first public collections', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'For centuries, collections of rare objects belonged to kings, nobles and wealthy scholars, and were usually seen only by invited guests. The idea of a museum open to the public developed gradually. One of the earliest examples is the Ashmolean Museum in Oxford, which opened in 1683 to house a collection donated to the university, and which admitted visitors who paid a fee. In the following century, the British Museum opened in London in 1759, allowing free entry, although visitors initially had to apply for tickets in advance. After the French Revolution, the Louvre in Paris opened in 1793, displaying former royal collections as the property of the nation. These institutions reflected new ideas that knowledge and culture should be shared more widely. Today museums continue to look for ways to reach people who rarely visit, through free entry, online collections and events.', 7, 600, NULL, '["public", "Ashmolean", "Louvre", "shared"]'::jsonb, NULL, 'Collections of rare objects were once private, but public museums developed gradually. Early examples include the Ashmolean in Oxford in 1683, the British Museum in 1759 and the Louvre in 1793, which displayed royal collections as national property. They reflected the idea that culture should be shared, and museums still seek ways to reach people who rarely visit.', 'Key points to include: public, Ashmolean, Louvre, shared. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-12', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'The founding of the Red Cross', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'In 1859, a Swiss businessman named Henri Dunant witnessed the aftermath of the Battle of Solferino in northern Italy, where tens of thousands of soldiers lay wounded with little medical help. He organised local people to care for the injured, regardless of which side they had fought on. Afterwards he wrote a book describing what he had seen and proposing two ideas: that every country should have volunteer relief societies trained to help the wounded in war, and that there should be an international agreement protecting them. Both ideas became reality. The International Committee of the Red Cross was founded in Geneva in 1863, and in 1864 the first Geneva Convention was signed, protecting wounded soldiers and the medical staff caring for them. Dunant later shared the first Nobel Peace Prize in 1901, although by then he had lost his fortune and lived in poverty.', 7, 600, NULL, '["Solferino", "Red Cross", "Geneva Convention", "Nobel Peace Prize"]'::jsonb, NULL, 'After seeing thousands of wounded soldiers at Solferino in 1859, Henri Dunant organised care for both sides and proposed national volunteer relief societies and an international agreement protecting them. The Red Cross was founded in 1863 and the first Geneva Convention signed in 1864. Dunant shared the first Nobel Peace Prize in 1901, despite living in poverty.', 'Key points to include: Solferino, Red Cross, Geneva Convention, Nobel Peace Prize. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-13', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'The first Paralympics', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'The Paralympic Games grew out of work at Stoke Mandeville Hospital in England, where the neurologist Ludwig Guttmann treated soldiers and civilians with spinal injuries after the Second World War. At the time, such injuries were often seen as the end of an active life, but Guttmann believed that sport could aid physical rehabilitation and restore confidence. In 1948, on the same day the London Olympics opened, he organised an archery competition for patients in wheelchairs. The event grew each year and soon included international teams. In 1960, a competition held in Rome, just after the Olympic Games there, is now recognised as the first Paralympic Games, with around four hundred athletes. Over time, the Games expanded to include athletes with a wider range of impairments. Since 1988, the Paralympics have been held in the same city as the Olympics, and they now attract thousands of athletes and large global audiences.', 7, 600, NULL, '["Guttmann", "spinal injuries", "Rome", "1988"]'::jsonb, NULL, 'The Paralympics began with Ludwig Guttmann''s work at Stoke Mandeville Hospital, where he used sport to rehabilitate people with spinal injuries after the Second World War. His 1948 wheelchair archery competition grew into international events, and the 1960 Rome games are recognised as the first Paralympics. The Games later included more impairments and, since 1988, share the Olympic host city.', 'Key points to include: Guttmann, spinal injuries, Rome, 1988. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-14', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Where surnames come from', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'For much of history, most people had only one name. As populations grew, this caused confusion, especially for officials collecting taxes or recording property. Surnames developed gradually to solve this problem, and in many European languages they fall into a few main types. Some describe a person''s job, such as Smith, Baker or Miller. Others refer to where someone lived, such as Hill or Brook. Many come from a father''s name, such as Johnson, meaning son of John, or its equivalents in other languages. A fourth group began as nicknames describing appearance or character. Not all cultures followed the same path. In Iceland, most people still use a name based on their father''s or mother''s first name rather than a fixed family surname. Japan made family names compulsory for all citizens only in 1875, when the government required everyone to register one.', 7, 600, NULL, '["surnames", "jobs", "father''s name", "Iceland"]'::jsonb, NULL, 'As populations grew, single names caused confusion for officials, so surnames developed gradually. In many European languages they come from jobs, places, a father''s name or nicknames. Other cultures differ: people in Iceland still mostly use names based on a parent''s first name, and Japan required all citizens to register a family name only in 1875.', 'Key points to include: surnames, jobs, father''s name, Iceland. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-15', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'A short history of the passport', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Travel documents have existed for centuries, but for most of history people could cross many borders without them. In the nineteenth century, the spread of railways made international travel much easier, and many European countries relaxed or abandoned passport requirements. The First World War changed this. Governments, worried about spies and keen to control the movement of people, introduced strict passport rules, and they remained in place after the war. In 1920, an international conference organised by the League of Nations agreed a standard format, a small booklet with a photograph and a description of the holder, which was the basis for the modern passport. Many travellers at the time objected to having their photographs taken for official purposes, seeing it as treating them like criminals. Since then, passports have added machine-readable pages and electronic chips storing the holder''s details.', 7, 600, NULL, '["passport", "First World War", "League of Nations", "photograph"]'::jsonb, NULL, 'A passport was often unnecessary in the nineteenth century, when railways made travel easier and rules were relaxed. The First World War brought strict controls that remained afterwards, and in 1920 a League of Nations conference agreed a standard booklet with a photograph, the basis of today''s passport. Some travellers objected, and modern passports add electronic chips.', 'Key points to include: passport, First World War, League of Nations, photograph. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-16', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'The oldest universities', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Which is the oldest university in the world? The answer depends on how a university is defined. The University of al-Qarawiyyin in Fez, Morocco, founded in 859 by a woman named Fatima al-Fihri, is often described as the oldest continuously operating institution of higher learning, although it began as a mosque with a school attached. In Europe, the University of Bologna, dating from 1088, is usually considered the first university in the modern sense: a self-governing community of students and teachers that awarded degrees. Interestingly, at Bologna it was the students who initially held much of the power, hiring teachers and even fining them if they started late or skipped difficult topics. Oxford and Paris followed soon after, with teachers playing a larger role in their organisation. These medieval institutions established features that still exist today, including degrees, faculties and academic dress.', 7, 600, NULL, '["al-Qarawiyyin", "Bologna", "students", "degrees"]'::jsonb, NULL, 'The answer depends on definition. Al-Qarawiyyin in Morocco, founded in 859 by Fatima al-Fihri, is often called the oldest continuously operating institution of higher learning, while Bologna, from 1088, is usually seen as the first university in the modern sense. At Bologna, students initially held power over teachers, and medieval universities established degrees, faculties and academic dress.', 'Key points to include: al-Qarawiyyin, Bologna, students, degrees. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-17', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'A slow welcome for the fork', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Forks now seem an essential part of eating in many countries, but they were slow to be accepted in Europe. Large forks were used in kitchens for centuries, but small forks for eating were more common in the Byzantine Empire. According to a famous story, when a Byzantine princess married into a Venetian noble family in the eleventh century and ate with a golden fork, some church leaders condemned her behaviour as excessively refined. Forks gradually spread through Italy, where they were useful for eating pasta, but many other Europeans continued to eat with knives, spoons and their fingers. In the early seventeenth century, an English traveller described Italian forks as a curious custom. It was not until the eighteenth century that forks became common in much of Europe. In many parts of the world, of course, people continued to eat with chopsticks or their hands, which remain the most common methods globally.', 7, 600, NULL, '["forks", "Byzantine", "Italy", "chopsticks"]'::jsonb, NULL, 'Eating forks were used in the Byzantine Empire but spread slowly in Europe. A Byzantine princess using a golden fork in Venice was reportedly criticised, and forks became popular in Italy partly for pasta, while elsewhere people used knives, spoons and fingers until the eighteenth century. Worldwide, chopsticks and hands remain the most common ways of eating.', 'Key points to include: forks, Byzantine, Italy, chopsticks. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-18', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'The history of the toothbrush', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'People have cleaned their teeth for thousands of years, using chewed twigs from certain trees, some of which are still used today in parts of Africa, the Middle East and South Asia. The bristle toothbrush appears to have been developed in China, where records describe brushes made with hairs from pigs attached to handles of bone or bamboo. In England, a man named William Addis is credited with starting the first mass production of toothbrushes in the late eighteenth century. According to the company''s history, he had the idea while in prison, when he made a brush from a small bone and some bristles. Brushing did not become a daily habit for most people until the twentieth century. Soldiers in the Second World War were required to brush their teeth and brought the habit home. The introduction of nylon bristles in the 1930s also made toothbrushes cheaper and more hygienic.', 7, 600, NULL, '["twigs", "China", "William Addis", "nylon"]'::jsonb, NULL, 'People cleaned their teeth with chewed twigs for thousands of years, and bristle toothbrushes were developed in China using pig hair. William Addis began mass production in England in the eighteenth century, reportedly after making a brush in prison. Daily brushing became common only in the twentieth century, helped by wartime habits and cheaper, more hygienic nylon bristles.', 'Key points to include: twigs, China, William Addis, nylon. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-19', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Loneliness and health', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Loneliness is usually thought of as an emotional problem, but researchers increasingly treat it as a public health issue. Large studies following people over many years have found that social isolation and loneliness are associated with a higher risk of early death, as well as heart disease, stroke and depression. One widely discussed analysis suggested that the effect on mortality was comparable to well-known risk factors such as obesity. Scientists are still investigating why. Loneliness may cause chronic stress, disrupt sleep and make people less likely to exercise or seek medical help. Importantly, being alone and feeling lonely are not the same; some people live alone happily, while others feel lonely in a crowd. In 2018, the United Kingdom appointed a government minister with responsibility for loneliness, and some doctors now refer patients to community groups and activities, an approach known as social prescribing.', 7, 600, NULL, '["loneliness", "public health", "early death", "social prescribing"]'::jsonb, NULL, 'Researchers increasingly treat loneliness as a public health issue, since studies link isolation and loneliness to early death, heart disease, stroke and depression, possibly through stress, poor sleep and less healthy behaviour. Being alone differs from feeling lonely. The United Kingdom appointed a minister for loneliness in 2018, and doctors may use social prescribing to connect patients with community activities.', 'Key points to include: loneliness, public health, early death, social prescribing. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-20', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Exercise and low mood', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Physical activity is well known to benefit the heart and muscles, but there is also strong evidence that it helps mental health. Reviews combining many studies have found that regular exercise can reduce symptoms of depression, and in some trials its effect was comparable to that of talking therapies or medication for mild to moderate cases. Several explanations have been proposed. Exercise may affect chemicals in the brain linked to mood, improve sleep, reduce inflammation and provide a sense of achievement. Group activities can also offer social contact. Importantly, benefits have been found for many types of exercise, including walking, and not only for intense training. However, experts stress that exercise is not a replacement for professional treatment in severe depression, and that one of the difficulties is that depression itself reduces energy and motivation, so people may need support to get started.', 7, 600, NULL, '["exercise", "depression", "walking", "motivation"]'::jsonb, NULL, 'Research shows that regular exercise can reduce symptoms of depression, sometimes as much as therapy or medication in mild to moderate cases, possibly by affecting brain chemicals, sleep, inflammation and confidence. Many activities, including walking, help. However, exercise does not replace treatment for severe depression, and because depression reduces motivation, people may need support to start.', 'Key points to include: exercise, depression, walking, motivation. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-21', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Short sight and outdoor play', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Short-sightedness, or myopia, has become far more common in recent decades. In some cities in East Asia, a large majority of young people finishing school are now short-sighted, compared with a much smaller share a few generations ago. The change has happened too quickly to be explained by genes alone. For many years, reading and close work were blamed, but research increasingly points to another factor: time spent outdoors. Children who spend more time outside tend to be less likely to become short-sighted, and one explanation is that bright daylight affects how the eye grows. In a trial in China, schools that added an extra outdoor class each day saw fewer new cases of myopia. As a result, some countries now encourage schools to give children more time outside. Severe myopia matters because it increases the risk of serious eye diseases later in life.', 7, 600, NULL, '["myopia", "outdoor", "daylight", "eye disease"]'::jsonb, NULL, 'Myopia has risen sharply, especially in East Asian cities, too quickly for genes alone to explain. Research suggests a lack of time outdoors is important, possibly because bright daylight affects eye growth, and a Chinese trial found an extra daily outdoor class reduced new cases. Some countries now encourage outdoor time, since severe myopia raises the risk of eye disease.', 'Key points to include: myopia, outdoor, daylight, eye disease. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-22', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'How painkillers work', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Common painkillers work in different ways. Drugs such as ibuprofen and aspirin belong to a group called non-steroidal anti-inflammatory drugs. They block enzymes that produce substances called prostaglandins, which contribute to pain, fever and swelling. Because they reduce inflammation, they are often recommended for injuries such as sprains. However, they can irritate the stomach and are not suitable for everyone. Paracetamol, known as acetaminophen in some countries, also reduces pain and fever, but it has little effect on inflammation, and scientists are still not entirely sure how it works. It is gentle on the stomach, but taking more than the recommended dose can seriously damage the liver, which is why pack sizes are limited in some countries. Doctors often point out that combining different painkillers safely can be more effective than increasing the dose of one, but people should always follow medical advice.', 7, 600, NULL, '["ibuprofen", "inflammation", "paracetamol", "liver"]'::jsonb, NULL, 'Anti-inflammatory drugs such as ibuprofen and aspirin block prostaglandins, reducing pain, fever and swelling, but they can irritate the stomach. Paracetamol reduces pain and fever with little effect on inflammation, and how it works is not fully understood; it is gentle on the stomach, but overdoses can damage the liver. Combining painkillers safely may help, following medical advice.', 'Key points to include: ibuprofen, inflammation, paracetamol, liver. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-23', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Lactase persistence', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'All human babies can digest lactose, the sugar in milk, using an enzyme called lactase. In most mammals, including most humans historically, production of this enzyme falls after weaning, so adults who drink large amounts of milk may suffer from stomach discomfort. However, in some populations, many adults continue producing lactase throughout life. This trait, called lactase persistence, is common in northern Europe and among some herding groups in East Africa and the Middle East. Genetic studies show that it evolved separately in different regions, through different mutations, within the last several thousand years, after people began keeping dairy animals. This is one of the clearest examples of recent human evolution, and of culture shaping biology: where milk was an important food, people who could digest it may have had an advantage. Worldwide, however, most adults still have a reduced ability to digest lactose.', 7, 600, NULL, '["lactase", "milk", "evolved", "dairy"]'::jsonb, NULL, 'Babies digest lactose, but in most people lactase production falls after weaning. In some populations, including northern Europeans and certain East African and Middle Eastern herders, lactase persistence evolved separately within the last few thousand years after dairy farming began. It is a clear example of recent evolution shaped by culture, though most adults worldwide still digest milk poorly.', 'Key points to include: lactase, milk, evolved, dairy. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-24', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Why fingers wrinkle', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'After a long bath, our fingers and toes become wrinkled. For a long time, this was thought to be a simple result of skin absorbing water and swelling. But in the 1930s, doctors noticed that fingers did not wrinkle if the nerves to them had been damaged, showing that wrinkling is an active process controlled by the nervous system. When skin is soaked, blood vessels beneath it narrow, and the skin surface folds. Why would the body do this? In 2013, researchers reported that people with wrinkled fingers were quicker at moving wet objects from one container to another, suggesting that wrinkles might improve grip in wet conditions, like the tread on a tyre. Other studies, however, have not found the same advantage, so the question remains open. Doctors have occasionally used the wrinkling test to check whether nerves in the hand are working properly.', 7, 600, NULL, '["wrinkle", "nerves", "grip", "uncertain"]'::jsonb, NULL, 'Fingers wrinkle in water not through simple swelling but through an active process controlled by nerves, since damaged nerves prevent it; blood vessels narrow and the skin folds. A 2013 study suggested wrinkles improve grip on wet objects, but other studies disagree, so the purpose remains uncertain. Doctors have used the test to check nerves in the hand.', 'Key points to include: wrinkle, nerves, grip, uncertain. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-25', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Learning styles', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Many people believe that each of us has a preferred learning style, such as visual, auditory or hands-on, and that students learn best when teaching matches that style. Surveys have found that large numbers of teachers around the world accept this idea. Yet when researchers have tested it properly, the evidence has been weak. To support the theory, a study would need to show that visual learners do better with visual teaching while auditory learners do better with spoken teaching. Reviews of the research have found very few studies meeting this standard, and those that exist generally do not support the idea. People certainly have preferences, but preferring a method does not mean learning more from it. Experts suggest that the best approach often depends on the content: maps are best understood visually, for example, and pronunciation through listening. Using several methods together can help everyone.', 7, 600, NULL, '["learning style", "evidence", "preferences", "content"]'::jsonb, NULL, 'Many teachers believe students learn best when teaching matches their preferred learning style, such as visual or auditory. However, properly designed studies provide little evidence for this, and preferences do not mean better learning. Experts argue that the best method depends on the content, such as maps shown visually or pronunciation taught through listening, and combining methods helps all students.', 'Key points to include: learning style, evidence, preferences, content. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-26', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Teachers'' expectations', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'In the 1960s, the psychologists Robert Rosenthal and Lenore Jacobson told teachers at an American school that certain pupils had been identified by a test as likely to make rapid intellectual progress. In reality, these pupils had been chosen at random. At the end of the year, some of the selected children, particularly younger ones, showed greater gains in test scores than their classmates. The researchers concluded that teachers'' expectations had influenced the pupils'' progress, perhaps because teachers gave them more attention, encouragement and challenging work. The study became famous as the Pygmalion effect. It has also been criticised. Later researchers questioned its methods, and attempts to repeat it found smaller or inconsistent effects. Most psychologists now agree that teacher expectations can influence pupils, but that the effect is usually modest rather than dramatic. Even so, the idea encourages teachers to hold high expectations for all students.', 7, 600, NULL, '["expectations", "Pygmalion effect", "modest", "teachers"]'::jsonb, NULL, 'In the 1960s, teachers were told that randomly chosen pupils would progress rapidly, and some of those pupils, especially younger ones, later gained more. Researchers concluded that expectations shaped progress through attention and encouragement, the Pygmalion effect. Later studies questioned the methods and found smaller effects, so the influence is considered real but modest, encouraging teachers to hold high expectations for everyone.', 'Key points to include: expectations, Pygmalion effect, modest, teachers. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-27', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Testing yourself to remember', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Many students revise by rereading their notes and textbooks, often several times. It feels productive, because the material becomes familiar. However, research on memory suggests that a different method is much more effective: testing yourself. In many experiments, students who practised recalling information, for example by answering questions or writing down everything they could remember, performed better on later tests than students who spent the same time rereading. This is known as the testing effect, or retrieval practice. The effort of retrieving information from memory seems to strengthen it and make it easier to recall in the future. Tests also reveal what a student does not know, allowing them to focus on weak areas. Researchers note that the practice tests do not need to be marked or to count towards grades. Simple techniques, such as flashcards or covering notes and explaining a topic aloud, can provide the same benefit.', 7, 600, NULL, '["rereading", "testing", "retrieval", "flashcards"]'::jsonb, NULL, 'Rereading notes feels productive because material becomes familiar, but research shows that testing yourself is more effective. In experiments, students who practised recalling information outperformed those who spent the time rereading, because retrieval strengthens memory and reveals gaps in knowledge. Practice tests need not be marked, and simple methods such as flashcards or explaining topics aloud provide the same benefit.', 'Key points to include: rereading, testing, retrieval, flashcards. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-28', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Note-taking methods', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Do students learn more by taking notes by hand or on a laptop? A widely reported study in 2014 found that students who typed tended to copy lectures word for word, while those who wrote by hand, being slower, had to summarise in their own words. On questions testing understanding, the handwriting group performed better. The study was influential, and some lecturers banned laptops from their classrooms. However, later attempts to repeat the experiment produced mixed results, and a larger replication found that the difference was small and not reliable. What seems more consistent is that the way students process information matters more than the tool. Summarising, reorganising ideas and reviewing notes later all help learning, whichever method is used. Laptops also bring a separate problem: distraction. Studies have found that students who browse the internet during lectures learn less, and may even distract classmates sitting nearby.', 7, 600, NULL, '["handwriting", "laptop", "replication", "distraction"]'::jsonb, NULL, 'A 2014 study suggested that handwriting improves understanding because slower writers summarise rather than copy word for word, and some lecturers banned the laptop from class. However, a larger replication found small, unreliable differences. How students process information, by summarising and reviewing notes, matters more than the tool, although laptops can cause distraction for users and nearby classmates.', 'Key points to include: handwriting, laptop, replication, distraction. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-29', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Shared picture-book reading', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Reading aloud to young children is often recommended by teachers and health professionals, and research supports the advice. Picture books contain a wider range of vocabulary than most everyday conversation, so children who are read to regularly hear many words they would rarely encounter otherwise. One study estimated that children whose parents read to them daily would hear over a million more words by the time they started school than children who were never read to. Shared reading also helps children understand how stories are structured, connect spoken and written language, and develop concentration. Benefits appear to be greatest when adults make it interactive, asking questions, pointing to pictures and encouraging children to predict what will happen next, rather than simply reading the words. Importantly, the language does not need to be the language of school; reading in a family''s home language supports development just as well.', 7, 600, NULL, '["reading aloud", "vocabulary", "interactive", "home language"]'::jsonb, NULL, 'Research supports reading aloud to young children, because picture books contain richer vocabulary than everyday conversation, and daily reading may expose children to over a million extra words before school. It also builds understanding of stories and concentration. Benefits are greatest when reading is interactive, with questions and predictions, and reading in the home language works equally well.', 'Key points to include: reading aloud, vocabulary, interactive, home language. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-30', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Smaller classes', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Does reducing class sizes improve learning? One of the most influential studies, known as Project STAR, took place in the American state of Tennessee in the late 1980s. Thousands of young pupils and their teachers were randomly assigned to small classes of around fifteen pupils or to regular classes of around twenty-two to twenty-five. Because the assignment was random, differences in results could be linked to class size itself. Pupils in small classes performed better in the early years, and the benefits were larger for children from disadvantaged backgrounds. Some follow-up studies found lasting advantages, such as higher rates of college entry. However, smaller classes are expensive, because they require more teachers and classrooms. When California reduced class sizes rapidly in the 1990s, it had to hire many inexperienced teachers, and the gains were smaller than expected. Policymakers therefore weigh class size against other uses of the same money.', 7, 600, NULL, '["class size", "randomly", "disadvantaged", "teachers"]'::jsonb, NULL, 'Tennessee''s Project STAR randomly assigned pupils to small or regular classes and found that a smaller class size improved early results, especially for disadvantaged children, with some lasting benefits. However, smaller classes are costly, and California''s rapid reduction required many inexperienced teachers and produced smaller gains, so policymakers compare class size with other uses of money.', 'Key points to include: class size, randomly, disadvantaged, teachers. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-31', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Unequal internet access', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'The term digital divide describes the gap between people who have access to the internet and digital technology and those who do not. Globally, a large share of the population still does not use the internet, and most of these people live in low-income countries and rural areas. But the divide is not only about access. Researchers also point to differences in the quality of connection, the devices people use and the skills needed to benefit from them. A student trying to complete homework on a shared mobile phone with limited data faces very different conditions from one with a laptop and fast broadband. These differences became especially visible when schools closed during the pandemic and lessons moved online. Efforts to close the divide include expanding mobile networks, reducing data costs, providing devices through schools and libraries, and teaching digital skills to older adults and others who lack confidence online.', 7, 600, NULL, '["digital divide", "access", "skills", "pandemic"]'::jsonb, NULL, 'The digital divide is the gap between those with and without internet access, especially in low-income and rural areas. It also includes connection quality, devices and digital skills, differences exposed when schools moved online during the pandemic. Solutions include expanding networks, lowering data costs, providing devices through schools and libraries, and teaching skills to those who lack confidence.', 'Key points to include: digital divide, access, skills, pandemic. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-32', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Ranking web pages', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'In the early days of the web, search engines ranked pages mainly by counting how often the search words appeared on them. This was easy to manipulate: a page could simply repeat popular words many times. In the late 1990s, two graduate students at Stanford University, Larry Page and Sergey Brin, developed a different approach called PageRank. It treated a link from one page to another as a kind of vote. A page linked to by many other pages was likely to be important, and a link from an important page counted for more than a link from an obscure one. This idea helped their search engine, Google, produce much more useful results, and it grew rapidly. Modern search engines use hundreds of signals, and link-based ranking led to new forms of manipulation, such as creating networks of fake links, which search companies continue to fight.', 7, 600, NULL, '["search engines", "PageRank", "links", "manipulation"]'::jsonb, NULL, 'Early search engines ranked pages by counting search words, which was easily manipulated. Larry Page and Sergey Brin developed PageRank, treating links as votes and giving links from important pages more weight, which helped Google produce better results. Modern search engines use hundreds of signals, and link-based ranking created new manipulation, such as fake link networks, that companies still fight.', 'Key points to include: search engines, PageRank, links, manipulation. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-33', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Moore''s law', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'In 1965, Gordon Moore, who later co-founded the chip maker Intel, observed that the number of components that could be placed on a computer chip was doubling roughly every year. He later revised the rate to about every two years. His observation, known as Moore''s law, was not a law of nature but a prediction, and for decades the industry treated it almost as a target. As transistors became smaller, chips became faster, cheaper and more energy-efficient, which explains why a modern smartphone is far more powerful than the computers that guided the first Moon landings. In recent years, however, progress has slowed. Transistors are now so small that they approach the size of atoms, making further shrinking extremely difficult and expensive. Engineers are responding in other ways, such as stacking components in three dimensions and designing specialised chips for particular tasks, such as artificial intelligence.', 7, 600, NULL, '["Moore''s law", "transistors", "slowed", "specialised chips"]'::jsonb, NULL, 'In 1965 Gordon Moore observed that chip components were doubling regularly, later about every two years. Moore''s law was a prediction the industry treated as a target, and shrinking transistors made chips faster, cheaper and more efficient. Progress has slowed as transistors approach atomic size, so engineers now stack components and design specialised chips for tasks such as artificial intelligence.', 'Key points to include: Moore''s law, transistors, slowed, specialised chips. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-34', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'The millennium bug', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'In the late 1990s, governments and businesses around the world became concerned about a problem known as the millennium bug, or Y2K. Many older computer systems stored years using only their last two digits, to save expensive memory. The year 1999 was recorded as ninety-nine, so when the date changed to 2000, some systems might read it as 1900, causing errors in calculations involving dates, from bank interest to scheduling. Organisations spent enormous sums checking and correcting their software. When the new year arrived, very few serious problems occurred. Some people concluded that the danger had been exaggerated and the money wasted. Many engineers who worked on the problem argue the opposite: that failures were rare precisely because so much work had been done in advance. The episode is sometimes used to illustrate a difficulty with prevention. When a problem is successfully avoided, it can look as though it never existed.', 7, 600, NULL, '["millennium bug", "two digits", "prevention", "software"]'::jsonb, NULL, 'The millennium bug arose because older systems stored years with two digits, so 2000 might be read as 1900, causing date errors. Organisations spent heavily fixing software, and few problems occurred. Some called the fears exaggerated, but engineers argue the preparation prevented failures, illustrating how successful prevention can make a problem look as though it never existed.', 'Key points to include: millennium bug, two digits, prevention, software. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-35', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Packet switching', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'When you send a photo over the internet, it does not travel as a single piece. Instead, it is broken into many small packets of data, each labelled with its destination and its place in the sequence. The packets may travel by different routes through the network, and at the other end they are put back together in the right order. If a packet is lost or damaged, it can simply be sent again. This method, called packet switching, was developed in the 1960s by researchers in the United States and Britain. It differed from the telephone network, which created a dedicated connection for the whole length of a call. Packet switching makes much more efficient use of the network, because many users can share the same connections, and it is resilient, since data can be routed around damaged or congested parts of the network. It remains a foundation of the internet today.', 7, 600, NULL, '["packets", "packet switching", "efficient", "resilient"]'::jsonb, NULL, 'Internet data is split into labelled packets that may travel by different routes and are reassembled at the destination, with lost packets sent again. Packet switching, developed in the 1960s in the United States and Britain, differs from dedicated telephone connections. It is efficient because users share connections, and resilient because data can avoid damaged or congested routes.', 'Key points to include: packets, packet switching, efficient, resilient. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-36', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Range anxiety', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'When people consider buying an electric car, one of their most common concerns is range anxiety: the fear that the battery will run out before they reach a charging point. Surveys suggest this worry often exceeds the reality. Most daily journeys are far shorter than the range of modern electric cars, and many owners charge at home overnight, so they start each day with a full battery. Long journeys still require planning, and the availability and reliability of public chargers vary greatly between regions. Cold weather can also reduce range noticeably, because batteries work less efficiently and energy is needed to heat the car. Researchers have found that range anxiety tends to fall after people gain experience with electric cars, as they learn how far they can actually travel. Governments and companies are investing in faster charging networks, particularly along motorways, to address the concerns of people who have not yet switched.', 7, 600, NULL, '["range anxiety", "charge at home", "cold weather", "experience"]'::jsonb, NULL, 'Range anxiety, the fear that an electric car''s battery will run out, is common but often exceeds reality, since most journeys are short and many owners charge at home. Long trips need planning, public chargers vary, and cold weather reduces range. The worry usually falls with experience, and investment in faster charging networks aims to reassure new buyers.', 'Key points to include: range anxiety, charge at home, cold weather, experience. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-37', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'QR codes', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'QR codes, the square black-and-white patterns scanned with phone cameras, were invented in 1994 by an engineer at a Japanese company that made parts for the car industry. They were designed to track components in factories, and could store far more information than traditional barcodes, which can only be read in one direction. The name stands for quick response. The codes can be read from any angle, and they include extra information that allows them to be scanned even if part of the pattern is damaged or dirty. The company chose not to enforce its patent, allowing anyone to use the design freely, which helped it spread. For many years, QR codes were popular in parts of Asia but less so elsewhere, partly because phones needed separate apps to read them. When phone cameras began reading them automatically, and the pandemic encouraged contactless menus and payments, they became common worldwide.', 7, 600, NULL, '["QR codes", "barcodes", "damaged", "pandemic"]'::jsonb, NULL, 'QR codes were invented in Japan in 1994 to track car parts and store more information than barcodes. They can be read from any angle and even when damaged, and the company allowed free use of the design. Once phone cameras could read them automatically and the pandemic encouraged contactless menus and payments, they spread worldwide.', 'Key points to include: QR codes, barcodes, damaged, pandemic. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-38', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'The mantis shrimp''s punch', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'The mantis shrimp is a small, brightly coloured marine animal with one of the most powerful strikes in the animal kingdom. Some species have club-like limbs that they fire forward at extraordinary speed to smash the shells of crabs and snails. The strike is so fast that it causes bubbles to form and collapse in the water, producing an additional shock wave, a process called cavitation. In aquariums, mantis shrimp have been known to crack glass. Scientists have studied how the animal''s clubs survive repeated impacts without breaking. They are built in layers arranged in a spiral pattern, which stops cracks from spreading. This structure has inspired engineers developing lightweight, impact-resistant materials for helmets, body armour and aircraft. Mantis shrimp are also famous for their eyes, which contain many more types of colour receptors than human eyes, although experiments suggest they are not better than us at telling similar colours apart.', 7, 600, NULL, '["mantis shrimp", "shock wave", "layers", "colour receptors"]'::jsonb, NULL, 'The mantis shrimp strikes prey with club-like limbs so fast that collapsing bubbles create an extra shock wave, and it can even crack aquarium glass. Its clubs resist damage thanks to spiral layers that stop cracks spreading, inspiring impact-resistant materials. Its eyes have many colour receptors, though experiments suggest it does not distinguish similar colours better than humans.', 'Key points to include: mantis shrimp, shock wave, layers, colour receptors. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-39', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Cuckoos in the nest', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'The common cuckoo does not build a nest or raise its own young. Instead, the female lays her eggs in the nests of other bird species, a strategy known as brood parasitism. Her egg often closely resembles those of the host species in colour and pattern, reducing the chance that it will be rejected. After hatching, the cuckoo chick usually pushes the host''s eggs or chicks out of the nest, so that it receives all the food. The host parents then raise the cuckoo, even when it grows much larger than they are. This relationship has been described as an evolutionary arms race. Host species that learn to recognise and reject strange eggs survive better, so cuckoos that lay more convincing eggs are favoured, and so on. Some host populations have become very good at detecting cuckoo eggs, while cuckoos in turn have evolved to lay their eggs very quickly, sometimes in only a few seconds.', 7, 600, NULL, '["brood parasitism", "host", "arms race", "eggs"]'::jsonb, NULL, 'Cuckoos lay their eggs in other birds'' nests, a strategy called brood parasitism, and the eggs often resemble those of the host. The cuckoo chick pushes out the host''s eggs or chicks and is raised by the hosts. This creates an evolutionary arms race, with hosts learning to reject strange eggs and cuckoos evolving more convincing eggs and very quick laying.', 'Key points to include: brood parasitism, host, arms race, eggs. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-40', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Dragonflies on the hunt', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Dragonflies are among the most successful hunters in the animal world. Studies have found that some species catch their prey in the vast majority of attempts, a success rate far higher than that of lions or sharks. Their secret lies partly in their flight. Each of their four wings can be controlled independently, allowing them to hover, change direction instantly and even fly backwards. But researchers believe their brains matter just as much. Rather than simply chasing their prey, dragonflies predict where it will go and fly on a course to intercept it, much as a fielder runs to where a ball will land. Specialised nerve cells help them track a single target while ignoring others in a swarm. Dragonflies have existed for hundreds of millions of years, and some ancient relatives had wingspans of around seventy centimetres. Engineers study their flight and targeting to design small drones.', 7, 600, NULL, '["dragonflies", "wings", "intercept", "drones"]'::jsonb, NULL, 'Dragonflies are extremely successful hunters, catching prey in most attempts. Independently controlled wings let them hover, turn instantly and fly backwards, and they predict where prey will go and intercept it, using specialised nerve cells to track one target in a swarm. They have ancient origins, and engineers study their flight and targeting to design small drones.', 'Key points to include: dragonflies, wings, intercept, drones. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-41', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Do dogs feel guilty?', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Many dog owners are convinced that their dogs look guilty when they have done something wrong, such as eating food from the table. In 2009, the researcher Alexandra Horowitz tested this belief. Owners were asked to leave the room after telling their dog not to eat a treat. In some cases the dog ate it; in others, the researcher removed it. When the owners returned, they were sometimes told, falsely, that the dog had eaten the treat. The dogs showed the so-called guilty look, lowering their heads and avoiding eye contact, most strongly when owners scolded them, whether or not they had actually eaten the treat. The study suggests that the guilty look is a response to the owner''s behaviour rather than evidence that the dog feels guilt about its actions. This does not mean dogs lack emotions, but it warns against assuming that animals interpret situations exactly as humans do.', 7, 600, NULL, '["guilty look", "scolded", "owner''s behaviour", "treat"]'::jsonb, NULL, 'A 2009 study by Alexandra Horowitz tested whether dogs look guilty after misbehaving. Dogs showed the guilty look most strongly when scolded by their owners, whether or not they had eaten a forbidden treat. This suggests the look is a response to the owner''s behaviour rather than a sign of guilt, warning against assuming animals interpret situations as humans do.', 'Key points to include: guilty look, scolded, owner''s behaviour, treat. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-42', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Under a polar bear''s fur', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Polar bears look white, but their fur is not actually white. Each hair is transparent and hollow, and it appears white because it scatters visible light, in the same way that snow and ice do. Underneath the thick fur, the bear''s skin is black, which may help it absorb heat from sunlight. A thick layer of fat provides further insulation, and polar bears are so well insulated that they can overheat when running. The idea that their hollow hairs channel sunlight down to the skin, like optical fibres, was once popular, but research has not supported it. Polar bears depend on sea ice to hunt seals, their main food, waiting at breathing holes in the ice. As Arctic sea ice forms later in autumn and melts earlier in spring, many bears must spend longer periods on land with little food, which is why they have become a symbol of the effects of climate change.', 7, 600, NULL, '["transparent", "black", "sea ice", "seals"]'::jsonb, NULL, 'Polar bear hairs are transparent and hollow, appearing white by scattering light, while the skin underneath is black and thick fat insulates the bears so well that they can overheat. The idea that hairs channel sunlight is unsupported. Bears need sea ice to hunt seals, and as the ice season shortens they spend longer on land with little food.', 'Key points to include: transparent, black, sea ice, seals. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-43', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Transparent frogs', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Glass frogs, found in the forests of Central and South America, have skin on their undersides so transparent that their hearts and other organs can be seen. When they rest on leaves during the day, their bodies look pale green and their outline is hard to see, which helps them avoid predators. There was a puzzle, however. Blood is red and should make the frogs easy to spot. In 2022, researchers used special imaging to study sleeping glass frogs and discovered that the animals remove most of the red blood cells from circulation and store them in their liver, which is covered by a reflective layer. This made the frogs two to three times more transparent while resting. When the frogs woke and became active, the red blood cells returned to circulation. Remarkably, the frogs do not seem to suffer from blood clots, and researchers hope to learn from this for medicine.', 7, 600, NULL, '["glass frogs", "transparent", "liver", "blood clots"]'::jsonb, NULL, 'Glass frogs have transparent undersides that help them hide on leaves. Red blood should make them visible, but a 2022 study found that sleeping frogs store most red blood cells in their reflective liver, becoming much more transparent, and release them on waking. They avoid blood clots while doing this, which researchers hope may help medical research.', 'Key points to include: glass frogs, transparent, liver, blood clots. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-44', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Hoverflies in disguise', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Many hoverflies have yellow and black stripes that make them look like wasps or bees, yet they cannot sting. This is an example of Batesian mimicry, named after the nineteenth-century naturalist Henry Walter Bates, who studied butterflies in the Amazon. A harmless species benefits by resembling a dangerous or unpleasant one, because predators that have learned to avoid the dangerous species will also avoid the mimic. The strategy works best when mimics are less common than the species they copy. If mimics become too common, predators may eat many of them without being stung, learn that the pattern is not always dangerous, and begin attacking both. Some hoverflies go beyond appearance, moving their legs in front of their heads to imitate a wasp''s long antennae, or buzzing in a similar way. Hoverflies are also important pollinators, and the larvae of some species eat aphids, making them useful in gardens.', 7, 600, NULL, '["Batesian mimicry", "predators", "rarer", "pollinators"]'::jsonb, NULL, 'Harmless hoverflies resemble stinging wasps, an example of Batesian mimicry, which protects mimics because predators avoid the dangerous model. It works best when mimics are rarer than the models; otherwise predators learn the pattern is harmless. Some hoverflies also copy wasp behaviour. Hoverflies are useful pollinators, and some larvae eat aphids, which helps gardeners.', 'Key points to include: Batesian mimicry, predators, rarer, pollinators. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-45', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Webb''s sunshield', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'The James Webb Space Telescope, launched in December 2021, observes the universe mainly in infrared light, which is emitted by warm objects. This allows it to see very distant galaxies, whose light has been stretched into the infrared, and to look through clouds of dust where stars are forming. But it creates a challenge: the telescope itself must be extremely cold, or its own heat would overwhelm the faint signals it is trying to detect. The solution is a sunshield about the size of a tennis court, made of five thin layers, which blocks heat from the Sun, Earth and Moon. The cold side of the telescope stays at around minus two hundred and thirty degrees Celsius. The telescope also orbits a point in space about one and a half million kilometres from Earth, where it can keep the Sun, Earth and Moon on the same side, behind its shield.', 7, 600, NULL, '["infrared", "sunshield", "cold", "distant galaxies"]'::jsonb, NULL, 'The James Webb Space Telescope observes mainly in infrared, letting it see very distant galaxies and through dust where stars form. Because its own heat would drown faint signals, a five-layer sunshield the size of a tennis court keeps it extremely cold, and it orbits far from Earth, keeping the Sun, Earth and Moon behind the shield.', 'Key points to include: infrared, sunshield, cold, distant galaxies. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-46', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Craters on the Moon', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Look at the Moon through binoculars and you will see countless craters, the scars of impacts by asteroids and comets over billions of years. The Earth has been struck just as often, and in fact more, because it is larger and its gravity is stronger. So why does the Earth have so few visible craters? The answer is that our planet constantly renews its surface. Wind, water and ice erode craters over time, plants cover them, and sediments bury them. Over longer periods, the movement of tectonic plates recycles large parts of the Earth''s crust. The Earth''s atmosphere also burns up many smaller objects before they reach the ground. The Moon has almost no atmosphere, no weather and no moving plates, so its craters can survive almost unchanged for billions of years. This makes the Moon a valuable record of the history of impacts in our part of the solar system.', 7, 600, NULL, '["craters", "erosion", "tectonic plates", "atmosphere"]'::jsonb, NULL, 'The Earth has been hit by asteroids and comets at least as often as the Moon, but its surface is constantly renewed by erosion, plants, sediments and moving tectonic plates, and its atmosphere burns up smaller objects. The Moon lacks an atmosphere, weather and moving plates, so its craters survive, preserving a long record of impacts.', 'Key points to include: craters, erosion, tectonic plates, atmosphere. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-47', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Musical chills', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Many people experience a shiver or chills when listening to a favourite piece of music. In 2011, researchers in Canada used brain imaging to study this experience. Participants brought music that reliably gave them chills. The researchers found that the brain released dopamine, a chemical associated with pleasure and reward, at the peak moments. Interestingly, dopamine was also released in the moments before the peak, as listeners anticipated what was coming. This suggests that part of the pleasure of music comes from expectation: a skilled composer creates tension and then either satisfies or surprises the listener''s predictions. Not everyone experiences musical chills, and studies suggest that people who do may differ in personality, tending to score higher on openness to experience. Some people even have a condition in which music gives them little or no pleasure, although they can still enjoy other rewards such as food.', 7, 600, NULL, '["chills", "dopamine", "anticipation", "expectation"]'::jsonb, NULL, 'A 2011 Canadian study found that the brain releases dopamine, linked to pleasure and reward, at the peak moments of music that gives listeners chills, and also just before, during anticipation. This suggests musical pleasure depends partly on expectation. Not everyone experiences chills, and some people gain little pleasure from music while still enjoying other rewards.', 'Key points to include: chills, dopamine, anticipation, expectation. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-48', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Frame rates in cinema', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Why are most films shown at twenty-four frames per second? In the silent era, films were shot at a range of speeds, often by cranking the camera by hand. When sound arrived in the late 1920s, the soundtrack was recorded on the same strip of film as the images, so the speed had to be fixed and consistent. Twenty-four frames per second was adopted as a compromise. It was fast enough to produce smooth motion and acceptable sound quality, but slow enough to keep the cost of film, which was expensive, under control. The standard has lasted for nearly a century, even though digital cameras could easily record faster. Some directors have experimented with higher frame rates, which make motion sharper, but many viewers found the result looked too much like television or video, and the slight blur of twenty-four frames has become part of what audiences think a film should look like.', 7, 600, NULL, '["frames per second", "sound", "compromise", "television"]'::jsonb, NULL, 'Silent films were shot at varying speeds, but sound required a fixed speed because the soundtrack was recorded on the film. Twenty-four frames per second was a compromise between smooth motion, sound quality and film costs. Although digital cameras can record faster, higher frame rates often looked like television to viewers, so the standard has survived.', 'Key points to include: frames per second, sound, compromise, television. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-49', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Singers behind the screen', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'In most Hindi films, the actors do not actually sing the songs they appear to perform. Instead, the songs are recorded by professional playback singers, and the actors mime to the recordings on screen. The practice became standard in the 1940s and 1950s, as studios realised that good actors were not always good singers. Some playback singers became among the most famous performers in India. Lata Mangeshkar, for example, recorded thousands of songs over a career lasting more than seven decades and was known across the country, even though audiences rarely saw her on screen. Songs are often released before the film, and their popularity can help a film succeed. Audiences are fully aware of the practice, and a successful partnership between a particular actor and a particular singer''s voice could become part of a star''s identity. In recent years, some actors have begun singing their own songs, but playback remains common.', 7, 600, NULL, '["playback singers", "mime", "Lata Mangeshkar", "songs"]'::jsonb, NULL, 'In most Hindi films, professional playback singers record the songs while actors mime on screen, a practice standard since the 1940s and 1950s because good actors were not always good singers. Singers such as Lata Mangeshkar became hugely famous. Songs released early can help films succeed, and although some actors now sing, playback remains common.', 'Key points to include: playback singers, mime, Lata Mangeshkar, songs. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-sst-50', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'summarize-spoken-text', 'Summarize Spoken Text', 'Timbuktu''s manuscripts', 'You will hear a short lecture. Write a summary for a fellow student who was not present at the lecture. You should write 50-70 words. You have 10 minutes to finish this task. Your response will be judged on the quality of your writing and on how well your response presents the key points presented in the lecture.', NULL, 'Timbuktu, in present-day Mali, was a major centre of trade and Islamic scholarship between the fourteenth and sixteenth centuries. Caravans crossing the Sahara brought gold, salt and books, and wealthy families built up private libraries of handwritten manuscripts on subjects including astronomy, medicine, law and mathematics. Many of these manuscripts survived for centuries, kept in family collections, often in difficult conditions. In 2012, armed groups occupied the city, and there were fears that the manuscripts would be destroyed. Librarians and families secretly packed hundreds of thousands of documents into metal trunks and smuggled them south to the capital, Bamako, by road and by river. Some manuscripts were burned, but the great majority were saved. Today scholars are working to preserve and digitise them, and they are helping to challenge the old view that Africa south of the Sahara had little written history before colonial times.', 7, 600, NULL, '["Timbuktu", "manuscripts", "Bamako", "written history"]'::jsonb, NULL, 'Timbuktu in Mali was a centre of trade and scholarship, and families kept private libraries of manuscripts on astronomy, medicine, law and mathematics. When armed groups occupied the city in 2012, librarians smuggled hundreds of thousands of manuscripts to Bamako, saving most of them. Scholars now preserve and digitise them, challenging the view that the region lacked written history.', 'Key points to include: Timbuktu, manuscripts, Bamako, written history. Model summary should be 50-70 words.', 'medium', 10, ARRAY['PTE', 'Original practice', 'Summarize Spoken Text']::text[], true),
    ('q-pl90-mcma-01', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The Dust Bowl', 'Which TWO causes of the Dust Bowl does the speaker mention?', NULL, 'In the 1930s, huge dust storms swept across the southern Great Plains of the United States, a period remembered as the Dust Bowl. In the decades before, farmers had ploughed up millions of hectares of native grassland to grow wheat. The deep roots of the prairie grasses had held the soil in place, even during dry spells. When a long drought arrived in the early 1930s, the exposed topsoil dried out and was carried away by strong winds. Some storms were so large that dust fell on cities on the east coast. Hundreds of thousands of people left the region, many travelling west to California in search of work. The government responded by creating a service to teach soil conservation, encouraging farmers to plough along the contours of the land, rotate crops and plant long rows of trees to break the wind.', 7, 90, '[{"id": "A", "text": "A sudden fall in grain prices"}, {"id": "B", "text": "The planting of long rows of trees"}, {"id": "C", "text": "Ploughing that removed the native grasses"}, {"id": "D", "text": "Heavy floods along major rivers"}, {"id": "E", "text": "A long period of drought"}]'::jsonb, '["C", "E"]'::jsonb, NULL, NULL, 'Options (C), (E) are correct. Grassland was ploughed up, and then drought dried out the exposed soil; the tree planting was part of the response.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-02', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The Irish famine', 'Which TWO statements about the famine are made by the speaker?', NULL, 'Between 1845 and 1852, Ireland suffered one of the worst famines in modern European history. The immediate cause was potato blight, a disease caused by a fungus-like organism that turned potatoes black and rotten in the ground. The disaster was so severe because a large part of the population, especially the rural poor, depended almost entirely on potatoes for food, and most farmers grew the same variety, which had little resistance. Around one million people died, and at least another million emigrated, many to Britain and North America. The famine remains a painful and controversial subject, partly because food, including grain and livestock, continued to be exported from Ireland while people starved, and many historians criticise the government''s response as inadequate. Ireland''s population has never returned to the level it reached before the famine.', 7, 90, '[{"id": "A", "text": "Many poor families depended heavily on a single crop"}, {"id": "B", "text": "Most emigrants travelled to Australia"}, {"id": "C", "text": "The population soon returned to its earlier level"}, {"id": "D", "text": "Food continued to be exported from Ireland during the famine"}, {"id": "E", "text": "The government banned the planting of potatoes"}, {"id": "F", "text": "The blight was caused by an insect pest"}]'::jsonb, '["A", "D"]'::jsonb, NULL, NULL, 'Options (A), (D) are correct. The rural poor relied almost entirely on potatoes, and food was still exported while people starved.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-03', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Moving the stones of Stonehenge', 'Which THREE statements are supported by the recording?', NULL, 'Stonehenge, in southern England, was built in several stages over more than a thousand years, beginning around five thousand years ago. One of its greatest puzzles is how the stones arrived. The smaller bluestones, each weighing a few tonnes, have been traced to hills in west Wales, over two hundred kilometres away. The huge sarsen stones, some weighing more than twenty tonnes, came from a much closer source. In 2020, a chemical analysis of a core drilled from one stone identified a likely origin in an area about twenty-five kilometres to the north. Nobody knows exactly how the stones were moved, since the builders left no written records. Experiments suggest that teams of people could have pulled them on wooden sledges running over timber tracks, and some researchers believe the bluestones may have travelled part of the way by water.', 7, 90, '[{"id": "A", "text": "The monument was built within a single decade"}, {"id": "B", "text": "The largest stones came from about twenty-five kilometres away"}, {"id": "C", "text": "Nobody knows exactly how the stones were moved"}, {"id": "D", "text": "The builders left detailed written records"}, {"id": "E", "text": "The smaller stones came from Wales"}, {"id": "F", "text": "All of the stones came from one quarry"}, {"id": "G", "text": "The stones were carried on horse-drawn carts"}]'::jsonb, '["B", "C", "E"]'::jsonb, NULL, NULL, 'Options (B), (C), (E) are correct. Bluestones came from Wales, the sarsens from about 25 km away, and the method of transport is unknown.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-04', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Who built the pyramids', 'Which TWO pieces of evidence suggest that the workers were not slaves?', NULL, 'For centuries, popular belief held that the pyramids of Egypt were built by huge numbers of slaves, an idea encouraged by ancient Greek writers and, much later, by Hollywood films. Archaeological discoveries near the pyramids at Giza have changed this picture. Since the 1990s, excavations have uncovered a settlement where workers lived, including bakeries and evidence that they ate large amounts of beef. Nearby, archaeologists found the tombs of workers, built close to the pyramids themselves, which would have been an honour unlikely to be given to slaves. Some skeletons show broken bones that had healed properly, suggesting that injured workers received medical care. Many researchers now believe the pyramids were built by a core of skilled, permanent craftsmen, supported by larger groups of labourers who worked in rotation, perhaps as a form of service owed to the state.', 7, 90, '[{"id": "A", "text": "Written contracts listed their wages"}, {"id": "B", "text": "Their healed bones suggest they received medical care"}, {"id": "C", "text": "They were buried in tombs close to the pyramids"}, {"id": "D", "text": "They were paid in gold coins"}, {"id": "E", "text": "They lived inside the pyramids during construction"}, {"id": "F", "text": "Greek historians praised their working conditions"}]'::jsonb, '["B", "C"]'::jsonb, NULL, NULL, 'Options (B), (C) are correct. Tombs near the pyramids and healed injuries point to honoured, cared-for workers.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-05', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Viking longships', 'Which TWO features allowed longships to reach places far from the coast or land without a harbour?', NULL, 'Viking longships were among the most advanced vessels of their time. They were built using overlapping wooden planks, a technique that made the hulls both strong and flexible, so they could bend with the waves rather than break. Crucially, the ships sat very low in the water, needing only about a metre of depth. This meant they could sail up rivers far inland and be pulled directly onto beaches, allowing raiders to arrive and leave quickly without a harbour. Longships carried a large square sail but also had oars, so crews could row when the wind dropped or when manoeuvring in narrow channels. The bow and stern were almost identical, so a ship could reverse direction without turning around. These vessels carried Norse explorers across the North Atlantic, and archaeological evidence confirms they reached North America around the year one thousand.', 7, 90, '[{"id": "A", "text": "They were carved from single hollow trees"}, {"id": "B", "text": "They could be pulled directly onto beaches"}, {"id": "C", "text": "They needed only shallow water to sail"}, {"id": "D", "text": "Their heavy keels kept them stable in deep water"}, {"id": "E", "text": "They were powered only by their sails"}]'::jsonb, '["B", "C"]'::jsonb, NULL, NULL, 'Options (B), (C) are correct. Needing about a metre of water, they could go up rivers and land on beaches.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-06', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Apollo 13', 'Which THREE statements about the mission are correct?', NULL, 'In April 1970, the Apollo 13 mission was on its way to the Moon when an oxygen tank in the service module exploded. The planned landing was immediately cancelled, and the priority became bringing the three astronauts home alive. The crew moved into the lunar module, the small craft intended for landing, and used it as a lifeboat, although it was designed to support only two people for about two days. A serious problem soon appeared. Carbon dioxide was building up in the cabin, and the square filters from the main spacecraft did not fit the round openings in the lunar module. Engineers on the ground designed a solution using only materials available on board, including plastic bags, cardboard and tape, and talked the crew through building it. After four tense days, the astronauts splashed down safely, and NASA later called the mission a successful failure.', 7, 90, '[{"id": "A", "text": "The crew used the lunar module as a lifeboat"}, {"id": "B", "text": "The crew returned to Earth within a few hours"}, {"id": "C", "text": "The astronauts repaired the oxygen tank on the Moon"}, {"id": "D", "text": "An adaptor for the air filters was made from materials on board"}, {"id": "E", "text": "A rescue spacecraft was launched to meet them"}, {"id": "F", "text": "The planned Moon landing was cancelled"}]'::jsonb, '["A", "D", "F"]'::jsonb, NULL, NULL, 'Options (A), (D), (F) are correct. The landing was cancelled, the lunar module became a lifeboat, and the filter adaptor was improvised.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-07', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'After the Tenerife collision', 'Which TWO changes followed the accident?', NULL, 'In 1977, two passenger jets collided on a foggy runway on the island of Tenerife, killing five hundred and eighty-three people in the deadliest accident in aviation history. Investigators found that a combination of factors was responsible. Visibility was very poor, radio messages were partly blocked and misunderstood, and one captain began his take-off without clear permission. Other members of his crew appear to have had doubts but did not challenge him forcefully. The disaster led to important changes. Standard radio phrases were tightened, so that the word take-off is now used only when a plane is actually cleared to take off. Airlines also introduced training known as crew resource management, which teaches pilots to work as a team and encourages junior crew members to speak up when they see a problem, however senior the captain. Hospitals and other high-risk workplaces have since adopted similar training.', 7, 90, '[{"id": "A", "text": "Training that encourages junior crew members to speak up"}, {"id": "B", "text": "Giving captains complete authority over every decision"}, {"id": "C", "text": "The permanent closure of the airport"}, {"id": "D", "text": "Stricter rules on when the word take-off may be used"}, {"id": "E", "text": "A ban on flights in foggy weather"}]'::jsonb, '["A", "D"]'::jsonb, NULL, NULL, 'Options (A), (D) are correct. Radio phrasing was tightened and crew resource management training was introduced.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-08', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Hubble''s blurred vision', 'Which TWO statements about the telescope are correct?', NULL, 'When the Hubble Space Telescope was launched in 1990, astronomers expected spectacular images. Instead, the first pictures were disappointingly blurry. Investigators discovered that the telescope''s main mirror had been ground to a slightly incorrect shape. The error was tiny, about one fiftieth of the width of a human hair, but for such a precise instrument it was enough to spoil the images. The mistake was traced to a faulty testing device used during manufacture. Because Hubble orbits the Earth, it could be reached by the space shuttle. In 1993, astronauts carried out a complex servicing mission and installed corrective optics that worked rather like glasses. The results were a dramatic success. Hubble went on to produce some of the most famous images in the history of astronomy and was serviced several more times over the following years.', 7, 90, '[{"id": "A", "text": "Its main mirror had been ground to a slightly wrong shape"}, {"id": "B", "text": "It was brought back to Earth for repair"}, {"id": "C", "text": "Astronauts installed corrective optics in 1993"}, {"id": "D", "text": "The error in the mirror was several centimetres wide"}, {"id": "E", "text": "The fault was caused by a collision with debris"}, {"id": "F", "text": "It was replaced by a completely new telescope"}]'::jsonb, '["A", "C"]'::jsonb, NULL, NULL, 'Options (A), (C) are correct. A tiny error in the mirror''s shape was fixed by corrective optics fitted in orbit.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-09', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The Harvard computers', 'Which TWO achievements does the speaker describe?', NULL, 'In the late nineteenth century, the director of the Harvard College Observatory hired a group of women to study thousands of photographic plates of the night sky. They were known as computers, because their job was to calculate and classify, and they were paid far less than male assistants would have been. Yet their work transformed astronomy. Annie Jump Cannon examined hundreds of thousands of stars and developed a system for classifying them by the features of their light, a system still taught today. Henrietta Swan Leavitt studied a type of star whose brightness rises and falls regularly, and found that the length of this cycle was linked to the star''s true brightness. This allowed astronomers to calculate distances to faraway stars, and it later helped Edwin Hubble show that the universe extends far beyond our own galaxy.', 7, 90, '[{"id": "A", "text": "A method for predicting solar eclipses"}, {"id": "B", "text": "A system for classifying stars that is still used"}, {"id": "C", "text": "The first photograph of another galaxy"}, {"id": "D", "text": "A discovery that helped measure distances in space"}, {"id": "E", "text": "The invention of the photographic telescope"}]'::jsonb, '["B", "D"]'::jsonb, NULL, NULL, 'Options (B), (D) are correct. Cannon''s classification system and Leavitt''s link between brightness cycles and distance.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-10', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Radar and the Battle of Britain', 'Which TWO advantages of the radar system are mentioned?', NULL, 'In the 1930s, the British government asked scientists whether a beam of radio waves could be used as a death ray to destroy enemy aircraft. The physicist Robert Watson-Watt concluded that this was impossible, but he suggested something more useful: radio waves could be used to detect aircraft. By the start of the Second World War, a chain of radar stations along the coast could spot approaching planes long before they arrived. The information was passed to operations rooms, where staff plotted the positions of aircraft on large maps and decided which fighter squadrons to send. This system meant that fighters did not need to patrol the skies constantly, wasting fuel and exhausting pilots. Instead, they could be sent exactly where they were needed. Many historians regard radar as a key factor in the Battle of Britain in 1940.', 7, 90, '[{"id": "A", "text": "It used a beam of energy to destroy aircraft"}, {"id": "B", "text": "It was developed after the war had ended"}, {"id": "C", "text": "It worked only in daylight"}, {"id": "D", "text": "It removed the need for fighter pilots"}, {"id": "E", "text": "It allowed fighters to be sent only where they were needed"}, {"id": "F", "text": "It detected aircraft long before they reached the coast"}]'::jsonb, '["E", "F"]'::jsonb, NULL, NULL, 'Options (E), (F) are correct. Early detection meant fighters could be directed exactly where needed.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-11', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Mosquitoes and malaria', 'Which TWO statements are supported by the recording?', NULL, 'The word malaria comes from the Italian for bad air, reflecting an old belief that the disease was caused by foul air rising from swamps. It was a reasonable guess, since malaria was common near marshes, but the real cause was not understood until the late nineteenth century. In 1880, a French army doctor saw tiny parasites in the blood of a patient. The next question was how the parasite passed from one person to another. In 1897 and 1898, Ronald Ross, a British doctor working in India, showed that mosquitoes carried the parasite and transmitted it through their bites, work that earned him a Nobel Prize. The discovery explained the link with swamps, where mosquitoes breed, and it led to practical measures such as draining standing water and sleeping under nets, which remain important today.', 7, 90, '[{"id": "A", "text": "The disease''s name reflects an old belief about bad air"}, {"id": "B", "text": "Ross carried out his research in South America"}, {"id": "C", "text": "Ross showed that mosquitoes transmit the parasite"}, {"id": "D", "text": "Malaria is caused by a virus in drinking water"}, {"id": "E", "text": "The discovery immediately produced a vaccine"}]'::jsonb, '["A", "C"]'::jsonb, NULL, NULL, 'Options (A), (C) are correct. Malaria means bad air, and Ross proved mosquitoes spread the parasite.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-12', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Bacteria in the gut', 'Which THREE roles of gut bacteria does the speaker mention?', NULL, 'The human gut is home to trillions of microorganisms, mostly bacteria, together known as the gut microbiome. For a long time these organisms received little attention, but research over the past two decades has shown that they play important roles in our health. Many of them break down types of dietary fibre that our own digestive system cannot process, producing substances that nourish the cells lining the gut. Some bacteria produce vitamins, such as vitamin K. The microbiome also appears to help train the immune system. The composition of these communities varies greatly between people and is shaped by diet, environment and medicines. A course of antibiotics, for example, can temporarily reduce their diversity. Researchers are also investigating possible links between gut bacteria and mood, but many of these findings are still at an early stage and should be treated with caution.', 7, 90, '[{"id": "A", "text": "Breaking down fibre we cannot digest"}, {"id": "B", "text": "Controlling body temperature"}, {"id": "C", "text": "Producing certain vitamins"}, {"id": "D", "text": "Protecting the body against all infections"}, {"id": "E", "text": "Producing insulin"}, {"id": "F", "text": "Helping to train the immune system"}]'::jsonb, '["A", "C", "F"]'::jsonb, NULL, NULL, 'Options (A), (C), (F) are correct. Fibre digestion, vitamin production and immune training are all mentioned.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-13', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'How bacteria resist antibiotics', 'Which THREE statements are made in the recording?', NULL, 'When Alexander Fleming accepted the Nobel Prize for the discovery of penicillin in 1945, he warned that misuse of the drug could allow bacteria to become resistant. His warning proved accurate. Bacteria reproduce very quickly, and random changes in their genes occasionally make some of them less vulnerable to a particular antibiotic. When the drug is used, it kills the vulnerable bacteria, but the resistant ones survive and multiply. Bacteria can also pass genes for resistance directly to one another, even across different species, which allows resistance to spread rapidly. Every use of antibiotics creates pressure for resistance, so unnecessary use is particularly harmful. Antibiotics have no effect on viral infections such as colds and flu, yet they have often been prescribed for them. Large quantities have also been used in farming to help animals grow faster, a practice now restricted in many countries.', 7, 90, '[{"id": "A", "text": "Resistance develops only in hospitals"}, {"id": "B", "text": "Prescribing antibiotics for viral infections adds to the problem"}, {"id": "C", "text": "Bacteria can pass resistance genes to one another"}, {"id": "D", "text": "Antibiotics work well against colds and flu"}, {"id": "E", "text": "Fleming believed resistance could never happen"}, {"id": "F", "text": "Antibiotics have been used to make farm animals grow faster"}]'::jsonb, '["B", "C", "F"]'::jsonb, NULL, NULL, 'Options (B), (C), (F) are correct. Gene sharing, unnecessary use for viral infections and use in farming are all described.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-14', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Caffeine and sleepiness', 'Which TWO statements about caffeine are correct according to the speaker?', NULL, 'Why does coffee make us feel more alert? During the hours we are awake, a chemical called adenosine gradually builds up in the brain. As it attaches to receptors on nerve cells, it creates a growing sense of sleepiness. Caffeine has a similar shape to adenosine, so it can occupy these receptors without activating them, effectively blocking the signal that tells us we are tired. Caffeine does not provide energy in the way food does; it simply masks fatigue. Its effects also last longer than many people realise. In a typical adult, it takes around five hours for the body to remove half of the caffeine consumed, so an afternoon coffee may still affect sleep at night. People who drink coffee every day also develop tolerance, meaning they need more to feel the same effect, and they may experience headaches if they suddenly stop.', 7, 90, '[{"id": "A", "text": "It blocks a chemical signal that makes us feel sleepy"}, {"id": "B", "text": "It can affect sleep many hours after it is drunk"}, {"id": "C", "text": "It leaves the body within about an hour"}, {"id": "D", "text": "Regular drinkers become more sensitive to it over time"}, {"id": "E", "text": "It gives the body extra energy in the form of calories"}]'::jsonb, '["A", "B"]'::jsonb, NULL, NULL, 'Options (A), (B) are correct. Caffeine blocks adenosine receptors, and half of it remains after about five hours.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-15', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Sunlight and vitamin D', 'Which TWO statements about vitamin D are made?', NULL, 'Vitamin D is unusual among vitamins because the body can make it for itself. When ultraviolet light from the sun reaches the skin, it triggers a chemical reaction that produces vitamin D. The vitamin helps the body absorb calcium from food, which is essential for strong bones. A severe lack of it in childhood can cause rickets, a condition in which bones become soft and bend. In countries far from the equator, the winter sun is too low in the sky for its ultraviolet rays to be strong enough to produce vitamin D, even on a clear day. People with darker skin, which contains more of the pigment that protects against ultraviolet light, generally need longer in the sun to make the same amount. For these reasons, some health authorities advise people to take supplements during winter, while oily fish and eggs provide smaller amounts through diet.', 7, 90, '[{"id": "A", "text": "People with darker skin need less sunlight to produce it"}, {"id": "B", "text": "Winter sunlight far from the equator may be too weak to produce it"}, {"id": "C", "text": "It is made in the liver from sugar"}, {"id": "D", "text": "It is found mainly in green vegetables"}, {"id": "E", "text": "It helps the body absorb calcium"}]'::jsonb, '["B", "E"]'::jsonb, NULL, NULL, 'Options (B), (E) are correct. It aids calcium absorption, and weak winter sun at high latitudes cannot produce it.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-16', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Walking and new ideas', 'Which TWO findings are reported?', NULL, 'Many writers and thinkers have claimed that they think best while walking. In 2014, researchers at Stanford University tested this idea. Participants were asked to think of creative uses for everyday objects, such as a button or a tyre, either while sitting or while walking. Most people produced considerably more ideas when walking. Surprisingly, it did not matter whether they walked outdoors or on a treadmill facing a blank wall inside a small room; the act of walking itself seemed to be what mattered. The benefit also continued for a short time after participants sat down again. However, walking did not help with every kind of thinking. On tasks that required finding one correct answer, rather than generating many possibilities, walkers performed no better than those who were sitting. The researchers suggested that a walk might be most useful at the start of a project, when new ideas are needed.', 7, 90, '[{"id": "A", "text": "Walking on a treadmill indoors also increased the number of ideas"}, {"id": "B", "text": "Participants produced fewer ideas while walking"}, {"id": "C", "text": "Only walking outdoors in nature had any effect"}, {"id": "D", "text": "Walking did not help with problems that have one correct answer"}, {"id": "E", "text": "The benefit disappeared the moment people sat down"}]'::jsonb, '["A", "D"]'::jsonb, NULL, NULL, 'Options (A), (D) are correct. The treadmill worked as well as outdoors, but convergent tasks did not improve.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-17', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Why we sweat', 'Which TWO statements are supported by the recording?', NULL, 'Humans are unusually good at sweating. We have millions of sweat glands spread across the skin, far more than most other mammals, and in hot conditions we can lose more than a litre of sweat an hour. Sweat itself does not cool us; the cooling comes when it evaporates, because turning liquid water into vapour takes heat from the skin. This is why humid weather can be dangerous. When the air already contains a lot of moisture, sweat evaporates slowly, and it drips off the body instead of cooling it. Many other animals rely on different methods. Dogs, for example, have few sweat glands and cool down mainly by panting. Some researchers believe our ability to sweat helped early humans hunt by running long distances in the heat, chasing animals until they were exhausted, although this idea is still debated.', 7, 90, '[{"id": "A", "text": "Humans have fewer sweat glands than most mammals"}, {"id": "B", "text": "Sweat cools the body as it evaporates"}, {"id": "C", "text": "Dogs cool down mainly by sweating through their fur"}, {"id": "D", "text": "Humid air makes sweating less effective"}, {"id": "E", "text": "Scientists agree that sweating evolved for hunting"}]'::jsonb, '["B", "D"]'::jsonb, NULL, NULL, 'Options (B), (D) are correct. Cooling comes from evaporation, which slows in humid air.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-18', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The eel''s life cycle', 'Which TWO statements about European eels are correct?', NULL, 'The European eel has one of the strangest life cycles of any fish. For centuries, nobody knew where eels came from, because no one had ever found eel eggs in European rivers. In the early twentieth century, a Danish scientist followed ever smaller eel larvae across the Atlantic and concluded that they hatch in the Sargasso Sea, a region of the western Atlantic. The tiny, leaf-shaped larvae drift on ocean currents for months or even years until they reach the coasts of Europe, where they turn into young eels and swim up rivers. There they may live for decades before making the long journey back across the ocean to breed, after which they die. Remarkably, no one has ever observed eels spawning in the wild. The species is now critically endangered, and scientists are still trying to understand all the reasons for its decline.', 7, 90, '[{"id": "A", "text": "Their larvae drift across the Atlantic to reach Europe"}, {"id": "B", "text": "Nobody has observed them spawning in the wild"}, {"id": "C", "text": "Their numbers have increased in recent decades"}, {"id": "D", "text": "They spend their whole lives in the Sargasso Sea"}, {"id": "E", "text": "Adults return to European rivers after breeding"}]'::jsonb, '["A", "B"]'::jsonb, NULL, NULL, 'Options (A), (B) are correct. Larvae drift to Europe, and spawning has never been observed.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-19', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The coelacanth', 'Which TWO statements about the coelacanth are made?', NULL, 'Until 1938, the coelacanth was known only from fossils, and scientists believed it had died out around the same time as the dinosaurs. Then, in December of that year, a fishing boat off the coast of South Africa brought up a strange, large blue fish. A local museum curator, Marjorie Courtenay-Latimer, recognised that it was unusual and contacted a scientist, who identified it as a living coelacanth. The discovery caused a sensation. The fish has thick, fleshy fins that move in a pattern resembling the legs of land animals, which makes it important for understanding how vertebrates moved onto land. A second species was found in Indonesia in 1997. The coelacanth is often called a living fossil, but scientists point out that the term is misleading, because modern coelacanths are not identical to their ancient relatives.', 7, 90, '[{"id": "A", "text": "It was first discovered by deep-sea divers"}, {"id": "B", "text": "A second species was later found in Indonesia"}, {"id": "C", "text": "It lives mainly in freshwater lakes"}, {"id": "D", "text": "It was known from fossils before a living one was found"}, {"id": "E", "text": "It has not changed at all for millions of years"}]'::jsonb, '["B", "D"]'::jsonb, NULL, NULL, 'Options (B), (D) are correct. It was known only as a fossil until 1938, and a second species appeared in 1997.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-20', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Squid of the deep', 'Which TWO statements about the giant squid are correct?', NULL, 'For centuries, sailors told stories of enormous sea monsters with long arms, and the giant squid may lie behind some of these legends. Dead specimens occasionally washed ashore, showing that the animals could grow to well over ten metres including their tentacles, but no one had seen one alive in the deep ocean. The first photographs of a living giant squid in its natural habitat were taken by Japanese researchers in 2004. In 2012, a team finally filmed one in the deep sea. Their success depended on being quiet and subtle: instead of bright lights and noisy vehicles, they used a camera with dim red light and a lure that imitated the glow of a jellyfish in distress, which may attract predators. Giant squid also have some of the largest eyes in the animal kingdom, about the size of a dinner plate.', 7, 90, '[{"id": "A", "text": "Its eyes are among the smallest of any squid"}, {"id": "B", "text": "A lure imitating a glowing jellyfish helped attract it"}, {"id": "C", "text": "It was first photographed alive in its habitat in 2004"}, {"id": "D", "text": "It was captured and kept in an aquarium"}, {"id": "E", "text": "It was filmed from a noisy vehicle with bright lights"}]'::jsonb, '["B", "C"]'::jsonb, NULL, NULL, 'Options (B), (C) are correct. Photographs came in 2004, and a quiet camera with a jellyfish-like lure filmed it later.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-21', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The narwhal''s tusk', 'Which TWO statements are made about narwhal tusks?', NULL, 'The narwhal is a medium-sized whale that lives in the Arctic Ocean, and it is best known for the long spiral tusk that grows from the heads of most males. The tusk is in fact a tooth, which can grow to around three metres in length. In medieval Europe, narwhal tusks were brought back by traders and sold as the horns of unicorns, fetching extraordinary prices because they were believed to have magical powers. The true purpose of the tusk has long been debated. It contains millions of nerve endings, leading some scientists to suggest it can sense changes in the water around it. Others believe it plays a role in competition between males, who may display their tusks to attract females. In 2017, drone footage even showed narwhals using their tusks to tap and stun small fish before eating them.', 7, 90, '[{"id": "A", "text": "Narwhals live mainly in tropical waters"}, {"id": "B", "text": "Only female narwhals have tusks"}, {"id": "C", "text": "Scientists agree the tusk is used only for fighting"}, {"id": "D", "text": "Tusks were once sold in Europe as unicorn horns"}, {"id": "E", "text": "The tusk is actually a very long tooth"}]'::jsonb, '["D", "E"]'::jsonb, NULL, NULL, 'Options (D), (E) are correct. The tusk is a tooth, and medieval traders sold tusks as unicorn horns.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-22', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Built for speed', 'Which THREE statements about cheetahs are correct?', NULL, 'The cheetah is the fastest land animal, capable of reaching around one hundred kilometres an hour in a few seconds. Its body is built for speed: it has a light frame, long legs and an unusually flexible spine that stretches and bends with each stride, lengthening its step. Unlike most cats, it cannot fully retract its claws, which grip the ground like the spikes on a sprinter''s shoes. Its long tail acts as a counterbalance, helping it change direction sharply when chasing prey. However, speed has costs. A chase usually lasts less than a minute, because the cheetah quickly becomes exhausted and overheated. After a successful hunt, it often needs to rest before eating, and during this time larger predators such as lions and hyenas may steal its kill. As a result, cheetahs lose a significant share of the food they catch.', 7, 90, '[{"id": "A", "text": "It hunts mainly at night in dense forest"}, {"id": "B", "text": "It can keep its top speed for several kilometres"}, {"id": "C", "text": "Its tail helps it balance during sharp turns"}, {"id": "D", "text": "Its claws retract fully like a house cat''s"}, {"id": "E", "text": "It often loses its prey to larger predators"}, {"id": "F", "text": "Its claws grip the ground like running spikes"}]'::jsonb, '["C", "E", "F"]'::jsonb, NULL, NULL, 'Options (C), (E), (F) are correct. The tail balances turns, the claws grip like spikes, and lions or hyenas often steal kills.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-23', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'How kangaroos hop', 'Which TWO statements about kangaroos are made?', NULL, 'Hopping looks like a tiring way to travel, but for large kangaroos it is remarkably efficient. When a kangaroo lands, the long tendons in its hind legs stretch and store elastic energy, rather like springs. This energy is released in the next jump, so the muscles do not have to do all the work. Studies in the 1970s found that, above a certain speed, a hopping kangaroo uses hardly any extra energy as it goes faster. This is very different from animals that run on four legs, which use more and more energy as their speed increases. At slow speeds, however, hopping is less practical. When feeding, kangaroos move in a slower way, using their powerful tail as a kind of fifth leg, supporting their weight while they swing their hind legs forward. Their body shape also makes it very difficult for them to move backwards.', 7, 90, '[{"id": "A", "text": "Their muscles do all the work without help from tendons"}, {"id": "B", "text": "At slow speeds they use their tail like an extra leg"}, {"id": "C", "text": "They escape danger by walking backwards"}, {"id": "D", "text": "Going faster costs them hardly any extra energy above a certain speed"}, {"id": "E", "text": "Hopping uses more energy than running on four legs"}]'::jsonb, '["B", "D"]'::jsonb, NULL, NULL, 'Options (B), (D) are correct. Stored tendon energy makes fast hopping cheap, and the tail acts as a fifth leg when slow.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-24', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Homing pigeons', 'Which TWO methods of navigation does the speaker mention?', NULL, 'Homing pigeons can return to their lofts from places hundreds of kilometres away, even if they have never visited them before. How they do this is still not fully understood. Experiments suggest that they use several different cues. On sunny days, pigeons can use the position of the sun as a compass, adjusting for the time of day with an internal clock. When the sky is overcast, they still manage to navigate, and many researchers believe they can sense the Earth''s magnetic field. Some Italian studies found that pigeons with an impaired sense of smell struggled to find their way, suggesting that odours carried by the wind may form part of a map. Close to home, familiar landmarks become important. Tracking studies have even shown pigeons following motorways and turning at major junctions, much as a human driver would.', 7, 90, '[{"id": "A", "text": "Following the calls of other birds"}, {"id": "B", "text": "Relying only on their sense of hearing"}, {"id": "C", "text": "Waiting for clear skies before flying"}, {"id": "D", "text": "Following roads and familiar landmarks near home"}, {"id": "E", "text": "Using the position of the sun"}]'::jsonb, '["D", "E"]'::jsonb, NULL, NULL, 'Options (D), (E) are correct. The sun compass and familiar landmarks, including motorways, are both described.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-25', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Dogs that detect disease', 'Which TWO statements are made in the recording?', NULL, 'A dog''s sense of smell is far more sensitive than ours, and researchers have been investigating whether dogs can detect diseases by their odour. Many illnesses change the chemical compounds our bodies release, sometimes in tiny amounts. Trained dogs have been used to alert people with diabetes when their blood sugar falls to dangerous levels, and studies have tested dogs'' ability to identify certain cancers and infections from samples of breath, urine or clothing. Some results have been impressive, but there are practical challenges. Training a detection dog takes time and money, dogs can become tired or distracted, and individual dogs perform differently. For these reasons, many scientists see the dogs not as a replacement for medical tests, but as a guide. By identifying the chemicals the dogs are responding to, researchers hope to design electronic devices that can detect them in the same way.', 7, 90, '[{"id": "A", "text": "Training detection dogs is quick and cheap"}, {"id": "B", "text": "Most hospitals already use dogs to diagnose cancer"}, {"id": "C", "text": "All dogs perform equally well after training"}, {"id": "D", "text": "Dogs have been trained to detect low blood sugar"}, {"id": "E", "text": "Researchers hope to build devices that copy dogs'' abilities"}]'::jsonb, '["D", "E"]'::jsonb, NULL, NULL, 'Options (D), (E) are correct. Dogs alert people with diabetes, and scientists want electronic devices that detect the same chemicals.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-26', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Wildcats and grain stores', 'Which TWO statements about the domestication of cats are correct?', NULL, 'Unlike dogs, which people may have actively tamed, cats seem to have largely domesticated themselves. Genetic studies suggest the process began around ten thousand years ago in the Near East, when people started farming and storing grain. The stores attracted mice and rats, and these in turn attracted wildcats. Cats that were less fearful of people could take advantage of this new source of food, and farmers had good reason to tolerate them. Some of the earliest evidence of a close bond comes from a grave on the island of Cyprus, around nine and a half thousand years old, where a person was buried with a cat. Ancient Egypt later played an important role in spreading tame cats and celebrating them in art. Even today, domestic cats remain genetically quite similar to their wild relatives, and many can still survive perfectly well without human help.', 7, 90, '[{"id": "A", "text": "Stored grain attracted mice, which drew wildcats to settlements"}, {"id": "B", "text": "People captured wildcats to guard their homes"}, {"id": "C", "text": "Domestic cats remain genetically similar to wildcats"}, {"id": "D", "text": "The oldest evidence comes from a burial in China"}, {"id": "E", "text": "Cats were first domesticated in ancient Egypt"}]'::jsonb, '["A", "C"]'::jsonb, NULL, NULL, 'Options (A), (C) are correct. Grain stores drew rodents and then wildcats, and domestic cats are still close to wild ones.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-27', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Vampire bat cooperation', 'Which TWO statements are supported by the recording?', NULL, 'Vampire bats feed only on blood, and their lives are finely balanced. A bat that fails to find a meal for two or three nights in a row is at serious risk of starving. On any given night, some bats return to the roost hungry. Researchers have observed that well-fed bats often regurgitate some of their meal to feed these hungry companions. This sharing is not limited to close relatives. Long-term studies have found that bats are more likely to share with individuals that have shared with them in the past, a pattern that looks like a system of mutual help. In experiments, bats that had built up a wider network of sharing partners were better protected when one partner was unavailable. The findings make vampire bats an important example for scientists studying how cooperation develops among animals that are not related.', 7, 90, '[{"id": "A", "text": "Bats are more likely to share with those that shared with them"}, {"id": "B", "text": "Sharing food weakens a bat''s ability to hunt"}, {"id": "C", "text": "A bat that fails to feed for a few nights may starve"}, {"id": "D", "text": "Only closely related bats share food"}, {"id": "E", "text": "Vampire bats feed mainly on fruit"}]'::jsonb, '["A", "C"]'::jsonb, NULL, NULL, 'Options (A), (C) are correct. Missing a few meals is dangerous, and sharing follows past help.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-28', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Bees and static charge', 'Which TWO statements are made about bumblebees?', NULL, 'As a bumblebee flies, friction with the air gives its body a small positive electric charge. Flowers, meanwhile, tend to carry a slight negative charge. When a bee lands on a flower, some of the charge is transferred, and the electric field around the flower changes for a short time. In 2013, researchers in Britain showed that bumblebees can detect these electric fields and learn to use them. In experiments with artificial flowers, bees learned to tell rewarding flowers from unrewarding ones using electric fields alone. Later work suggested that the bees sense the fields through tiny hairs on their bodies, which move in response. This could help a bee avoid wasting time on a flower whose nectar has just been taken by another insect. It is a reminder that animals may perceive the world through senses we are only beginning to understand.', 7, 90, '[{"id": "A", "text": "They may sense whether a flower has just been visited"}, {"id": "B", "text": "They sense electric fields through their eyes"}, {"id": "C", "text": "They carry a different charge from flowers"}, {"id": "D", "text": "They produce electricity to attract mates"}, {"id": "E", "text": "Flowers give them electric shocks to keep them away"}]'::jsonb, '["A", "C"]'::jsonb, NULL, NULL, 'Options (A), (C) are correct. Bees are positively charged and flowers negatively, and a recent visit changes the field.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-29', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Clownfish and anemones', 'Which THREE statements about clownfish are correct?', NULL, 'Clownfish live among the tentacles of sea anemones, which are covered in stinging cells that can paralyse other small fish. Clownfish are protected by a layer of mucus on their skin, which appears to stop the anemone from firing its stinging cells. The relationship benefits both animals. The anemone provides the clownfish with shelter from predators, while the clownfish chases away fish that might eat the anemone, and its waste may provide the anemone with nutrients. Clownfish also have an unusual social structure. Each anemone is usually home to a group led by a single breeding female, the largest fish, and a breeding male. All clownfish are born male. If the female dies, the breeding male changes sex and becomes female, and the next largest fish takes his place. This detail of their biology would change the story of a famous animated film considerably.', 7, 90, '[{"id": "A", "text": "A coating of mucus protects them from stings"}, {"id": "B", "text": "The anemone gains nothing from the relationship"}, {"id": "C", "text": "They chase away fish that would eat the anemone"}, {"id": "D", "text": "A breeding male can change into a female"}, {"id": "E", "text": "All clownfish are born female"}, {"id": "F", "text": "They feed on the anemone''s tentacles"}]'::jsonb, '["A", "C", "D"]'::jsonb, NULL, NULL, 'Options (A), (C), (D) are correct. Mucus protects them, they defend the anemone, and the male becomes female if she dies.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-30', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Figs and their wasps', 'Which TWO statements about figs are made?', NULL, 'A fig is not really a fruit in the usual sense. It is a hollow structure lined on the inside with hundreds of tiny flowers, hidden from view. This creates a problem: how can the flowers be pollinated? The answer is a remarkable partnership with tiny insects called fig wasps. A female wasp, carrying pollen, squeezes through a narrow opening into the fig, often losing her wings in the process. Inside, she pollinates the flowers and lays her eggs, and then she dies. Her offspring develop inside the fig, and new females leave carrying pollen to another fig. Many fig species rely on their own particular species of wasp, and neither could reproduce without the other. Because fig trees produce fruit throughout the year, they are an essential source of food for many birds, bats and monkeys in tropical forests.', 7, 90, '[{"id": "A", "text": "Their flowers are hidden inside them"}, {"id": "B", "text": "Figs are rarely eaten by wild animals"}, {"id": "C", "text": "Many fig species depend on their own species of wasp"}, {"id": "D", "text": "The wasps enter figs to hide from predators"}, {"id": "E", "text": "Fig wasps are pests that destroy the fruit"}]'::jsonb, '["A", "C"]'::jsonb, NULL, NULL, 'Options (A), (C) are correct. The flowers line the inside of the fig, and fig and wasp species depend on each other.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-31', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Orchids that deceive', 'Which TWO statements about orchids are correct?', NULL, 'Most flowering plants offer pollinators a reward, such as nectar or pollen, in exchange for carrying pollen from one flower to another. A surprising number of orchids, however, offer nothing at all. Estimates suggest that around a third of orchid species attract insects through deception. Some produce bright colours and shapes that resemble nectar-rich flowers, even though they contain no nectar. Others are even more elaborate. Certain orchids produce a scent that closely imitates the chemical signals released by female insects, and their flowers may even look like the female. Male insects are attracted, try to mate with the flower, and pick up pollen, which they then carry to the next orchid that deceives them. The strategy works because the insects are deceived only occasionally, but it does mean that such orchids often depend on a single species of insect for their survival.', 7, 90, '[{"id": "A", "text": "Some imitate the scent of female insects"}, {"id": "B", "text": "Deceptive orchids attract many different insect species"}, {"id": "C", "text": "Some offer insects no reward at all"}, {"id": "D", "text": "They are pollinated mainly by the wind"}, {"id": "E", "text": "They produce more nectar than any other flowers"}]'::jsonb, '["A", "C"]'::jsonb, NULL, NULL, 'Options (A), (C) are correct. About a third deceive their pollinators, some by imitating female insects.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-32', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Sunflowers and the sun', 'Which TWO findings does the speaker report?', NULL, 'Young sunflowers really do follow the sun. During the day, the growing plants gradually turn from east to west, and at night they swing back to face east, ready for sunrise. Research published in 2016 showed that this movement is controlled partly by the plant''s internal clock, which allows it to anticipate the sun''s position rather than simply react to it. The turning is produced by the stem growing faster on one side than on the other. Once the plants mature and their flowers open, they stop moving and most end up facing east. The researchers found that this has an advantage. East-facing flowers warm up more quickly in the morning sun, and warm flowers attract more visits from bees and other pollinators than flowers that face west. So the direction a sunflower faces may have a direct effect on its success in producing seeds.', 7, 90, '[{"id": "A", "text": "West-facing plants produced the most seeds"}, {"id": "B", "text": "East-facing mature flowers attract more bees"}, {"id": "C", "text": "Mature flower heads follow the sun all day"}, {"id": "D", "text": "Young plants turn back towards the east at night"}, {"id": "E", "text": "Sunflowers turn only in response to rainfall"}]'::jsonb, '["B", "D"]'::jsonb, NULL, NULL, 'Options (B), (D) are correct. Young plants reset overnight, and warm east-facing flowers get more pollinator visits.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-33', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The baobab tree', 'Which TWO statements about baobabs are made?', NULL, 'The baobab tree, found across the dry savannahs of Africa, is famous for its enormous, swollen trunk. The trunk stores large quantities of water, which helps the tree survive long dry seasons, and it may lose its leaves for much of the year to reduce water loss. Baobabs can live for well over a thousand years, and some hollow trunks have been used by people as shelters and storage rooms. The trees are also valuable for food: the fruit contains a dry pulp that is rich in vitamin C. In 2018, researchers who had been dating the oldest baobabs reported that several of the largest and most ancient trees had died or lost their oldest parts within the previous decade. They suggested that changes in climate might be involved, but they stressed that more research was needed to be sure.', 7, 90, '[{"id": "A", "text": "Their trunks can store large amounts of water"}, {"id": "B", "text": "Scientists know exactly why the old trees died"}, {"id": "C", "text": "Their fruit contains no vitamins"}, {"id": "D", "text": "Several of the oldest trees have recently died"}, {"id": "E", "text": "They grow mainly in cold mountain regions"}]'::jsonb, '["A", "D"]'::jsonb, NULL, NULL, 'Options (A), (D) are correct. The trunk stores water, and many of the oldest trees died within a decade.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-34', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'How dandelion seeds fly', 'Which TWO statements are made about the dandelion''s parachute?', NULL, 'Each dandelion seed hangs beneath a tiny parachute made of around one hundred fine bristles. Surprisingly, this parachute is mostly empty space, yet it keeps the seed airborne so effectively that seeds can travel long distances on the wind. In 2018, researchers in Scotland used wind tunnels to discover how it works. They found that as air flows through the gaps between the bristles, it forms a stable ring of swirling air that sits just above the parachute without being carried away. This ring lowers the pressure above the seed and helps slow its fall. The researchers calculated that the bristle structure is several times more efficient, for its weight, than a solid disc of the same size would be. The discovery has interested engineers who design very small flying devices, which need to stay in the air using as little material and energy as possible.', 7, 90, '[{"id": "A", "text": "A solid disc of the same size would work better"}, {"id": "B", "text": "Its bristles are joined by a thin skin"}, {"id": "C", "text": "It is lifted only by warm air rising from the ground"}, {"id": "D", "text": "It is mostly empty space"}, {"id": "E", "text": "A ring of swirling air above it helps it stay aloft"}]'::jsonb, '["D", "E"]'::jsonb, NULL, NULL, 'Options (D), (E) are correct. The open bristles create a stable swirling ring that slows the fall.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-35', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Rolling tumbleweeds', 'Which TWO statements about tumbleweeds are correct?', NULL, 'In Western films, tumbleweeds rolling across an empty town have become a symbol of the American frontier. A tumbleweed is the dried upper part of certain plants that, once mature, breaks away from its roots and is blown along by the wind. As it tumbles, it scatters its seeds across a wide area, and a single large plant can release many thousands. Ironically, one of the best-known tumbleweeds in North America, the Russian thistle, is not native there. It is believed to have arrived in the late nineteenth century, mixed in with a shipment of crop seeds brought by farmers from Eastern Europe. It spread rapidly across the plains. Today tumbleweeds can be a real nuisance, piling up against fences and houses, blocking roads, and sometimes presenting a fire risk when they collect in large numbers.', 7, 90, '[{"id": "A", "text": "They scatter seeds as they roll"}, {"id": "B", "text": "They are native to every continent"}, {"id": "C", "text": "They move only when pushed by animals"}, {"id": "D", "text": "One well-known species arrived in North America by accident"}, {"id": "E", "text": "They are the seeds of a single desert tree"}]'::jsonb, '["A", "D"]'::jsonb, NULL, NULL, 'Options (A), (D) are correct. Rolling spreads the seeds, and the Russian thistle arrived mixed in with crop seeds.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-36', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Dwarf elephants', 'Which TWO statements are supported by the recording?', NULL, 'When animals become isolated on islands, their body size often changes over many generations. Large animals frequently become smaller, a pattern known as island dwarfism. Fossils show that elephants living on several Mediterranean islands, including Sicily and Malta, evolved into dwarf forms, some only about a metre tall. Scientists think that limited food on small islands favoured smaller bodies, which need less energy, and that the absence of large predators removed one of the advantages of being big. The opposite can happen to small animals, which sometimes grow larger than their mainland relatives, a pattern called island gigantism. Examples include giant rats and lizards on certain islands. The discovery of fossils of a small human species on the Indonesian island of Flores has led some researchers to ask whether similar processes may even have affected our own relatives.', 7, 90, '[{"id": "A", "text": "Small animals on islands sometimes become larger"}, {"id": "B", "text": "Some island elephants became much smaller than their ancestors"}, {"id": "C", "text": "All island animals become smaller over time"}, {"id": "D", "text": "Islands usually provide more food than the mainland"}, {"id": "E", "text": "Dwarf elephants still live in the Mediterranean"}, {"id": "F", "text": "Large predators are common on small islands"}]'::jsonb, '["A", "B"]'::jsonb, NULL, NULL, 'Options (A), (B) are correct. Dwarf elephants and giant rats and lizards illustrate both patterns.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-37', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Tortoises of the Galápagos', 'Which THREE statements are made in the recording?', NULL, 'Giant tortoises once lived in huge numbers on the Galápagos Islands. Their ability to survive for many months without food or water proved disastrous for them. From the seventeenth century onwards, sailors and whalers collected thousands of tortoises and stored them alive in the holds of their ships, providing a supply of fresh meat on long voyages. Later, settlers and the animals they introduced added to the damage. Goats, in particular, ate much of the vegetation the tortoises relied on. Several species became extinct. One famous tortoise, known as Lonesome George, was the last known member of his species when he died in 2012. Conservation programmes have since removed goats from several islands and bred tortoises in captivity for release into the wild, and some populations have recovered significantly, although others remain at risk.', 7, 90, '[{"id": "A", "text": "They were hunted mainly for their shells"}, {"id": "B", "text": "Sailors kept them alive on ships as fresh meat"}, {"id": "C", "text": "Introduced goats ate the vegetation they needed"}, {"id": "D", "text": "Lonesome George was the last known member of his species"}, {"id": "E", "text": "They cannot survive without drinking daily"}, {"id": "F", "text": "Every species has now fully recovered"}]'::jsonb, '["B", "C", "D"]'::jsonb, NULL, NULL, 'Options (B), (C), (D) are correct. Sailors took them as food, goats destroyed their food plants, and Lonesome George was the last of his kind.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-38', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The kiwi', 'Which THREE statements about the kiwi are correct?', NULL, 'The kiwi, New Zealand''s national bird, is unusual in many ways. It cannot fly, and its tiny wings are hidden beneath its feathers. It is mostly active at night, and unlike almost all other birds, it has nostrils at the tip of its long beak, which it uses to smell insects and worms in the soil. Perhaps most remarkably, the female lays an enormous egg compared with her body size, around a fifth of her own weight, one of the largest egg-to-body ratios of any bird. Before humans arrived, New Zealand had no land mammals except bats, so the kiwi had few predators on the ground. Today introduced animals, especially stoats, kill most chicks before they are old enough to defend themselves. Conservation programmes collect eggs from the wild, hatch them in safety, and return the young birds once they are large enough to survive.', 7, 90, '[{"id": "A", "text": "It flies short distances at night"}, {"id": "B", "text": "Introduced stoats kill many chicks"}, {"id": "C", "text": "It had many ground predators before humans arrived"}, {"id": "D", "text": "The female''s egg is very large compared with her body"}, {"id": "E", "text": "It finds food mainly by sight"}, {"id": "F", "text": "Its nostrils are at the tip of its beak"}]'::jsonb, '["B", "D", "F"]'::jsonb, NULL, NULL, 'Options (B), (D), (F) are correct. Nostrils at the beak tip, a huge egg and chick losses to stoats are all described.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-39', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The passenger pigeon', 'Which THREE statements are supported by the recording?', NULL, 'In the nineteenth century, the passenger pigeon may have been the most numerous bird in North America, with a population estimated in the billions. Observers described flocks so large that they darkened the sky for hours as they passed. Yet by 1914 the species was extinct; the last known individual, a female named Martha, died in a zoo in Cincinnati. Commercial hunting was a major cause. New technologies played a part: telegraph networks allowed hunters to learn quickly where flocks were nesting, and railways carried vast quantities of meat to city markets. The clearing of forests also removed the birds'' habitat. Some scientists believe the species was especially vulnerable because it bred in enormous colonies, and when numbers fell, the remaining small groups may not have been able to breed successfully.', 7, 90, '[{"id": "A", "text": "The telegraph and railways helped hunters"}, {"id": "B", "text": "Small numbers still survive in remote forests"}, {"id": "C", "text": "The bird was never common in North America"}, {"id": "D", "text": "The last known bird died in a zoo in 1914"}, {"id": "E", "text": "A disease was the main cause of extinction"}, {"id": "F", "text": "The birds may have needed large colonies to breed"}]'::jsonb, '["A", "D", "F"]'::jsonb, NULL, NULL, 'Options (A), (D), (F) are correct. Technology aided hunting, small groups may not have bred, and Martha died in 1914.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-40', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Commuting and happiness', 'Which TWO findings does the speaker report?', NULL, 'When researchers ask people to describe how they felt during different activities throughout the day, commuting regularly appears among the least enjoyable. Economists have also noticed a puzzle. People who accept a long commute should, in theory, be compensated by something else, such as a higher salary or a larger home. Yet some studies have found that people with long commutes report lower satisfaction with their lives, suggesting that many underestimate the cost of travel when choosing where to live or work. Not all commutes are equal, however. People who walk or cycle to work tend to report higher satisfaction than those who drive or use crowded public transport, perhaps because of the exercise and the predictability of the journey. The growth of working from home has given researchers new opportunities to study how the time saved is actually used.', 7, 90, '[{"id": "A", "text": "People usually overestimate how tiring travel will be"}, {"id": "B", "text": "People who walk or cycle to work tend to be more satisfied"}, {"id": "C", "text": "Driving is the most enjoyable way to commute"}, {"id": "D", "text": "Commuting is among the least enjoyable parts of many people''s day"}, {"id": "E", "text": "Long commutes are fully compensated by higher pay"}]'::jsonb, '["B", "D"]'::jsonb, NULL, NULL, 'Options (B), (D) are correct. Commuting ranks low for enjoyment, and walkers and cyclists report higher satisfaction.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-41', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Blind orchestra auditions', 'Which TWO statements are made in the recording?', NULL, 'In the 1970s and 1980s, many major orchestras in the United States began holding auditions behind a screen, so that the judges could hear the musician but not see them. Some orchestras even laid carpet on the stage, so that the sound of footsteps would not reveal whether a candidate was wearing high heels. During the same period, the proportion of women in these orchestras increased considerably. A widely cited study published in 2000 concluded that the screens had helped women advance, and the case became a famous example of how removing information can reduce bias. In recent years, some researchers have argued that the statistical evidence in the study was weaker than often claimed. Even so, the idea behind blind auditions has influenced recruitment in other fields, such as removing names from job applications during the first stage of selection.', 7, 90, '[{"id": "A", "text": "Screens hid the musicians'' identity from the judges"}, {"id": "B", "text": "Only female musicians auditioned behind screens"}, {"id": "C", "text": "Screens were introduced to improve the sound"}, {"id": "D", "text": "Orchestras stopped using screens after the study"}, {"id": "E", "text": "Some researchers have questioned the strength of the study''s evidence"}]'::jsonb, '["A", "E"]'::jsonb, NULL, NULL, 'Options (A), (E) are correct. Judges could hear but not see candidates, and the 2000 study has been criticised.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-42', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Better job interviews', 'Which TWO statements about interviews are supported?', NULL, 'Job interviews are one of the most common ways of choosing employees, yet research suggests that traditional interviews are surprisingly poor at predicting how well someone will perform in a job. In an unstructured interview, the conversation can go in any direction, and interviewers often form a strong impression within the first few minutes, sometimes based on factors such as confidence or shared interests that have little to do with the job. Decades of studies have found that structured interviews work considerably better. In a structured interview, every candidate is asked the same questions, which are based on the skills the job requires, and answers are scored using agreed criteria. Some organisations combine this with work sample tests, in which candidates complete a task similar to the real job. These methods do not remove human judgement, but they help to make it fairer and more consistent.', 7, 90, '[{"id": "A", "text": "Asking every candidate the same questions improves predictions"}, {"id": "B", "text": "Work sample tests have been shown to be useless"}, {"id": "C", "text": "Interviewers often form opinions very quickly"}, {"id": "D", "text": "Structured interviews remove human judgement completely"}, {"id": "E", "text": "Informal conversations are the most reliable method"}]'::jsonb, '["A", "C"]'::jsonb, NULL, NULL, 'Options (A), (C) are correct. Structured questions predict better, and impressions form in the first minutes.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-43', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'The economics of presents', 'Which TWO points does the speaker make?', NULL, 'In 1993, the economist Joel Waldfogel published a paper with a provocative title: The Deadweight Loss of Christmas. He asked students to estimate how much the givers had paid for gifts they had received and how much they would have been willing to pay for them. On average, recipients valued their gifts at noticeably less than the price the giver had paid, and the gap was largest for gifts from more distant relatives. From a purely economic point of view, giving cash would avoid this loss, since people could buy exactly what they wanted. In practice, however, many people feel that giving money is impersonal or even rude. Gift cards offer a compromise, although a proportion of them are never spent. Critics of the study also point out that it ignores sentimental value: a gift can matter because of who chose it, not only because of what it is.', 7, 90, '[{"id": "A", "text": "Recipients often value gifts at less than their price"}, {"id": "B", "text": "Many people feel uncomfortable giving cash"}, {"id": "C", "text": "Gifts from close friends were valued least"}, {"id": "D", "text": "Economists recommend giving no gifts at all"}, {"id": "E", "text": "Gift cards are always valued above their price"}]'::jsonb, '["A", "B"]'::jsonb, NULL, NULL, 'Options (A), (B) are correct. Gifts were valued below cost, yet cash is often seen as impersonal.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-44', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Getting used to good fortune', 'Which TWO statements are supported by the recording?', NULL, 'A famous study published in 1978 compared people who had won large sums in a lottery with people who had not. Some time after their win, the lottery winners were not significantly happier than the comparison group, and they reported taking less pleasure in ordinary everyday activities. The study is often used to illustrate an idea called hedonic adaptation: people tend to get used to changes in their circumstances, whether positive or negative, and their happiness gradually drifts back towards its usual level. This helps explain why a pay rise or a new car may bring only temporary satisfaction. However, later research has shown that adaptation is not complete for every kind of event. Some experiences, such as long-term unemployment or the loss of a partner, can have lasting effects on well-being.', 7, 90, '[{"id": "A", "text": "Some events can have lasting effects on happiness"}, {"id": "B", "text": "People tend to adapt to major changes over time"}, {"id": "C", "text": "Lottery winners stayed much happier for the rest of their lives"}, {"id": "D", "text": "People adapt to good events but never to bad ones"}, {"id": "E", "text": "Winners enjoyed everyday activities more than before"}]'::jsonb, '["A", "B"]'::jsonb, NULL, NULL, 'Options (A), (B) are correct. Happiness tends to drift back after change, but some losses have lasting effects.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-45', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Handedness', 'Which THREE statements are made in the recording?', NULL, 'Around one in ten people around the world are left-handed, a proportion that appears to have been fairly stable for thousands of years, judging by evidence from ancient tools and artwork. Handedness is influenced by genes, but no single gene determines it, and environmental factors also play a part. For much of history, left-handed children were often forced to write with their right hand, and the words for left in several languages carry negative meanings. Left-handers are, however, overrepresented at the top level of some sports. In one-on-one contests such as fencing, boxing and tennis, they may have an advantage because most opponents spend their time competing against right-handers and are less familiar with the angles a left-hander creates. Some researchers have suggested that a similar advantage in fighting may help explain why left-handedness has survived throughout human evolution.', 7, 90, '[{"id": "A", "text": "About one in ten people are left-handed"}, {"id": "B", "text": "Left-handers have an advantage only in team sports"}, {"id": "C", "text": "Left-handed children were often forced to use their right hand"}, {"id": "D", "text": "Left-handers are overrepresented in some one-on-one sports"}, {"id": "E", "text": "Handedness is decided by a single gene"}, {"id": "F", "text": "Left-handedness first appeared in the last century"}]'::jsonb, '["A", "C", "D"]'::jsonb, NULL, NULL, 'Options (A), (C), (D) are correct. The proportion, the history of forced switching and the sporting advantage are all mentioned.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-46', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Childhood amnesia', 'Which TWO explanations for childhood amnesia does the speaker mention?', NULL, 'Most adults cannot remember anything from the first three or four years of their lives, even though young children clearly form memories at the time; a two-year-old can remember a visit to the park the week before. This loss of early memories is known as childhood amnesia. Researchers have proposed several explanations. The hippocampus, a brain region important for forming long-term memories of events, is still developing in early childhood, and the rapid growth of new brain cells may disrupt older memories. Language may also play a role: memories formed before children can describe experiences in words may be harder to retrieve later. In addition, many people report early memories that are actually based on family photographs or stories they have heard, rather than on the events themselves. Studies have shown that it is surprisingly easy to create such false memories, especially of early childhood.', 7, 90, '[{"id": "A", "text": "A brain region for event memory is still developing"}, {"id": "B", "text": "Young children cannot form memories at all"}, {"id": "C", "text": "Adults deliberately suppress unhappy early experiences"}, {"id": "D", "text": "Memories formed before language may be hard to retrieve"}, {"id": "E", "text": "Family photographs erase real memories"}]'::jsonb, '["A", "D"]'::jsonb, NULL, NULL, 'Options (A), (D) are correct. The developing hippocampus and the role of language are both given as explanations.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-47', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Bacteria on dropped snacks', 'Which THREE findings are reported?', NULL, 'Many people follow the so-called five-second rule, believing that food dropped on the floor is safe to eat if it is picked up quickly. In 2016, researchers in the United States tested this belief. They contaminated different surfaces, including stainless steel, tiles, wood and carpet, with bacteria, and then dropped foods such as watermelon, bread and gummy sweets onto them for different lengths of time. They found that bacteria could move onto food in less than a second, so the rule is not reliable. Longer contact did lead to more contamination, however. Moisture was the most important factor: watermelon picked up the most bacteria, while the gummy sweets picked up the least. Surprisingly, carpet transferred fewer bacteria than steel or tiles, possibly because food touches less of its surface. The researchers concluded that the five-second rule is a significant oversimplification.', 7, 90, '[{"id": "A", "text": "Contact time made no difference"}, {"id": "B", "text": "Moist foods picked up the most bacteria"}, {"id": "C", "text": "Carpet transferred more bacteria than steel"}, {"id": "D", "text": "Bacteria can move onto food in less than a second"}, {"id": "E", "text": "Longer contact led to more contamination"}, {"id": "F", "text": "Food is safe if picked up within five seconds"}]'::jsonb, '["B", "D", "E"]'::jsonb, NULL, NULL, 'Options (B), (D), (E) are correct. Transfer was almost instant, moisture mattered most, and longer contact meant more bacteria.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-48', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Recognising a reflection', 'Which TWO statements about the mirror test are made?', NULL, 'In 1970, the psychologist Gordon Gallup developed a simple test of whether animals recognise themselves. Chimpanzees were given time to become familiar with a mirror, and then a coloured mark was placed on their faces while they were anaesthetised, in a position they could see only in the mirror. When they woke, several chimpanzees looked in the mirror and touched the mark on their own faces, suggesting they understood that the reflection showed themselves. Since then, great apes, some elephants, dolphins and magpies have been reported to pass versions of the test. Many other animals, including dogs, do not. Critics argue that the test favours species that depend heavily on vision. Dogs rely much more on smell, and researchers have designed experiments suggesting that dogs may recognise their own scent in ways similar to a mirror test.', 7, 90, '[{"id": "A", "text": "Critics say it favours animals that rely on sight"}, {"id": "B", "text": "Only humans have ever passed it"}, {"id": "C", "text": "The mark is placed where it can be seen only in a mirror"}, {"id": "D", "text": "It measures an animal''s overall intelligence"}, {"id": "E", "text": "Dogs pass it more easily than chimpanzees"}]'::jsonb, '["A", "C"]'::jsonb, NULL, NULL, 'Options (A), (C) are correct. The mark is visible only in the mirror, and the test may be unfair to smell-based animals.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-49', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Darwin''s earthworms', 'Which TWO statements are made about Darwin''s research?', NULL, 'Charles Darwin''s final book, published in 1881, was not about evolution but about earthworms, and it sold remarkably well. Darwin had studied worms for decades. He measured how quickly objects left on the surface of fields were buried as worms brought soil up from below, and he showed that worms had helped to bury ancient buildings and stones. He argued that worms were enormously important to agriculture, because by constantly swallowing and moving soil they mix it, let air and water in, and make it more fertile. Some of his experiments were charmingly unusual. He tested whether worms could hear by having his son play the bassoon to them, and by playing notes on a piano. The worms showed no reaction to the music, but when their pots were placed on top of the piano, they responded quickly to the vibrations.', 7, 90, '[{"id": "A", "text": "He found that worms could hear the piano clearly"}, {"id": "B", "text": "His final book was about earthworms"}, {"id": "C", "text": "Worms ignored the music but reacted to vibrations"}, {"id": "D", "text": "The book sold very few copies"}, {"id": "E", "text": "He concluded that worms damage farmland"}]'::jsonb, '["B", "C"]'::jsonb, NULL, NULL, 'Options (B), (C) are correct. The 1881 book was about worms, which reacted to vibrations but not to sound.', 'medium', 2, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-mcma-50', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-mcma', 'MCQ Multiple Answer', 'Pisa''s tilt', 'Which THREE statements about the tower are correct?', NULL, 'Construction of the famous bell tower in Pisa began in 1173, and it had reached only its third floor when it began to lean. The ground beneath it was soft and uneven, and one side sank more than the other. Work stopped for almost a century because of wars, and this long pause may have saved the tower, allowing the soil to compress and become stronger. When building resumed, the engineers tried to correct the tilt by making the upper floors slightly curved. By the late twentieth century, the lean had become so great that the tower was closed to the public in 1990. Engineers then carefully removed small amounts of soil from beneath the higher side, allowing it to settle and reducing the tilt without straightening it completely. The tower reopened in 2001, and experts believe it should remain stable for centuries.', 7, 90, '[{"id": "A", "text": "The lean was caused by an earthquake"}, {"id": "B", "text": "It began to lean while it was still being built"}, {"id": "C", "text": "Work on it stopped for almost a century"}, {"id": "D", "text": "It has been closed to visitors since 1990"}, {"id": "E", "text": "Removing soil from one side reduced the lean"}, {"id": "F", "text": "Engineers straightened it completely"}]'::jsonb, '["B", "C", "E"]'::jsonb, NULL, NULL, 'Options (B), (C), (E) are correct. The lean began early, construction paused, and soil removal reduced the tilt.', 'medium', 3, ARRAY['PTE', 'Original practice', 'MCQ Multiple Answer']::text[], true),
    ('q-pl90-fib-01', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'Burrs and Velcro', 'You will hear a recording. Type the missing words in each blank.', 'In 1941, the Swiss engineer George de Mestral returned from a walk and noticed burrs stuck to his dog''s fur. Under a [[b1]], he saw that each burr was covered in tiny [[b2]] that caught on loops of hair and fabric. It took him years to copy this design in nylon, but the fastener he patented in the 1950s became known as Velcro, a clear example of engineers learning from [[b3]].', 'In 1941, the Swiss engineer George de Mestral returned from a walk and noticed burrs stuck to his dog''s fur. Under a microscope, he saw that each burr was covered in tiny hooks that caught on loops of hair and fabric. It took him years to copy this design in nylon, but the fastener he patented in the 1950s became known as Velcro, a clear example of engineers learning from nature.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "microscope"}, {"id": "b2", "correctAnswer": "hooks"}, {"id": "b3", "correctAnswer": "nature"}]'::jsonb, NULL, 'The recording says: microscope, hooks, nature.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-02', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'The accidental sticky note', 'You will hear a recording. Type the missing words in each blank.', 'In 1968, a chemist at the company 3M was trying to create a very strong glue, but he produced one that was surprisingly [[b1]]. It stuck to surfaces yet could be removed without leaving a mark. For years nobody found a use for it, until a colleague used it to keep [[b2]] in place in his choir book. The sticky notes finally went on [[b3]] in 1980.', 'In 1968, a chemist at the company 3M was trying to create a very strong glue, but he produced one that was surprisingly weak. It stuck to surfaces yet could be removed without leaving a mark. For years nobody found a use for it, until a colleague used it to keep bookmarks in place in his choir book. The sticky notes finally went on sale in 1980.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "weak"}, {"id": "b2", "correctAnswer": "bookmarks"}, {"id": "b3", "correctAnswer": "sale"}]'::jsonb, NULL, 'The recording says: weak, bookmarks, sale.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-03', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'Percy Spencer''s magnetron', 'You will hear a recording. Type the missing words in each blank.', 'During the Second World War, the engineer Percy Spencer worked on [[b1]] equipment. One day, while standing near a device called a magnetron, he noticed that a chocolate bar in his [[b2]] had melted. He then tested the effect on popcorn kernels, which popped. His company patented the idea, and the first microwave ovens were large, expensive machines used mainly in [[b3]] and on ships.', 'During the Second World War, the engineer Percy Spencer worked on radar equipment. One day, while standing near a device called a magnetron, he noticed that a chocolate bar in his pocket had melted. He then tested the effect on popcorn kernels, which popped. His company patented the idea, and the first microwave ovens were large, expensive machines used mainly in restaurants and on ships.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "radar"}, {"id": "b2", "correctAnswer": "pocket"}, {"id": "b3", "correctAnswer": "restaurants"}]'::jsonb, NULL, 'The recording says: radar, pocket, restaurants.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-04', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'Discovering Teflon', 'You will hear a recording. Type the missing words in each blank.', 'In 1938, the chemist Roy Plunkett was working with a gas stored in metal [[b1]]. When he opened one, no gas came out. Cutting it open, he found a white, waxy [[b2]] that was extremely slippery and resisted heat and chemicals. The material, later called Teflon, was first used in industry, and only in the 1950s did a French engineer use it to coat frying [[b3]].', 'In 1938, the chemist Roy Plunkett was working with a gas stored in metal cylinders. When he opened one, no gas came out. Cutting it open, he found a white, waxy powder that was extremely slippery and resisted heat and chemicals. The material, later called Teflon, was first used in industry, and only in the 1950s did a French engineer use it to coat frying pans.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "cylinders"}, {"id": "b2", "correctAnswer": "powder"}, {"id": "b3", "correctAnswer": "pans"}]'::jsonb, NULL, 'The recording says: cylinders, powder, pans.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-05', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'Safer matches', 'You will hear a recording. Type the missing words in each blank.', 'Early matches could be lit by striking them on almost any rough surface, which made them [[b1]]. Many also contained white phosphorus, a toxic substance that seriously harmed the health of factory [[b2]]. The safety match, developed in Sweden in the nineteenth century, solved both problems by moving the reactive chemical, red phosphorus, from the match head onto a [[b3]] on the side of the box.', 'Early matches could be lit by striking them on almost any rough surface, which made them dangerous. Many also contained white phosphorus, a toxic substance that seriously harmed the health of factory workers. The safety match, developed in Sweden in the nineteenth century, solved both problems by moving the reactive chemical, red phosphorus, from the match head onto a strip on the side of the box.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "dangerous"}, {"id": "b2", "correctAnswer": "workers"}, {"id": "b3", "correctAnswer": "strip"}]'::jsonb, NULL, 'The recording says: dangerous, workers, strip.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-06', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'The Gem clip', 'You will hear a recording. Type the missing words in each blank.', 'The familiar paper clip, a loop of steel wire bent into a double oval, has a surprisingly unclear history. In the late nineteenth century, many inventors patented [[b1]] for holding sheets of paper together. The most successful shape, often called the Gem clip, was never actually patented by its original maker. In Norway, the paper clip became a symbol of [[b2]] during the Second World War, when people wore them on their [[b3]].', 'The familiar paper clip, a loop of steel wire bent into a double oval, has a surprisingly unclear history. In the late nineteenth century, many inventors patented designs for holding sheets of paper together. The most successful shape, often called the Gem clip, was never actually patented by its original maker. In Norway, the paper clip became a symbol of resistance during the Second World War, when people wore them on their clothes.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "designs"}, {"id": "b2", "correctAnswer": "resistance"}, {"id": "b3", "correctAnswer": "clothes"}]'::jsonb, NULL, 'The recording says: designs, resistance, clothes.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-07', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'The first barcode', 'You will hear a recording. Type the missing words in each blank.', 'The idea for the barcode came from a student who drew lines in the [[b1]] while thinking about Morse code. The first patent was granted in 1952, but the technology only became practical once [[b2]] and computers were cheaper. In 1974, a packet of chewing gum became the first product to be scanned at a supermarket [[b3]] in the United States.', 'The idea for the barcode came from a student who drew lines in the sand while thinking about Morse code. The first patent was granted in 1952, but the technology only became practical once lasers and computers were cheaper. In 1974, a packet of chewing gum became the first product to be scanned at a supermarket checkout in the United States.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "sand"}, {"id": "b2", "correctAnswer": "lasers"}, {"id": "b3", "correctAnswer": "checkout"}]'::jsonb, NULL, 'The recording says: sand, lasers, checkout.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-08', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'The ballpoint pen', 'You will hear a recording. Type the missing words in each blank.', 'The Hungarian journalist László Bíró noticed that newspaper ink dried [[b1]] without smudging, but it was too thick to flow through a fountain pen. Working with his brother, he designed a pen with a tiny rotating [[b2]] at its tip, which picked up ink and rolled it onto the paper. During the Second World War, the pens were valued by air crews because they did not [[b3]] at high altitude.', 'The Hungarian journalist László Bíró noticed that newspaper ink dried quickly without smudging, but it was too thick to flow through a fountain pen. Working with his brother, he designed a pen with a tiny rotating ball at its tip, which picked up ink and rolled it onto the paper. During the Second World War, the pens were valued by air crews because they did not leak at high altitude.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "quickly"}, {"id": "b2", "correctAnswer": "ball"}, {"id": "b3", "correctAnswer": "leak"}]'::jsonb, NULL, 'The recording says: quickly, ball, leak.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-09', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'Appert''s jars', 'You will hear a recording. Type the missing words in each blank.', 'In the early nineteenth century, the French government offered a prize for a better way to feed its [[b1]]. A confectioner named Nicolas Appert won it by sealing food in glass jars and then [[b2]] them. He did not know why the method worked; it was decades before Louis Pasteur showed that heat kills microbes. Tin cans soon replaced glass, although a practical can [[b3]] did not appear until much later.', 'In the early nineteenth century, the French government offered a prize for a better way to feed its armies. A confectioner named Nicolas Appert won it by sealing food in glass jars and then boiling them. He did not know why the method worked; it was decades before Louis Pasteur showed that heat kills microbes. Tin cans soon replaced glass, although a practical can opener did not appear until much later.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "armies"}, {"id": "b2", "correctAnswer": "boiling"}, {"id": "b3", "correctAnswer": "opener"}]'::jsonb, NULL, 'The recording says: armies, boiling, opener.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-10', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'Instant noodles', 'You will hear a recording. Type the missing words in each blank.', 'Instant noodles were invented in Japan in 1958 by Momofuku Ando, who had seen long [[b1]] for noodle soup during the food shortages after the war. His key discovery was that frying cooked noodles in hot oil removed their [[b2]] and left tiny holes, so they softened quickly in boiling water. In 1971 he added a waterproof [[b3]], creating a product that is now eaten around the world.', 'Instant noodles were invented in Japan in 1958 by Momofuku Ando, who had seen long queues for noodle soup during the food shortages after the war. His key discovery was that frying cooked noodles in hot oil removed their moisture and left tiny holes, so they softened quickly in boiling water. In 1971 he added a waterproof cup, creating a product that is now eaten around the world.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "queues"}, {"id": "b2", "correctAnswer": "moisture"}, {"id": "b3", "correctAnswer": "cup"}]'::jsonb, NULL, 'The recording says: queues, moisture, cup.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-11', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'The first crossword', 'You will hear a recording. Type the missing words in each blank.', 'The first modern crossword was published in a New York newspaper in December 1913. Its creator, Arthur Wynne, called it a word-cross and arranged it in a [[b1]] shape. The puzzle quickly became popular, and by the 1920s crosswords were a national [[b2]], with books of puzzles selling in huge numbers. Some critics even complained that people were wasting too much [[b3]] on them.', 'The first modern crossword was published in a New York newspaper in December 1913. Its creator, Arthur Wynne, called it a word-cross and arranged it in a diamond shape. The puzzle quickly became popular, and by the 1920s crosswords were a national craze, with books of puzzles selling in huge numbers. Some critics even complained that people were wasting too much time on them.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "diamond"}, {"id": "b2", "correctAnswer": "craze"}, {"id": "b3", "correctAnswer": "time"}]'::jsonb, NULL, 'The recording says: diamond, craze, time.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-12', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'The Penny Black', 'You will hear a recording. Type the missing words in each blank.', 'Before 1840, letters in Britain were usually paid for by the person who [[b1]] them, and the cost depended on the distance travelled. The reformer Rowland Hill argued for a single low price paid in advance by the [[b2]]. The result was the Penny Black, the world''s first adhesive postage [[b3]], which allowed a letter to be sent anywhere in the country for one penny.', 'Before 1840, letters in Britain were usually paid for by the person who received them, and the cost depended on the distance travelled. The reformer Rowland Hill argued for a single low price paid in advance by the sender. The result was the Penny Black, the world''s first adhesive postage stamp, which allowed a letter to be sent anywhere in the country for one penny.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "received"}, {"id": "b2", "correctAnswer": "sender"}, {"id": "b3", "correctAnswer": "stamp"}]'::jsonb, NULL, 'The recording says: received, sender, stamp.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-13', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'Cat''s eyes', 'You will hear a recording. Type the missing words in each blank.', 'In 1934, the English inventor Percy Shaw patented a small device set into the middle of the [[b1]], containing glass lenses that reflect car headlights back towards the driver. According to a popular story, the idea came to him when his headlights were reflected in the [[b2]] of a cat on a dark night. The design is clever: when a car drives over it, the rubber housing is pushed down and the lenses are wiped [[b3]] by rainwater collected inside.', 'In 1934, the English inventor Percy Shaw patented a small device set into the middle of the road, containing glass lenses that reflect car headlights back towards the driver. According to a popular story, the idea came to him when his headlights were reflected in the eyes of a cat on a dark night. The design is clever: when a car drives over it, the rubber housing is pushed down and the lenses are wiped clean by rainwater collected inside.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "road"}, {"id": "b2", "correctAnswer": "eyes"}, {"id": "b3", "correctAnswer": "clean"}]'::jsonb, NULL, 'The recording says: road, eyes, clean.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-14', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'Defining the metre', 'You will hear a recording. Type the missing words in each blank.', 'Before the French Revolution, France used hundreds of different local units of [[b1]], which made trade confusing and unfair. In the 1790s, scientists proposed a new system based on nature. The metre was defined as one ten-millionth of the distance from the North Pole to the [[b2]], and two astronomers spent years [[b3]] the line between Dunkirk and Barcelona to calculate it.', 'Before the French Revolution, France used hundreds of different local units of measurement, which made trade confusing and unfair. In the 1790s, scientists proposed a new system based on nature. The metre was defined as one ten-millionth of the distance from the North Pole to the equator, and two astronomers spent years surveying the line between Dunkirk and Barcelona to calculate it.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "measurement"}, {"id": "b2", "correctAnswer": "equator"}, {"id": "b3", "correctAnswer": "surveying"}]'::jsonb, NULL, 'The recording says: measurement, equator, surveying.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
    ('q-pl90-fib-15', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-listening-fib', 'Listening Fill in the Blanks', 'The Terracotta Army', 'You will hear a recording. Type the missing words in each blank.', 'In 1974, farmers digging a [[b1]] near the Chinese city of Xi''an found fragments of a clay figure. They had discovered the Terracotta Army, thousands of life-sized soldiers buried with China''s first emperor more than two thousand years ago. Each figure has an individual [[b2]]. The soldiers were originally brightly painted, but much of the colour flakes away within minutes of being exposed to [[b3]].', 'In 1974, farmers digging a well near the Chinese city of Xi''an found fragments of a clay figure. They had discovered the Terracotta Army, thousands of life-sized soldiers buried with China''s first emperor more than two thousand years ago. Each figure has an individual face. The soldiers were originally brightly painted, but much of the colour flakes away within minutes of being exposed to air.', 7, 120, NULL, NULL, '[{"id": "b1", "correctAnswer": "well"}, {"id": "b2", "correctAnswer": "face"}, {"id": "b3", "correctAnswer": "air"}]'::jsonb, NULL, 'The recording says: well, face, air.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Listening Fill in the Blanks']::text[], true),
