    ('q-pl90-hiw-16', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Maria Montessori', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Maria Montessori was one of the first women in Italy to qualify as a lawyer. In 1907, she opened a school for young children in a poor district of Rome. Her classrooms had child-sized windows, and children chose their own activities from carefully designed materials. She believed that children learn best through independent punishment, an approach still used in thousands of schools.', 'Maria Montessori was one of the first women in Italy to qualify as a doctor. In 1907, she opened a school for young children in a poor district of Rome. Her classrooms had child-sized furniture, and children chose their own activities from carefully designed materials. She believed that children learn best through independent exploration, an approach still used in thousands of schools.', 10, 120, '[{"id": "w1", "text": "Maria"}, {"id": "w2", "text": "Montessori"}, {"id": "w3", "text": "was"}, {"id": "w4", "text": "one"}, {"id": "w5", "text": "of"}, {"id": "w6", "text": "the"}, {"id": "w7", "text": "first"}, {"id": "w8", "text": "women"}, {"id": "w9", "text": "in"}, {"id": "w10", "text": "Italy"}, {"id": "w11", "text": "to"}, {"id": "w12", "text": "qualify"}, {"id": "w13", "text": "as"}, {"id": "w14", "text": "a"}, {"id": "w15", "text": "lawyer."}, {"id": "w16", "text": "In"}, {"id": "w17", "text": "1907,"}, {"id": "w18", "text": "she"}, {"id": "w19", "text": "opened"}, {"id": "w20", "text": "a"}, {"id": "w21", "text": "school"}, {"id": "w22", "text": "for"}, {"id": "w23", "text": "young"}, {"id": "w24", "text": "children"}, {"id": "w25", "text": "in"}, {"id": "w26", "text": "a"}, {"id": "w27", "text": "poor"}, {"id": "w28", "text": "district"}, {"id": "w29", "text": "of"}, {"id": "w30", "text": "Rome."}, {"id": "w31", "text": "Her"}, {"id": "w32", "text": "classrooms"}, {"id": "w33", "text": "had"}, {"id": "w34", "text": "child-sized"}, {"id": "w35", "text": "windows,"}, {"id": "w36", "text": "and"}, {"id": "w37", "text": "children"}, {"id": "w38", "text": "chose"}, {"id": "w39", "text": "their"}, {"id": "w40", "text": "own"}, {"id": "w41", "text": "activities"}, {"id": "w42", "text": "from"}, {"id": "w43", "text": "carefully"}, {"id": "w44", "text": "designed"}, {"id": "w45", "text": "materials."}, {"id": "w46", "text": "She"}, {"id": "w47", "text": "believed"}, {"id": "w48", "text": "that"}, {"id": "w49", "text": "children"}, {"id": "w50", "text": "learn"}, {"id": "w51", "text": "best"}, {"id": "w52", "text": "through"}, {"id": "w53", "text": "independent"}, {"id": "w54", "text": "punishment,"}, {"id": "w55", "text": "an"}, {"id": "w56", "text": "approach"}, {"id": "w57", "text": "still"}, {"id": "w58", "text": "used"}, {"id": "w59", "text": "in"}, {"id": "w60", "text": "thousands"}, {"id": "w61", "text": "of"}, {"id": "w62", "text": "schools."}]'::jsonb, '["w15", "w35", "w54"]'::jsonb, NULL, NULL, 'Select lawyer, windows, punishment. The speaker says doctor, furniture, exploration.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-17', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Froebel''s kindergarten', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The word kindergarten, meaning children''s garden, was created by the German educator Friedrich Froebel in the nineteenth month. He believed young children learn through work, songs and hands-on activity rather than memorising facts. He designed sets of wooden blocks and shapes, called gifts, and the architect Frank Lloyd Wright later said that playing with them as a child influenced his diet.', 'The word kindergarten, meaning children''s garden, was created by the German educator Friedrich Froebel in the nineteenth century. He believed young children learn through play, songs and hands-on activity rather than memorising facts. He designed sets of wooden blocks and shapes, called gifts, and the architect Frank Lloyd Wright later said that playing with them as a child influenced his designs.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "word"}, {"id": "w3", "text": "kindergarten,"}, {"id": "w4", "text": "meaning"}, {"id": "w5", "text": "children''s"}, {"id": "w6", "text": "garden,"}, {"id": "w7", "text": "was"}, {"id": "w8", "text": "created"}, {"id": "w9", "text": "by"}, {"id": "w10", "text": "the"}, {"id": "w11", "text": "German"}, {"id": "w12", "text": "educator"}, {"id": "w13", "text": "Friedrich"}, {"id": "w14", "text": "Froebel"}, {"id": "w15", "text": "in"}, {"id": "w16", "text": "the"}, {"id": "w17", "text": "nineteenth"}, {"id": "w18", "text": "month."}, {"id": "w19", "text": "He"}, {"id": "w20", "text": "believed"}, {"id": "w21", "text": "young"}, {"id": "w22", "text": "children"}, {"id": "w23", "text": "learn"}, {"id": "w24", "text": "through"}, {"id": "w25", "text": "work,"}, {"id": "w26", "