    ('q-pl90-hiw-18', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'The Socratic method', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The Socratic method is named after the Greek philosopher Socrates, who taught by asking stories rather than giving answers. By asking a student to explain and defend a belief, he aimed to reveal hidden assumptions and agreements. We know about his conversations mainly through the writings of his student Plato, and a version of the method is still widely used in cookery schools today.', 'The Socratic method is named after the Greek philosopher Socrates, who taught by asking questions rather than giving answers. By asking a student to explain and defend a belief, he aimed to reveal hidden assumptions and contradictions. We know about his conversations mainly through the writings of his student Plato, and a version of the method is still widely used in law schools today.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "Socratic"}, {"id": "w3", "text": "method"}, {"id": "w4", "text": "is"}, {"id": "w5", "text": "named"}, {"id": "w6", "text": "after"}, {"id": "w7", "text": "the"}, {"id": "w8", "text": "Greek"}, {"id": "w9", "text": "philosopher"}, {"id": "w10", "text": "Socrates,"}, {"id": "w11", "text": "who"}, {"id": "w12", "text": "taught"}, {"id": "w13", "text": "by"}, {"id": "w14", "text": "asking"}, {"id": "w15", "text": "stories"}, {"id": "w16", "text": "rather"}, {"id": "w17", "text": "than"}, {"id": "w18", "text": "giving"}, {"id": "w19", "text": "answers."}, {"id": "w20", "text": "By"}, {"id": "w21", "text": "asking"}, {"id": "w22", "text": "a"}, {"id": "w23", "text": "student"}, {"id": "w24", "text": "to"}, {"id": "w25", "text": "explain"}, {"id": "w26", "text": "and"}, {"id": "w27", "text": "defend"}, 