    ('q-pl90-hiw-19', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'The Great Vowel Shift', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'English spelling often seems modern, and one reason is the Great Vowel Shift. Between roughly 1400 and 1700, the pronunciation of long vowels in English changed slightly. At the same time, printing helped to fix spellings, so many words are still written in a way that reflects how they were translated centuries ago.', 'English spelling often seems illogical, and one reason is the Great Vowel Shift. Between roughly 1400 and 1700, the pronunciation of long vowels in English changed dramatically. At the same time, printing helped to fix spellings, so many words are still written in a way that reflects how they were pronounced centuries ago.', 10, 120, '[{"id": "w1", "text": "English"}, {"id": "w2", "text": "spelling"}, {"id": "w3", "text": "often"}, {"id": "w4", "text": "seems"}, {"id": "w5", "text": "modern,"}, {"id": "w6", "text": "and"}, {"id": "w7", "text": "one"}, {"id": "w8", "text": "reason"}, {"id": "w9", "text": "is"}, {"id": "w10", "text": "the"}, {"id": "w11", "text": "Great"}, {"id": "w12", "text": "Vowel"}, {"id": "w13", "text": "Shift."}, {"id": "w14", "text": "Between"}, {"id": "w15", "text": "roughly"}, {"id": "w16", "text": "1400"}, {"id": "w17", "text": "and"}, {"id": "w18", "text": "1700,"}, {"id": "w19", "text": "the"}, {"id": "w20", "text": "pronunciation"}, {"id": "w21", "text": "of"}, {"id": "w22", "text": "long"}, {"id": "w23", "text": "vowels"}, {"id": "w24", "text": "in"}, {"id": "w25", "text": "English"}, {"id": "w26", "text": "changed"}, {"id": "w27", "text": "slightly."}, {"id": "w28", "text": "At"}, {"id": "w29", "text": "the"}, {"id": "w30", "text": "same"}, {"id": "w31", "text": "time,"}, {"id": "w32", "text": "printing"}, {"id": "w33", "text": "helped"}, {"id": "w34", "text": "to"}, {"id": "w35", "text": "fix"}, {"id": "w36", "text": "spellings,"}, {"id": "w37", "text": "so"}, {"id": "w38", "text": "many"}, {"id": "w39", "text": "words"}, {"id": "w40", "text": "are"}, {"id": "w41", "text": "still"}, {"id": "w42", "text": "written"}, {"id": "w43", "text": "in"}, {"id": "w44", "text": "a"}, {"id": "w45", "text": "way"}, {"id": "w46", "text": "that"}, {"id": "w47", "text": "reflects"}, {"id": "w48", "text": "how"}, {"id": "w49", "text": "they"}, {"id": "w50", "text": "were"}, {"id": "w51", "text": "translated"}, {"id": "w52", "text": "centuries"}, {"id": "w53", "text": "ago."}]'::jsonb, '["w5", "w27", "w51"]'::jsonb, NULL, NULL, 'Select modern, slightly, translated. The speaker says illogical, dramatically, pronounced.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-20', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Johnson''s dictionary', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Samuel Johnson''s Dictionary of the English Language was published in 1755 after about nine years of travel. It defined around forty thousand words, and its most important innovation was the use of pictures from well-known writers to show how each word was actually used. Some definitions were famously brief, and the dictionary remained the leading authority for over a century.', 'Samuel Johnson''s Dictionary of the English Language was published in 1755 after about nine years of work. It defined around forty thousand words, and its most important innovation was the use of quotations from well-known writers to show how each word was actually used. Some definitions were famously humorous, and the dictionary remained the leading authority for over a century.', 10, 120, '[{"id": "w1", "text": "Samuel"}, {"id": "w2", "text": "Johnson''s"}, {"id": "w3", "text": "Dictionary"}, {"id": "w4", "text": "of"}, {"id": "w5", "text": "the"}, {"id": "w6", "text": "English"}, {"id": "w7", "text": "Language"}, {"id": "w8", "text": "was"}, {"id": "w9", "text": "published"}, {"id": "w10", "text": "in"}, {"id": "w11", "text": "1755"}, {"id": "w12", "text": "after"}, {"id": "w13", "text": "about"}, {"id": "w14", "text": "nine"}, {"id": "w15", "text": "years"}, {"id": "w16", "text": "of"}, {"id": "w17", "text": "travel."}, {"id": "w18", "text": "It"}, {"id": "w19", "text": "defined"}, {"id": "w20", "text": "around"}, {"id": "w21", "text": "forty"}, {"id": "w22", "text": "thousand"}, {"id": "w23", "text": "words,"}, {"id": "w24", "text": "and"}, {"id": "w25", "text": "its"}, {"id": "w26", "text": "most"}, {"id": "w27", "text": "important"}, {"id": "w28", "text": "innovation"}, {"id": "w29", "text": "was"}, {"id": "w30", "text": "the"}, {"id": "w31", "text": "use"}, {"id": "w32", "text": "of"}, {"id": "w33", "text": "pictures"}, {"id": "w34", "text": "from"}, {"id": "w35", "text": "well-known"}, {"id": "w36", "text": "writers"}, {"id": "w37", "text": "to"}, {"id": "w38", "text": "show"}, {"id": "w39", "text": "how"}, {"id": "w40", "text": "each"}, {"id": "w41", "text": "word"}, {"id": "w42", "text": "was"}, {"id": "w43", "text": "actually"}, {"id": "w44", "text": "used."}, {"id": "w45", "text": "Some"}, {"id": "w46", "text": "definitions"}, {"id": "w47", "text": "were"}, {"id": "w48", "text": "famously"}, {"id": "w49", "text": "brief,"}, {"id": "w50", "text": "and"}, {"id": "w51", "text": "the"}, {"id": "w52", "text": "dictionary"}, {"id": "w53", "text": "remained"}, {"id": "w54", "text": "the"}, {"id": "w55", "text": "leading"}, {"id": "w56", "text": "authority"}, {"id": "w57", "text": "for"}, {"id": "w58", "text": "over"}, {"id": "w59", "text": "a"}, {"id": "w60", "text": "century."}]'::jsonb, '["w17", "w33", "w49"]'::jsonb, NULL, NULL, 'Select travel, pictures, brief. The speaker says work, quotations, humorous.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-21', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Volunteers and the OED', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The Oxford English Dictionary relied on thousands of professors who read books and posted slips of paper showing how words had been used. The project began in the 1850s and was expected to take about ten years, but the final volume was not published until 1882. One of the most productive contributors was a sailor held in a psychiatric hospital.', 'The Oxford English Dictionary relied on thousands of volunteers who read books and posted slips of paper showing how words had been used. The project began in the 1850s and was expected to take about ten years, but the final volume was not published until 1928. One of the most productive contributors was a doctor held in a psychiatric hospital.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "Oxford"}, {"id": "w3", "text": "English"}, {"id": "w4", "text": "Dictionary"}, {"id": "w5", "text": "relied"}, {"id": "w6", "text": "on"}, {"id": "w7", "text": "thousands"}, {"id": "w8", "text": "of"}, {"id": "w9", "text": "professors"}, {"id": "w10", "text": "who"}, {"id": "w11", "text": "read"}, {"id": "w12", "text": "books"}, {"id": "w13", "text": "and"}, {"id": "w14", "text": "posted"}, {"id": "w15", "text": "slips"}, {"id": "w16", "text": "of"}, {"id": "w17", "text": "paper"}, {"id": "w18", "text": "showing"}, {"id": "w19", "text": "how"}, {"id": "w20", "text": "words"}, {"id": "w21", "text": "had"}, {"id": "w22", "text": "been"}, {"id": "w23", "text": "used."}, {"id": "w24", "text": "The"}, {"id": "w25", "text": "project"}, {"id": "w26", "text": "began"}, {"id": "w27", "text": "in"}, {"id": "w28", "text": "the"}, {"id": "w29", "text": "1850s"}, {"id": "w30", "text": "and"}, {"id": "w31", "text": "was"}, {"id": "w32", "text": "expected"}, {"id": "w33", "text": "to"}, {"id": "w34", "text": "take"}, {"id": "w35", "text": "about"}, {"id": "w36", "text": "ten"}, {"id": "w37", "text": "years,"}, {"id": "w38", "text": "but"}, {"id": "w39", "text": "the"}, {"id": "w40", "text": "final"}, {"id": "w41", "text": "volume"}, {"id": "w42", "text": "was"}, {"id": "w43", "text": "not"}, {"id": "w44", "text": "published"}, {"id": "w45", "text": "until"}, {"id": "w46", "text": "1882."}, {"id": "w47", "text": "One"}, {"id": "w48", "text": "of"}, {"id": "w49", "text": "the"}, {"id": "w50", "text": "most"}, {"id": "w51", "text": "productive"}, {"id": "w52", "text": "contributors"}, {"id": "w53", "text": "was"}, {"id": "w54", "text": "a"}, {"id": "w55", "text": "sailor"}, {"id": "w56", "text": "held"}, {"id": "w57", "text": "in"}, {"id": "w58", "text": "a"}, {"id": "w59", "text": "psychiatric"}, {"id": "w60", "text": "hospital."}]'::jsonb, '["w9", "w46", "w55"]'::jsonb, NULL, NULL, 'Select professors, 1882, sailor. The speaker says volunteers, 1928, doctor.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-22', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Where OK came from', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The word OK is used around the world, but its origin was debated for a long time. The linguist Allen Walker Read showed that it first appeared in a Boston novel in 1839, as a joke abbreviation of oll korrect, a deliberate misspelling of all correct. Such jokey abbreviations were forbidden at the time. The word survived partly thanks to the 1840 presidential debate, when supporters of Martin Van Buren, nicknamed Old Kinderhook, used it as a slogan.', 'The word OK is used around the world, but its origin was debated for a long time. The linguist Allen Walker Read showed that it first appeared in a Boston newspaper in 1839, as a joke abbreviation of oll korrect, a deliberate misspelling of all correct. Such jokey abbreviations were fashionable at the time. The word survived partly thanks to the 1840 presidential election, when supporters of Martin Van Buren, nicknamed Old Kinderhook, used it as a slogan.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "word"}, {"id": "w3", "text": "OK"}, {"id": "w4", "text": "is"}, {"id": "w5", "text": "used"}, {"id": "w6", "text": "around"}, {"id": "w7", "text": "the"}, {"id": "w8", "text": "world,"}, {"id": "w9", "text": "but"}, {"id": "w10", "text": "its"}, {"id": "w11", "text": "origin"}, {"id": "w12", "text": "was"}, {"id": "w13", "text": "debated"}, {"id": "w14", "text": "for"}, {"id": "w15", "text": "a"}, {"id": "w16", "text": "long"}, {"id": "w17", "text": "time."}, {"id": "w18", "text": "The"}, {"id": "w19", "text": "linguist"}, {"id": "w20", "text": "Allen"}, {"id": "w21", "text": "Walker"}, {"id": "w22", "text": "Read"}, {"id": "w23", "text": "showed"}, {"id": "w24", "text": "that"}, {"id": "w25", "text": "it"}, {"id": "w26", "text": "first"}, {"id": "w27", "text": "appeared"}, {"id": "w28", "text": "in"}, {"id": "w29", "text": "a"}, {"id": "w30", "text": "Boston"}, {"id": "w31", "text": "novel"}, {"id": "w32", "text": "in"}, {"id": "w33", "text": "1839,"}, {"id": "w34", "text": "as"}, {"id": "w35", "text": "a"}, {"id": "w36", "text": "joke"}, {"id": "w37", "text": "abbreviation"}, {"id": "w38", "text": "of"}, {"id": "w39", "text": "oll"}, {"id": "w40", "text": "korrect,"}, {"id": "w41", "text": "a"}, {"id": "w42", "text": "deliberate"}, {"id": "w43", "text": "misspelling"}, {"id": "w44", "text": "of"}, {"id": "w45", "text": "all"}, {"id": "w46", "text": "correct."}, {"id": "w47", "text": "Such"}, {"id": "w48", "text": "jokey"}, {"id": "w49", "text": "abbreviations"}, {"id": "w50", "text": "were"}, {"id": "w51", "text": "forbidden"}, {"id": "w52", "text": "at"}, {"id": "w53", "text": "the"}, {"id": "w54", "text": "time."}, {"id": "w55", "text": "The"}, {"id": "w56", "text": "word"}, {"id": "w57", "text": "survived"}, {"id": "w58", "text": "partly"}, {"id": "w59", "text": "thanks"}, {"id": "w60", "text": "to"}, {"id": "w61", "text": "the"}, {"id": "w62", "text": "1840"}, {"id": "w63", "text": "presidential"}, {"id": "w64", "text": "debate,"}, {"id": "w65", "text": "when"}, {"id": "w66", "text": "supporters"}, {"id": "w67", "text": "of"}, {"id": "w68", "text": "Martin"}, {"id": "w69", "text": "Van"}, {"id": "w70", "text": "Buren,"}, {"id": "w71", "text": "nicknamed"}, {"id": "w72", "text": "Old"}, {"id": "w73", "text": "Kinderhook,"}, {"id": "w74", "text": "used"}, {"id": "w75", "text": "it"}, {"id": "w76", "text": "as"}, {"id": "w77", "text": "a"}, {"id": "w78", "text": "slogan."}]'::jsonb, '["w31", "w51", "w64"]'::jsonb, NULL, NULL, 'Select novel, forbidden, debate. The speaker says newspaper, fashionable, election.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-23', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'The first emoji', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The first widely used set of emoji was designed in 1999 by Shigetaka Kurita for a Japanese mobile phone museum. Each of the 176 symbols was only twelve pixels tall and twelve pixels high. The idea was to help people express emotion in short messages. Today the original set is held in the collection of the Museum of Modern Art in New Delhi.', 'The first widely used set of emoji was designed in 1999 by Shigetaka Kurita for a Japanese mobile phone company. Each of the 176 symbols was only twelve pixels wide and twelve pixels high. The idea was to help people express emotion in short messages. Today the original set is held in the collection of the Museum of Modern Art in New York.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "first"}, {"id": "w3", "text": "widely"}, {"id": "w4", "text": "used"}, {"id": "w5", "text": "set"}, {"id": "w6", "text": "of"}, {"id": "w7", "text": "emoji"}, {"id": "w8", "text": "was"}, {"id": "w9", "text": "designed"}, {"id": "w10", "text": "in"}, {"id": "w11", "text": "1999"}, {"id": "w12", "text": "by"}, {"id": "w13", "text": "Shigetaka"}, {"id": "w14", "text": "Kurita"}, {"id": "w15", "text": "for"}, {"id": "w16", "text": "a"}, {"id": "w17", "text": "Japanese"}, {"id": "w18", "text": "mobile"}, {"id": "w19", "text": "phone"}, {"id": "w20", "text": "museum."}, {"id": "w21", "text": "Each"}, {"id": "w22", "text": "of"}, {"id": "w23", "text": "the"}, {"id": "w24", "text": "176"}, {"id": "w25", "text": "symbols"}, {"id": "w26", "text": "was"}, {"id": "w27", "text": "only"}, {"id": "w28", "text": "twelve"}, {"id": "w29", "text": "pixels"}, {"id": "w30", "text": "tall"}, {"id": "w31", "text": "and"}, {"id": "w32", "text": "twelve"}, {"id": "w33", "text": "pixels"}, {"id": "w34", "text": "high."}, {"id": "w35", "text": "The"}, {"id": "w36", "text": "idea"}, {"id": "w37", "text": "was"}, {"id": "w38", "text": "to"}, {"id": "w39", "text": "help"}, {"id": "w40", "text": "people"}, {"id": "w41", "text": "express"}, {"id": "w42", "text": "emotion"}, {"id": "w43", "text": "in"}, {"id": "w44", "text": "short"}, {"id": "w45", "text": "messages."}, {"id": "w46", "text": "Today"}, {"id": "w47", "text": "the"}, {"id": "w48", "text": "original"}, {"id": "w49", "text": "set"}, {"id": "w50", "text": "is"}, {"id": "w51", "text": "held"}, {"id": "w52", "text": "in"}, {"id": "w53", "text": "the"}, {"id": "w54", "text": "collection"}, {"id": "w55", "text": "of"}, {"id": "w56", "text": "the"}, {"id": "w57", "text": "Museum"}, {"id": "w58", "text": "of"}, {"id": "w59", "text": "Modern"}, {"id": "w60", "text": "Art"}, {"id": "w61", "text": "in"}, {"id": "w62", "text": "New"}, {"id": "w63", "text": "Delhi."}]'::jsonb, '["w20", "w30", "w63"]'::jsonb, NULL, NULL, 'Select museum, tall, Delhi. The speaker says company, wide, York.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-24', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Cracking Linear B', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Clay tablets inscribed with a script called Linear B were discovered on the island of Cyprus around 1900. For half a century nobody could read them. In 1952, Michael Ventris, an archaeologist with a passion for codes, showed that the script recorded an early form of Greek. Disappointingly for some, most tablets turned out to be ordinary administrative poems, such as lists of goods and workers.', 'Clay tablets inscribed with a script called Linear B were discovered on the island of Crete around 1900. For half a century nobody could read them. In 1952, Michael Ventris, an architect with a passion for codes, showed that the script recorded an early form of Greek. Disappointingly for some, most tablets turned out to be ordinary administrative records, such as lists of goods and workers.', 10, 120, '[{"id": "w1", "text": "Clay"}, {"id": "w2", "text": "tablets"}, {"id": "w3", "text": "inscribed"}, {"id": "w4", "text": "with"}, {"id": "w5", "text": "a"}, {"id": "w6", "text": "script"}, {"id": "w7", "text": "called"}, {"id": "w8", "text": "Linear"}, {"id": "w9", "text": "B"}, {"id": "w10", "text": "were"}, {"id": "w11", "text": "discovered"}, {"id": "w12", "text": "on"}, {"id": "w13", "text": "the"}, {"id": "w14", "text": "island"}, {"id": "w15", "text": "of"}, {"id": "w16", "text": "Cyprus"}, {"id": "w17", "text": "around"}, {"id": "w18", "text": "1900."}, {"id": "w19", "text": "For"}, {"id": "w20", "text": "half"}, {"id": "w21", "text": "a"}, {"id": "w22", "text": "century"}, {"id": "w23", "text": "nobody"}, {"id": "w24", "text": "could"}, {"id": "w25", "text": "read"}, {"id": "w26", "text": "them."}, {"id": "w27", "text": "In"}, {"id": "w28", "text": "1952,"}, {"id": "w29", "text": "Michael"}, {"id": "w30", "text": "Ventris,"}, {"id": "w31", "text": "an"}, {"id": "w32", "text": "archaeologist"}, {"id": "w33", "text": "with"}, {"id": "w34", "text": "a"}, {"id": "w35", "text": "passion"}, {"id": "w36", "text": "for"}, {"id": "w37", "text": "codes,"}, {"id": "w38", "text": "showed"}, {"id": "w39", "text": "that"}, {"id": "w40", "text": "the"}, {"id": "w41", "text": "script"}, {"id": "w42", "text": "recorded"}, {"id": "w43", "text": "an"}, {"id": "w44", "text": "early"}, {"id": "w45", "text": "form"}, {"id": "w46", "text": "of"}, {"id": "w47", "text": "Greek."}, {"id": "w48", "text": "Disappointingly"}, {"id": "w49", "text": "for"}, {"id": "w50", "text": "some,"}, {"id": "w51", "text": "most"}, {"id": "w52", "text": "tablets"}, {"id": "w53", "text": "turned"}, {"id": "w54", "text": "out"}, {"id": "w55", "text": "to"}, {"id": "w56", "text": "be"}, {"id": "w57", "text": "ordinary"}, {"id": "w58", "text": "administrative"}, {"id": "w59", "text": "poems,"}, {"id": "w60", "text": "such"}, {"id": "w61", "text": "as"}, {"id": "w62", "text": "lists"}, {"id": "w63", "text": "of"}, {"id": "w64", "text": "goods"}, {"id": "w65", "text": "and"}, {"id": "w66", "text": "workers."}]'::jsonb, '["w16", "w32", "w59"]'::jsonb, NULL, NULL, 'Select Cyprus, archaeologist, poems. The speaker says Crete, architect, records.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-25', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'The fire of 1666', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The Great Fire of London began in a church in September 1666 and burned for four days. It destroyed more than thirteen thousand houses, many of them built of stone. After the fire, new rules required buildings to be made of brick or stone, streets were widened, and the first fire brigade companies were established in the city.', 'The Great Fire of London began in a bakery in September 1666 and burned for four days. It destroyed more than thirteen thousand houses, many of them built of wood. After the fire, new rules required buildings to be made of brick or stone, streets were widened, and the first fire insurance companies were established in the city.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "Great"}, {"id": "w3", "text": "Fire"}, {"id": "w4", "text": "of"}, {"id": "w5", "text": "London"}, {"id": "w6", "text": "began"}, {"id": "w7", "text": "in"}, {"id": "w8", "text": "a"}, {"id": "w9", "text": "church"}, {"id": "w10", "text": "in"}, {"id": "w11", "text": "September"}, {"id": "w12", "text": "1666"}, {"id": "w13", "text": "and"}, {"id": "w14", "text": "burned"}, {"id": "w15", "text": "for"}, {"id": "w16", "text": "four"}, {"id": "w17", "text": "days."}, {"id": "w18", "text": "It"}, {"id": "w19", "text": "destroyed"}, {"id": "w20", "text": "more"}, {"id": "w21", "text": "than"}, {"id": "w22", "text": "thirteen"}, {"id": "w23", "text": "thousand"}, {"id": "w24", "text": "houses,"}, {"id": "w25", "text": "many"}, {"id": "w26", "text": "of"}, {"id": "w27", "text": "them"}, {"id": "w28", "text": "built"}, {"id": "w29", "text": "of"}, {"id": "w30", "text": "stone."}, {"id": "w31", "text": "After"}, {"id": "w32