    ('q-pl90-hiw-33', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Chappe''s semaphore', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'In the 1790s, the French engineer Claude Chappe built a network of bridges with movable wooden arms. Operators watched the next tower through a window and copied the positions of its arms, passing coded messages across the country far faster than a rider on horseback. The system was eventually replaced by the steam telegraph in the nineteenth century.', 'In the 1790s, the French engineer Claude Chappe built a network of towers with movable wooden arms. Operators watched the next tower through a telescope and copied the positions of its arms, passing coded messages across the country far faster than a rider on horseback. The system was eventually replaced by the electric telegraph in the nineteenth century.', 10, 120, '[{"id": "w1", "text": "In"}, {"id": "w2", "text": "the"}, {"id": "w3", "text": "1790s,"}, {"id": "w4", "text": "the"}, {"id": "w5", "text": "French"}, {"id": "w6", "text": "engineer"}, {"id": "w7", "text": "Claude"}, {"id": "w8", "text": "Chappe"}, {"id": "w9", "text": "built"}, {"id": "w10", "text": "a"}, {"id": "w11", "text": "network"}, {"id": "w12", "text": "of"}, {"id": "w13", "text": "bridges"}, {"id": "w14", "text": "with"}, {"id": "w15", "text": "movable"}, {"id": "w16", "text": "wooden"}, {"id": "w17", "text": "arms."}, {"id": "w18", "text": "Operators"}, {"id": "w19", "text": "watched"}, {"id": "w20", "text": "the"}, {"id": "w21", "text": "next"}, {"id": "w22", "text": "tower"}, {"id": "w23", "text": "through"}, {"id": "w24", "text": "a"}, {"id": "w25", "text": "window"}, {"id": "w26", "text": "and"}, {"id": "w27", "text": "copied"}, {"id": "w28", "text": "the"}, {"id": "w29", "text": "positions"}, {"id": "w30", "text": "of"}, {"id": "w31", "text": "its"}, {"id": "w32", "text": "arms,"}, {"id": "w33", "text": "passing"}, {"id": "w34", "text": "coded"}, {"id": "w35", "text": "messages"}, {"id": "w36", "text": "across"}, {"id": "w37", "text": "the"}, {"id": "w38", "text": "country"}, {"id": "w39", "text": "far"}, {"id": "w40", "text": "faster"}, {"id": "w41", "text": "than"}, {"id": "w42", "text": "a"}, {"id": "w43", "text": "rider"}, {"id": "w44", "text": "on"}, {"id": "w45", "text": "horseback."}, {"id": "w46", "text": "The"}, {"id": "w47", "text": "system"}, {"id": "w48", "text": "was"}, {"id": "w49", "text": "eventually"}, {"id": "w50", "text": "replaced"}, {"id": "w51", "text": "by"}, {"id": "w52", "text": "the"}, {"id": "w53", "text": "steam"}, {"id": "w54", "text": "telegraph"}, {"id": "w55", "text": "in"}, {"id": "w56", "text": "the"}, {"id": "w57", "text": "nineteenth"}, {"id": "w58", "text": "century."}]'::jsonb, '["w13", "w25", "w53"]'::jsonb, NULL, NULL, 'Select bridges, window, steam. The speaker says towers, telescope, electric.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-34', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Ada Lovelace', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'In 1843, Ada Lovelace published detailed notes on a electrical computer designed by Charles Babbage, called the Analytical Engine. The machine was never completed, but her notes included a method for calculating a sequence of numbers, often described as the first computer poem. She also suggested that such machines might one day work with symbols beyond letters, such as musical notes.', 'In 1843, Ada Lovelace published detailed notes on a mechanical computer designed by Charles Babbage, called the Analytical Engine. The machine was never completed, but her notes included a method for calculating a sequence of numbers, often described as the first computer program. She also suggested that such machines might one day work with symbols beyond numbers, such as musical notes.', 10, 120, '[{"id": "w1", "text": "In"}, {"id": "w2", "text": "1843,"}, {"id": "w3", "text": "Ada"}, {"id": "w4", "text": "Lovelace"}, {"id": "w5", "text": "published"}, {"id": "w6", "text": "detailed"}, {"id": "w7", "text": "notes"}, {"id": "w8", "text": "on"}, {"id": "w9", "text": "a"}, {"id": "w10", "text": "electrical"}, {"id": "w11", "text": "computer"}, {"id": "w12", "text": "designed"}, {"id": "w13", "text": "by"}, {"id": "w14", "text": "Charles"}, {"id": "w15", "text": "Babbage,"}, {"id": "w16", "text": "called"}, {"id": "w17", "text": "the"}, {"id": "w18", "text": "Analytical"}, {"id": "w19", "text": "Engine."}, {"id": "w20", "text": "The"}, {"id": "w21", "text": "machine"}, {"id": "w22", "text": "was"}, {"id": "w23", "text": "never"}, {"id": "w24", "text": "completed,"}, {"id": "w25", "text": "but"}, {"id": "w26", "text": "her"}, {"id": "w27", "text": "notes"}, {"id": "w28", "text": "included"}, {"id": "w29", "text": "a"}, {"id": "w30", "text": "method"}, {"id": "w31", "text": "for"}, {"id": "w32", "text": "calculating"}, {"id": "w33", "text": "a"}, {"id": "w34", "text": "sequence"}, {"id": "w35", "text": "of"}, {"id": "w36", "text": "numbers,"}, {"id": "w37", "text": "often"}, {"id": "w38", "text": "described"}, {"id": "w39", "text": "as"}, {"id": "w40", "text": "the"}, {"id": "w41", "text": "first"}, {"id": "w42", "text": "computer"}, {"id": "w43", "text": "poem."}, {"id": "w44", "text": "She"}, {"id": "w45", "text": "also"}, {"id": "w46", "text": "suggested"}, {"id": "w47", "text": "that"}, {"id": "w48", "text": "such"}, {"id": "w49", "text": "machines"}, {"id": "w50", "text": "might"}, {"id": "w51", "text": "one"}, {"id": "w52", "text": "day"}, {"id": "w53", "text": "work"}, {"id": "w54", "text": "with"}, {"id": "w55", "text": "symbols"}, {"id": "w56", "text": "beyond"}, {"id": "w57", "text": "letters,"}, {"id": "w58", "text": "such"}, {"id": "w59", "text": "as"}, {"id": "w60", "text": "musical"}, {"id": "w61", "text": "notes."}]'::jsonb, '["w10", "w43", "w57"]'::jsonb, NULL, NULL, 'Select electrical, poem, letters. The speaker says mechanical, program, numbers.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-35', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Codebreakers at Bletchley Park', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'During the Second World War, codebreakers at Bletchley Park in England worked to read handwritten German messages. Mathematicians including Alan Turing designed electromechanical machines called bombes to speed up the work. Around three quarters of the staff were volunteers, and their achievements remained secret for weeks after the war ended.', 'During the Second World War, codebreakers at Bletchley Park in England worked to read encrypted German messages. Mathematicians including Alan Turing designed electromechanical machines called bombes to speed up the work. Around three quarters of the staff were women, and their achievements remained secret for decades after the war ended.', 10, 120, '[{"id": "w1", "text": "During"}, {"id": "w2", "text": "the"}, {"id": "w3", "text": "Second"}, {"id": "w4", "text": "World"}, {"id": "w5", "text": "War,"}, {"id": "w6", "text": "codebreakers"}, {"id": "w7", "text": "at"}, {"id": "w8", "text": "Bletchley"}, {"id": "w9", "text": "Park"}, {"id": "w10", "text": "in"}, {"id": "w11", "text": "England"}, {"id": "w12", "text": "worked"}, {"id": "w13", "text": "to"}, {"id": "w14", "text": "read"}, {"id": "w15", "text": "handwritten"}, {"id": "w16", "text": "German"}, {"id": "w17", "text": "messages."}, {"id": "w18", "text": "Mathematicians"}, {"id": "w19", "text": "including"}, {"id": "w20", "text": "Alan"}, {"id": "w21", "text": "Turing"}, {"id": "w22", "text": "designed"}, {"id": "w23", "text": "electromechanical"}, {"id": "w24", "text": "machines"}, {"id": "w25", "text": "called"}, {"id": "w26", "text": "bombes"}, {"id": "w27", "text": "to"}, {"id": "w28", "text": "speed"}, {"id": "w29", "text": "up"}, {"id": "w30", "text": "the"}, {"id": "w31", "text": "work."}, {"id": "w32", "text": "Around"}, {"id": "w33", "text": "three"}, {"id": "w34", "text": "quarters"}, {"id": "w35", "text": "of"}, {"id": "w36", "text": "the"}, {"id": "w37", "text": "staff"}, {"id": "w38", "text": "were"}, {"id": "w39", "text": "volunteers,"}, {"id": "w40", "text": "and"}, {"id": "w41", "text": "their"}, {"id": "w42", "text": "achievements"}, {"id": "w43", "text": "remained"}, {"id": "w44", "text": "secret"}, {"id": "w45", "text": "for"}, {"id": "w46", "text": "weeks"}, {"id": "w47", "text": "after"}, {"id": "w48", "text": "the"}, {"id": "w49", "text": "war"}, {"id": "w50", "text": "ended."}]'::jsonb, '["w15", "w39", "w46"]'::jsonb, NULL, NULL, 'Select handwritten, volunteers, weeks. The speaker says encrypted, women, decades.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-36', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Hedy Lamarr', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Hedy Lamarr was a famous Hollywood singer, but she was also an inventor. In 1942, she and the composer George Antheil patented a system in which a radio signal jumped rapidly between countries, making it hard to jam. The navy did not use it at the time, but the principle of frequency hopping later contributed to wireless medicines.', 'Hedy Lamarr was a famous Hollywood actress, but she was also an inventor. In 1942, she and the composer George Antheil patented a system in which a radio signal jumped rapidly between frequencies, making it hard to jam. The navy did not use it at the time, but the principle of frequency hopping later contributed to wireless technologies.', 10, 120, '[{"id": "w1", "text": "Hedy"}, {"id": "w2", "text": "Lamarr"}, {"id": "w3", "text": "was"}, {"id": "w4", "text": "a"}, {"id": "w5", "text": "famous"}, {"id": "w6", "text": "Hollywood"}, {"id": "w7", "text": "singer,"}, {"id": "w8", "text": "but"}, {"id": "w9", "text": "she"}, {"id": "w10", "text": "was"}, {"id": "w11", "text": "also"}, {"id": "w12", "text": "an"}, {"id": "w13", "text": "inventor."}, {"id": "w14", "text": "In"}, {"id": "w15", "text": "1942,"}, {"id": "w16", "text": "she"}, {"id": "w17", "text": "and"}, {"id": "w18", "text": "the"}, {"id": "w19", "text": "composer"}, {"id": "w20", "text": "George"}, {"id": "w21", "text": "Antheil"}, {"id": "w22", "text": "patented"}, {"id": "w23", "text": "a"}, {"id": "w24", "text": "system"}, {"id": "w25", "text": "in"}, {"id": "w26", "text": "which"}, {"id": "w27", "text": "a"}, {"id": "w28", "text": "radio"}, {"id": "w29", "text": "signal"}, {"id": "w30", "text": "jumped"}, {"id": "w31", "text": "rapidly"}, {"id": "w32", "text": "between"}, {"id": "w33", "text": "countries,"}, {"id": "w34", "text": "making"}, {"id": "w35", "text": "it"}, {"id": "w36", "text": "hard"}, {"id": "w37", "text": "to"}, {"id": "w38", "text": "jam."}, {"id": "w39", "text": "The"}, {"id": "w40", "text": "navy"}, {"id": "w41", "text": "did"}, {"id": "w42", "text": "not"}, {"id": "w43", "text": "use"}, {"id": "w44", "text": "it"}, {"id": "w45", "text": "at"}, {"id": "w46", "text": "the"}, {"id": "w47", "text": "time,"}, {"id": "w48", "text": "but"}, {"id": "w49", "text": "the"}, {"id": "w50", "text": "principle"}, {"id": "w51", "text": "of"}, {"id": "w52", "text": "frequency"}, {"id": "w53", "text": "hopping"}, {"id": "w54", "text": "later"}, {"id": "w55", "text": "contributed"}, {"id": "w56", "text": "to"}, {"id": "w57", "text": "wireless"}, {"id": "w58", "text": "medicines."}]'::jsonb, '["w7", "w33", "w58"]'::jsonb, NULL, NULL, 'Select singer, countries, medicines. The speaker says actress, frequencies, technologies.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-37', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'The transistor', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The transistor was invented at Bell Laboratories in the United States in 1974. It could amplify and switch electrical signals like the vacuum tubes used in early computers, but it was much louder and used far less power. Its three inventors shared a Nobel Prize, and today a single computer chip can contain dozens of transistors.', 'The transistor was invented at Bell Laboratories in the United States in 1947. It could amplify and switch electrical signals like the vacuum tubes used in early computers, but it was much smaller and used far less power. Its three inventors shared a Nobel Prize, and today a single computer chip can contain billions of transistors.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "transistor"}, {"id": "w3", "text": "was"}, {"id": "w4", "text": "invented"}, {"id": "w5", "text": "at"}, {"id": "w6", "text": "Bell"}, {"id": "w7", "text": "Laboratories"}, {"id": "w8", "text": "in"}, {"id": "w9", "text": "the"}, {"id": "w10", "text": "United"}, {"id": "w11", "text": "States"}, {"id": "w12", "text": "in"}, {"id": "w13", "text": "1974."}, {"id": "w14", "text": "It"}, {"id": "w15", "text": "could"}, {"id": "w16", "text": "amplify"}, {"id": "w17", "text": "and"}, {"id": "w18", "text": "switch"}, {"id": "w19", "text": "electrical"}, {"id": "w20", "text": "signals"}, {"id": "w21", "text": "like"}, {"id": "w22", "text": "the"}, {"id": "w23", "text": "vacuum"}, {"id": "w24", "text": "tubes"}, {"id": "w25", "text": "used"}, {"id": "w26", "text": "in"}, {"id": "w27", "text": "early"}, {"id": "w28", "text": "computers,"}, {"id": "w29", "text": "but"}, {"id": "w30", "text": "it"}, {"id": "w31", "text": "was"}, {"id": "w32", "text": "much"}, {"id": "w33", "text": "louder"}, {"id": "w34", "text": "and"}, {"id": "w35", "text": "used"}, {"id": "w36", "text": "far"}, {"id": "w37", "text": "less"}, {"id": "w38", "text": "power."}, {"id": "w39", "text": "Its"}, {"id": "w40", "text": "three"}, {"id": "w41", "text": "inventors"}, {"id": "w42", "text": "shared"}, {"id": "w43", "text": "a"}, {"id": "w44", "text": "Nobel"}, {"id": "w45", "text": "Prize,"}, {"id": "w46", "text": "and"}, {"id": "w47", "text": "today"}, {"id": "w48", "text": "a"}, {"id": "w49", "text": "single"}, {"id": "w50", "text": "computer"}, {"id": "w51", "text": "chip"}, {"id": "w52", "text": "can"}, {"id": "w53", "text": "contain"}, {"id": "w54", "text": "dozens"}, {"id": "w55", "text": "of"}, {"id": "w56", "text": "transistors."}]'::jsonb, '["w13", "w33", "w54"]'::jsonb, NULL, NULL, 'Select 1974, louder, dozens. The speaker says 1947, smaller, billions.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-38', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'A moth in the machine', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'In 1947, operators of the Harvard Mark II computer found a mouse trapped in one of its relays. They taped it into the logbook with the note that this was the first actual case of a bug being found. The joke worked because engineers had already used the word bug for ideas in machines for decades; even Thomas Edison had used it in the 1970s.', 'In 1947, operators of the Harvard Mark II computer found a moth trapped in one of its relays. They taped it into the logbook with the note that this was the first actual case of a bug being found. The joke worked because engineers had already used the word bug for faults in machines for decades; even Thomas Edison had used it in the 1870s.', 10, 120, '[{"id": "w1", "text": "In"}, {"id": "w2", "text": "1947,"}, {"id": "w3", "text": "operators"}, {"id": "w4", "text": "of"}, {"id": "w5", "text": "the"}, {"id": "w6", "text": "Harvard"}, {"id": "w7", "text": "Mark"}, {"id": "w8", "text": "II"}, {"id": "w9", "text": "computer"}, {"id": "w10", "text": "found"}, {"id": "w11", "text": "a"}, {"id": "w12", "text": "mouse"}, {"id": "w13", "text": "trapped"}, {"id": "w14", "text": "in"}, {"id": "w15", "text": "one"}, {"id": "w16", "text": "of"}, {"id": "w17", "text": "its"}, {"id": "w18", "text": "relays."}, {"id": "w19", "text": "They"}, {"id": "w20", "text": "taped"}, {"id": "w21", "text": "it"}, {"id": "w22", "text": "into"}, {"id": "w23", "text": "the"}, {"id": "w24", "text": "logbook"}, {"id": "w25", "text": "with"}, {"id": "w26", "text": "the"}, {"id": "w27", "text": "note"}, {"id": "w28", "text": "that"}, {"id": "w29", "text": "this"}, {"id": "w30", "text": "was"}, {"id": "w31", "text": "t