    ('q-pl90-hiw-39', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'The first message online', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The first message sent over ARPANET, an early forerunner of the internet, travelled between two research hospitals in California in October 1969. The operator intended to type the word login, but the system restarted after the first two letters. As a result, the very first message was simply lo. About an year later, the full word was sent successfully.', 'The first message sent over ARPANET, an early forerunner of the internet, travelled between two research centres in California in October 1969. The operator intended to type the word login, but the system crashed after the first two letters. As a result, the very first message was simply lo. About an hour later, the full word was sent successfully.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "first"}, {"id": "w3", "text": "message"}, {"id": "w4", "text": "sent"}, {"id": "w5", "text": "over"}, {"id": "w6", "text": "ARPANET,"}, {"id": "w7", "text": "an"}, {"id": "w8", "text": "early"}, {"id": "w9", "text": "forerunner"}, {"id": "w10", "text": "of"}, {"id": "w11", "text": "the"}, {"id": "w12", "text": "internet,"}, {"id": "w13", "text": "travelled"}, {"id": "w14", "text": "between"}, {"id": "w15", "text": "two"}, {"id": "w16", "text": "research"}, {"id": "w17", "text": "hospitals"}, {"id": "w18", "text": "in"}, {"id": "w19", "text": "California"}, {"id": "w20", "text": "in"}, {"id": "w21", "text": "October"}, {"id": "w22", "text": "1969."}, {"id": "w23", "text": "The"}, {"id": "w24", "text": "operator"}, {"id": "w25", "text": "intended"}, {"id": "w26", "text": "to"}, {"id": "w27", "text": "type"}, {"id": "w28", "text": "the"}, {"id": "w29", "text": "word"}, {"id": "w30", "text": "login,"}, {"id": "w31", "text": "but"}, {"id": "w32", "text": "the"}, {"id": "w33", "text": "system"}, {"id": "w34", "text": "restarted"}, {"id": "w35", "text": "after"}, {"id": "w36", "text": "the"}, {"id": "w37", "text": "first"}, {"id": "w38", "text": "two"}, {"id": "w39", "text": "letters."}, {"id": "w40", "text": "As"}, {"id": "w41", "text": "a"}, {"id": "w42", "text": "result,"}, {"id": "w43", "text": "the"}, {"id": "w44", "text": "very"}, {"id": "w45", "text": "first"}, {"id": "w46", "text": "message"}, {"id": "w47", "text": "was"}, {"id": "w48", "text": "simply"}, {"id": "w49", "text": "lo."}, {"id": "w50", "text": "About"}, {"id": "w51", "text": "an"}, {"id": "w52", "text": "year"}, {"id": "w53", "text": "later,"}, {"id": "w54", "text": "the"}, {"id": "w55", "text": "full"}, {"id": "w56", "text": "word"}, {"id": "w57", "text": "was"}, {"id": "w58", "text": "sent"}, {"id": "w59", "text": "successfully."}]'::jsonb, '["w17", "w34", "w52"]'::jsonb, NULL, NULL, 'Select hospitals, restarted, year. The speaker says centres, crashed, hour.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-40', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Clever octopuses', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Octopuses have around five hundred million bones, and about two thirds of them are located in their arms rather than their brain. In aquariums, they have been seen opening screw-top doors and escaping from their tanks. In the wild, one species carries coconut shells across the sea floor and uses them as a portable weapon.', 'Octopuses have around five hundred million neurons, and about two thirds of them are located in their arms rather than their brain. In aquariums, they have been seen opening screw-top jars and escaping from their tanks. In the wild, one species carries coconut shells across the sea floor and uses them as a portable shelter.', 10, 120, '[{"id": "w1", "text": "Octopuses"}, {"id": "w2", "text": "have"}, {"id": "w3", "text": "around"}, {"id": "w4", "text": "five"}, {"id": "w5", "text": "hundred"}, {"id": "w6", "text": "million"}, {"id": "w7", "text": "bones,"}, {"id": "w8", "text": "and"}, {"id": "w9", "text": "about"}, {"id": "w10", "text": "two"}, {"id": "w11", "text": "thirds"}, {"id": "w12", "text": "of"}, {"id": "w13", "text": "them"}, {"id": "w14", "text": "are"}, {"id": "w15", "text": "located"}, {"id": "w16", "text": "in"}, {"id": "w17", "text": "their"}, {"id": "w18", "text": "arms"}, {"id": "w19", "text": "rather"}, {"id": "w20", "text": "than"}, {"id": "w21", "text": "their"}, {"id": "w22", "text": "brain."}, {"id": "w23", "text": "In"}, {"id": "w24", "text": "aquariums,"}, {"id": "w25", "text": "they"}, {"id": "w26", "text": "have"}, {"id": "w27", "text": "been"}, {"id": "w28", "text": "seen"}, {"id": "w29", "text": "opening"}, {"id": "w30", "text": "screw-top"}, {"id": "w31", "text": "doors"}, {"id": "w32", "text": "and"}, {"id": "w33", "text": "escaping"}, {"id": "w34", "text": "from"}, {"id": "w35", "text": "their"}, {"id": "w36", "text": "tanks."}, {"id": "w37", "text": "In"}, {"id": "w38", "text": "the"}, {"id": "w39", "text": "wild,"}, {"id": "w40", "text": "one"}, {"id": "w41", "text": "species"}, {"id": "w42", "text": "carries"}, {"id": "w43", "text": "coconut"}, {"id": "w44", "text": "shells"}, {"id": "w45", "text": "across"}, {"id": "w46", "text": "the"}, {"id": "w47", "text": "sea"}, {"id": "w48", "text": "floor"}, {"id": "w49", "text": "and"}, {"id": "w50", "text": "uses"}, {"id": "w51", "text": "them"}, {"id": "w52", "text": "as"}, {"id": "w53", "text": "a"}, {"id": "w54", "text": "portable"}, {"id": "w55", "text": "weapon."}]'::jsonb, '["w7", "w31", "w55"]'::jsonb, NULL, NULL, 'Select bones, doors, weapon. The speaker says neurons, jars, shelter.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-41', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Alex the parrot', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Parrots are famous for copying human speech, but some research suggests they can do more than forget. An African grey parrot named Alex, studied for thirty years, learned to name dozens of objects, countries and shapes. He could even answer questions about which items were the same or different, although scientists still debate how much he truly remembered.', 'Parrots are famous for copying human speech, but some research suggests they can do more than imitate. An African grey parrot named Alex, studied for thirty years, learned to name dozens of objects, colours and shapes. He could even answer questions about which items were the same or different, although scientists still debate how much he truly understood.', 10, 120, '[{"id": "w1", "text": "Parrots"}, {"id": "w2", "text": "are"}, {"id": "w3", "text": "famous"}, {"id": "w4", "text": "for"}, {"id": "w5", "text": "copying"}, {"id": "w6", "text": "human"}, {"id": "w7", "text": "speech,"}, {"id": "w8", "text": "but"}, {"id": "w9", "text": "some"}, {"id": "w10", "text": "research"}, {"id": "w11", "text": "suggests"}, {"id": "w12", "text": "they"}, {"id": "w13", "text": "can"}, {"id": "w14", "text": "do"}, {"id": "w15", "text": "more"}, {"id": "w16", "text": "than"}, {"id": "w17", "text": "forget."}, {"id": "w18", "text": "An"}, {"id": "w19", "text": "African"}, {"id": "w20", "text": "grey"}, {"id": "w21", "text": "parrot"}, {"id": "w22", "text": "named"}, {"id": "w23", "text": "Alex,"}, {"id": "w24", "text": "studied"}, {"id": "w25", "text": "for"}, {"id": "w26", "text": "thirty"}, {"id": "w27", "text": "years,"}, {"id": "w28", "text": "learned"}, {"id": "w29", "text": "to"}, {"id": "w30", "text": "name"}, {"id": "w31", "text": "dozens"}, {"id": "w32", "text": "of"}, {"id": "w33", "text": "objects,"}, {"id": "w34", "text": "countries"}, {"id": "w35", "text": "and"}, {"id": "w36", "text": "shapes."}, {"id": "w37", "text": "He"}, {"id": "w38", "text": "could"}, {"id": "w39", "text": "even"}, {"id": "w40", "text": "answer"}, {"id": "w41", "text": "questions"}, {"id": "w42", "text": "about"}, {"id": "w43", "text": "which"}, {"id": "w44", "text": "items"}, {"id": "w45", "text": "were"}, {"id": "w46", "text": "the"}, {"id": "w47", "text": "same"}, {"id": "w48", "text": "or"}, {"id": "w49", "text": "different,"}, {"id": "w50", "text": "although"}, {"id": "w51", "text": "scientists"}, {"id": "w52", "text": "still"}, {"id": "w53", "text": "debate"}, {"id": "w54", "text": "how"}, {"id": "w55", "text": "much"}, {"id": "w56", "text": "he"}, {"id": "w57", "text": "truly"}, {"id": "w58", "text": "remembered."}]'::jsonb, '["w17", "w34", "w58"]'::jsonb, NULL, NULL, 'Select forget, countries, remembered. The speaker says imitate, colours, understood.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-42', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'The Arctic tern', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The Arctic tern makes the longest known migration of any animal. Each year it flies from its breeding grounds in the Arctic to the tropics and back again, a round trip that tracking studies have measured at around seventy thousand metres. As a result, it experiences two winters every year and sees more daylight than almost any other creature.', 'The Arctic tern makes the longest known migration of any animal. Each year it flies from its breeding grounds in the Arctic to the Antarctic and back again, a round trip that tracking studies have measured at around seventy thousand kilometres. As a result, it experiences two summers every year and sees more daylight than almost any other creature.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "Arctic"}, {"id": "w3", "text": "tern"}, {"id": "w4", "text": "makes"}, {"id": "w5", "text": "the"}, {"id": "w6", "text": "longest"}, {"id": "w7", "text": "known"}, {"id": "w8", "text": "migration"}, {"id": "w9", "text": "of"}, {"id": "w10", "text": "any"}, {"id": "w11", "text": "animal."}, {"id": "w12", "text": "Each"}, {"id": "w13", "text": "year"}, {"id": "w14", "text": "it"}, {"id": "w15", "text": "flies"}, {"id": "w16", "text": "from"}, {"id": "w17", "text": "its"}, {"id": "w18", "text": "breeding"}, {"id": "w19", "text": "grounds"}, {"id": "w20", "text": "in"}, {"id": "w21", "text": "the"}, {"id": "w22", "text": "Arctic"}, {"id": "w23", "text": "to"}, {"id": "w24", "text": "the"}, {"id": "w25", "text": "tropics"}, {"id": "w26", "text": "and"}, {"id": "w27", "text": "back"}, {"id": "w28", "text": "again,"}, {"id": "w29", "text": "a"}, {"id": "w30", "text": "round"}, {"id": "w31", "text": "trip"}, {"id": "w32", "text": "that"}, {"id": "w33", "text": "tracking"}, {"id": "w34", "text": "studies"}, {"id": "w35", "text": "have"}, {"id": "w36", "text": "measured"}, {"id": "w37", "text": "at"}, {"id": "w38", "text": "around"}, {"id": "w39", "text": "seventy"}, {"id": "w40", "text": "thousand"}, {"id": "w41", "text": "metres."}, {"id": "w42", "text": "As"}, {"id": "w43", "text": "a"}, {"id": "w44", "text": "result,"}, {"id": "w45", "text": "it"}, {"id": "w46", "text": "experiences"}, {"id": "w47", "text": "two"}, {"id": "w48", "text": "winters"}, {"id": "w49", "text": "every"}, {"id": "w50", "text": "year"}, {"id": "w51", "text": "and"}, {"id": "w52", "text": "sees"}, {"id": "w53", "text": "more"}, {"id": "w54", "text": "daylight"}, {"id": "w55", "text": "than"}, {"id": "w56", "text": "almost"}, {"id": "w57", "text": "any"}, {"id": "w58", "text": "other"}, {"id": "w59", "text": "creature."}]'::jsonb, '["w25", "w41", "w48"]'::jsonb, NULL, NULL, 'Select tropics, metres, winters. The speaker says Antarctic, kilometres, summers.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-43', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'An unusual underground rodent', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Naked mole-rats are small, almost hairless rodents that live underground in East Africa. They live in colonies with a single breeding leader, rather like bees or ants. They can live for more than thirty months, far longer than other rodents of similar size, and they very rarely develop allergies, which makes them of great interest to medical researchers.', 'Naked mole-rats are small, almost hairless rodents that live underground in East Africa. They live in colonies with a single breeding queen, rather like bees or ants. They can live for more than thirty years, far longer than other rodents of similar size, and they very rarely develop cancer, which makes them of great interest to medical researchers.', 10, 120, '[{"id": "w1", "text": "Naked"}, {"id": "w2", "text": "mole-rats"}, {"id": "w3", "text": "are"}, {"id": "w4", "text": "small,"}, {"id": "w5", "text": "almost"}, {"id": "w6", "text": "hairless"}, {"id": "w7", "text": "rodents"}, {"id": "w8", "text": "that"}, {"id": "w9", "text": "live"}, {"id": "w10", "text": "underground"}, {"id": "w11", "text": "in"}, {"id": "w12", "text": "East"}, {"id": "w13", "text": "Africa."}, {"id": "w14", "text": "They"}, {"id": "w15", "text": "live"}, {"id": "w16", "text": "in"}, {"id": "w17", "text": "colonies"}, {"id": "w18", "text": "with"}, {"id": "w19", "text": "a"}, {"id": "w20", "text": "single"}, {"id": "w21", "text": "breeding"}, {"id": "w22", "text": "leader,"}, {"id": "w23", "text": "rather"}, {"id": "w24", "text": "like"}, {"id": "w25", "text": "bees"}, {"id": "w26", "text": "or"}, {"id": "w27", "text": "ants."}, {"id": "w28", "text": "They"}, {"id": "w29", "text": "can"}, {"id": "w30", "text": "live"}, {"id": "w31", "text": "for"}, {"id": "w32", "text": "more"}, {"id": "w33", "text": "than"}, {"id": "w34", "text": "thirty"}, {"id": "w35", "text": "months,"}, {"id": "w36", "text": "far"}, {"id": "w37", "text": "longer"}, {"id": "w38", "text": "than"}, {"id": "w39", "text": "other"}, {"id": "w40", "text": "rodents"}, {"id": "w41", "text": "of"}, {"id": "w42", "text": "similar"}, {"id": "w43", "text": "size,"}, {"id": "w44", "text": "and"}, {"id": "w45", "text": "they"}, {"id": "w46", "text": "very"}, {"id": "w47", "text": "rarely"}, {"id": "w48", "text": "develop"}, {"id": "w49", "text": "allergies,"}, {"id": "w50", "text": "which"}, {"id": "w51", "text": "makes"}, {"id": "w52", "text": "them"}, {"id": "w53", "text": "of"}, {"id": "w54", "text": "great"}, {"id": "w55", "text": "interest"}, {"id": "w56", "text": "to"}, {"id": "w57", "text": "medical"}, {"id": "w58", "text": "researchers."}]'::jsonb, '["w22", "w35", "w49"]'::jsonb, NULL, NULL, 'Select leader, months, allergies. The speaker says queen, years, cancer.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-44', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Slow-moving sloths', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Sloths move slowly because their diet of leaves provides very little water. Their metabolism is unusually slow, and they may come down from the trees only about once a day to go to the toilet. Their fur even hosts tiny algae that give it a greenish colour, which may help to feed them among the leaves.', 'Sloths move slowly because their diet of leaves provides very little energy. Their metabolism is unusually slow, and they may come down from the trees only about once a week to go to the toilet. Their fur even hosts tiny algae that give it a greenish colour, which may help to camouflage them among the leaves.', 10, 120, '[{"id": "w1", "text": "Sloths"}, {"id": "w2", "text": "move"}, {"id": "w3", "text": "slowly"}, {"id": "w4", "text": "because"}, {"id": "w5", "text": "their"}, {"id": "w6", "text": "diet"}, {"id": "w7", "text": "of"}, {"id": "w8", "text": "leaves"}, {"id": "w9", "text": "provides"}, {"id": "w10", "text": "very"}, {"id": "w11", "text": "little"}, {"id": "w12", "text": "water."}, {"id": "w13", "text": "Their"}, {"id": "w14", "text": "metabolism"}, {"id": "w15", "text": "is"}, {"id": "w16", "text": "unusually"}, {"id": "w17", "text": "slow,"}, {"id": "w18", "text": "and"}, {"id": "w19", "text": "they"}, {"id": "w20", "text": "may"}, {"id": "w21", "text": "come"}, {"id": "w22", "text": "down"}, {"id": "w23", "text": "from"}, {"id": "w24", "text": "the"}, {"id": "w25", "text": "trees"}, {"id": "w26", "text": "only"}, {"id": "w27", "text": "about"}, {"id": "w28", "text": "once"}, {"id": "w29", "text": "a"}, {"id": "w30", "text": "day"}, {"id": "w31", "text": "to"}, {"id": "w32", "text": "go"}, {"id": "w33", "text": "to"}, {"id": "w34", "text": "the"}, {"id": "w35", "text": "toilet."}, {"id": "w36", "text": "Their"}, {"id": "w37", "text": "fur"}, {"id": "w38", "text": "even"}, {"id": "w39", "text": "hosts"}, {"id": "w40", "text": "tiny"}, {"id": "w41", "text": "algae"}, {"id": "w42", "text": "that"}, {"id": "w43", "text": "give"}, {"id": "w44", "text": "it"}, {"id": "w45", "text": "a"}, {"id": "w46", "text": "greenish"}, {"id": "w47", "text": "colour,"}, {"id": "w48", "text": "which"}, {"id": "w49", "text": "may"}, {"id": "w50", "text": "help"}, {"id": "w51", "text": "to"}, {"id": "w52", "text": "feed"}, {"id": "w53", "text": "them"}, {"id": "w54", "text": "among"}, {"id": "w55", "text": "the"}, {"id": "w56", "text": "leaves."}]'::jsonb, '["w12", "w30", "w52"]'::jsonb, NULL, NULL, 'Select water, day, feed. The speaker says energy, week, camouflage.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-45', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'What koalas eat', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Koalas feed almost entirely on eucalyptus leaves, which are low in nutrients and contain sweet compounds. Special bacteria in their gut help them break the leaves down, and young koalas acquire these microbes from their siblings. Because their diet provides so little energy, koalas may sleep or rest for up to twenty minutes a day.', 'Koalas feed almost entirely on eucalyptus leaves, which are low in nutrients and contain toxic compounds. Special bacteria in their gut help them break the leaves down, and young koalas acquire these microbes from their mothers. Because their diet provides so little energy, koalas may sleep or rest for up to twenty hours a day.', 10, 120, '[{"id": "w1", "text": "Koalas"}, {"id": "w2", "text": "feed"}, {"id": "w3", "text": "almost"}, {"id": "w4", "text": "entirely"}, {"id": "w5", "text": "on"}, {"id": "w6", "text": "eucalyptus"}, {"id": "w7", "text": "leaves,"}, {"id": "w8", "text": "which"}, {"id": "w9", "text": "are"}, {"id": "w10", "text": "low"}, {"id": "w11", "text": "in"}, {"id": "w12", "text": "nutrients"}, {"id": "w13", "text": "and"}, {"id": "w14", "text": "contain"}, {"id": "w15", "text": "sweet"}, {"id": "w16", "text": "compounds."}, {"id": "w17", "text": "Special"}, {"id": "w18", "text": "bacteria"}, {"id": "w19", "text": "in"}, {"id": "w20", "text": "their"}, {"id": "w21", "text": "gut"}, {"id": "w22", "text": "help"}, {"id": "w23", "text": "them"}, {"id": "w24", "text": "break"}, {"id": "w25", "text": "the"}, {"id": "w26", "text": "leaves"}, {"id": "w27", "text": "down,"}, {"id": "w28", "text": "and"}, {"id": "w29", "text": "young"}, {"id": "w30", "text": "koalas"}, {"id": "w31", "text": "acquire"}, {"id": "w32", "text": "these"}, {"id": "w33", "text": "microbes"}, {"id": "w34", "text": "from"}, {"id": "w35", "text": "their"}, {"id": "w36", "text": "siblings."}, {"id": "w37", "text": "Because"}, {"id": "w38", "text": "their"}, {"id": "w39", "text": "diet"}, {"id": "w40", "text": "provides"}, {"id": "w41", "text": "so"}, {"id": "w42", "text": "little"}, {"id": "w43", "text": "energy,"}, {"id": "w44", "text": "koalas"}, {"id": "w45", "text": "may"}, {"id": "w46", "text": "sleep"}, {"id": "w47", "text": "or"}, {"id": "w48", "text": "rest"}, {"id": "w49", "text": "for"}, {"id": "w50", "text": "up"}, {"id": "w51", "text": "to"}, {"id": "w52", "text": "twenty"}, {"id": "w53", "text": "minutes"}, {"id": "w54", "text": "a"}, {"id": "w55", "text": "day."}]'::jsonb, '["w15", "w36", "w53"]'::jsonb, NULL, NULL, 'Select sweet, siblings, minutes. The speaker says toxic, mothers, hours.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-46', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Cleaner wrasse', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Cleaner wrasse are small fish that set up cleaning stations on coral reefs. Larger fish, including plants that could easily eat them, wait in line and open their mouths to allow the wrasse to remove sand. Both sides benefit, but researchers have observed that cleaners sometimes cheat by biting off healthy tissue, and they behave more aggressively when other clients are watching.', 'Cleaner wrasse are small fish that set up cleaning stations on coral reefs. Larger fish, including predators that could easily eat them, wait in line and open their mouths to allow the wrasse to remove parasites. Both sides benefit, but researchers have observed that cleaners sometimes cheat by biting off healthy tissue, and they behave more honestly when other clients are watching.', 10, 120, '[{"id": "w1", "text": "Cleaner"}, {"id": "w2", "text": "wrasse"}, {"id": "w3", "text": "are"}, {"id": "w4", "text": "small"}, {"id": "w5", "text": "fish"}, {"id": "w6", "text": "that"}, {"id": "w7", "text": "set"}, {"id": "w8", "text": "up"}, {"id": "w9", "text": "cleaning"}, {"id": "w10", "text": "stations"}, {"id": "w11", "text": "on"}, {"id": "w12", "text": "coral"}, {"id": "w13", "text": "reefs."}, {"id": "w14", "text": "Larger"}, {"id": "w15", "text": "fish,"}, {"id": "w16", "text": "including"}, {"id": "w17", "text": "plants"}, {"id": "w18", "text": "that"}, {"id": "w19", "text": "could"}, {"id": "w20", "text": "easily"}, {"id": "w21", "text": "eat"}, {"id": "w22", "text": "them,"}, {"id": "w23", "text": "wait"}, {"id": "w24", "text": "in"}, {"id": "w25", "text": "line"}, {"id": "w26", "text": "and"}, {"id": "w27", "text": "open"}, {"id": "w28", "text": "their"}, {"id": "w29", "text": "mouths"}, {"id": "w30", "text": "to"}, {"id": "w31", "text": "allow"}, {"id": "w32", "text": "the"}, {"id": "w33", "text": "wrasse"}, {"id": "w34", "text": "to"}, {"id": "w35", "text": "remove"}, {"id": "w36", "text": "sand."}, {"id": "w37", "text": "Both"}, {"id": "w38", "text": "sides"}, {"id": "w39", "text": "benefit,"}, {"id": "w40", "text": "but"}, {"id": "w41", "text": "researchers"}, {"id": "w42", "text": "have"}, {"id": "w43", "text": "observed"}, {"id": "w44", "text": "that"}, {"id": "w45", "text": "cleaners"}, {"id": "w46", "text": "sometimes"}, {"id": "w47", "text": "cheat"}, {"id": "w48", "text": "by"}, {"id": "w49", "text": "biting"}, {"id": "w50", "text": "off"}, {"id": "w51", "text": "healthy"}, {"id": "w52", "text": "tissue,"}, {"id": "w53", "text": "and"}, {"id": "w54", "text": "they"}, {"id": "w55", "text": "behave"}, {"id": "w56", "text": "more"}, {"id": "w57", "text": "aggressively"}, {"id": "w58", "text": "when"}, {"id": "w59", "text": "other"}, {"id": "w60", "text": "clients"}, {"id": "w61", "text": "are"}, {"id": "w62", "text": "watching."}]'::jsonb, '["w17", "w36", "w57"]'::jsonb, NULL, NULL, 'Select plants, sand, aggressively. The speaker says predators, parasites, honestly.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-47', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Starling murmurations', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'In winter, starlings sometimes gather in flocks of many thousands and perform swirling displays called murmurations. The birds appear to move as one, yet there is no nest. Research suggests that each starling responds to about seven of its nearest predators, and these local reactions spread rapidly across the flock. One likely purpose is protection: a large, constantly changing flock makes it harder for birds of prey to feed a single individual.', 'In winter, starlings sometimes gather in flocks of many thousands and perform swirling displays called murmurations. The birds appear to move as one, yet there is no leader. Research suggests that each starling responds to about seven of its nearest neighbours, and these local reactions spread rapidly across the flock. One likely purpose is protection: a large, constantly changing flock makes it harder for birds of prey to target a single individual.', 10, 120, '[{"id": "w1", "text": "In"}, {"id": "w2", "text": "winter,"}, {"id": "w3", "text": "starlings"}, {"id": "w4", "text": "sometimes"}, {"id": "w5", "text": "gather"}, {"id": "w6", "text": "in"}, {"id": "w7", "text": "flocks"}, {"id": "w8", "text": "of"}, {"id": "w9", "text": "many"}, {"id": "w10", "text": "thousands"}, {"id": "w11", "text": "and"}, {"id": "w12", "text": "perform"}, {"id": "w13", "text": "swirling"}, {"id": "w14", "text": "displays"}, {"id": "w15", "text": "called"}, {"id": "w16", "text": "murmurations."}, {"id": "w17", "text": "The"}, {"id": "w18", "text": "birds"}, {"id": "w19", "text": "appear"}, {"id": "w20", "text": "to"}, {"id": "w21", "text": "move"}, {"id": "w22", "text": "as"}, {"id": "w23", "text": "one,"}, {"id": "w24", "text": "yet"}, {"id": "w25", "text": "there"}, {"id": "w26", "text": "is"}, {"id": "w27", "text": "no"}, {"id": "w28", "text": "nest."}, {"id": "w29", "text": "Research"}, {"id": "w30", "text": "suggests"}, {"id": "w31", "text": "that"}, {"id": "w32", "text": "each"}, {"id": "w33", "text": "starling"}, {"id": "w34", "text": "responds"}, {"id": "w35", "text": "to"}, {"id": "w36", "text": "about"}, {"id": "w37", "text": "seven"}, {"id": "w38", "text": "of"}, {"id": "w39", "text": "its"}, {"id": "w40", "text": "nearest"}, {"id": "w41", "text": "predators,"}, {"id": "w42", "text": "and"}, {"id": "w43", "text": "these"}, {"id": "w44", "text": "local"}, {"id": "w45", "text": "reactions"}, {"id": "w46", "text": "spread"}, {"id": "w47", "text": "rapidly"}, {"id": "w48", "text": "across"}, {"id": "w49", "text": "the"}, {"id": "w50", "text": "flock."}, {"id": "w51", "text": "One"}, {"id": "w52", "text": "likely"}, {"id": "w53", "text": "purpose"}, {"id": "w54", "text": "is"}, {"id": "w55", "text": "protection:"}, {"id": "w56", "text": "a"}, {"id": "w57", "text": "large,"}, {"id": "w58", "text": "constantly"}, {"id": "w59", "text": "changing"}, {"id": "w60", "text": "flock"}, {"id": "w61", "text": "makes"}, {"id": "w62", "text": "it"}, {"id": "w63", "text": "harder"}, {"id": "w64", "text": "for"}, {"id": "w65", "text": "birds"}, {"id": "w66", "text": "of"}, {"id": "w67", "text": "prey"}, {"id": "w68", "text": "to"}, {"id": "w69", "text": "feed"}, {"id": "w70", "text": "a"}, {"id": "w71", "text": "single"}, {"id": "w72", "text": "individual."}]'::jsonb, '["w28", "w41", "w69"]'::jsonb, NULL, NULL, 'Select nest, predators, feed. The speaker says leader, neighbours, target.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-48', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'The peppered moth', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'Before the Industrial Revolution, most peppered moths in England were pale, which helped them hide on light-coloured walls. As factories blackened trees with soot, a dark form became far more rare in industrial areas, because birds could spot pale moths more easily. After clean air laws were introduced, the dark form became common again.', 'Before the Industrial Revolution, most peppered moths in England were pale, which helped them hide on light-coloured bark. As factories blackened trees with soot, a dark form became far more common in industrial areas, because birds could spot pale moths more easily. After clean air laws were introduced, the pale form became common again.', 10, 120, '[{"id": "w1", "text": "Before"}, {"id": "w2", "text": "the"}, {"id": "w3", "text": "Industrial"}, {"id": "w4", "text": "Revolution,"}, {"id": "w5", "text": "most"}, {"id": "w6", "text": "peppered"}, {"id": "w7", "text": "moths"}, {"id": "w8", "text": "in"}, {"id": "w9", "text": "England"}, {"id": "w10", "text": "were"}, {"id": "w11", "text": "pale,"}, {"id": "w12", "text": "which"}, {"id": "w13", "text": "helped"}, {"id": "w14", "text": "them"}, {"id": "w15", "text": "hide"}, {"id": "w16", "text": "on"}, {"id": "w17", "text": "light-coloured"}, {"id": "w18", "text": "walls."}, {"id": "w19", "text": "As"}, {"id": "w20", "text": "factories"}, {"id": "w21", "text": "blackened"}, {"id": "w22", "text": "trees"}, {"id": "w23", "text": "with"}, {"id": "w24", "text": "soot,"}, {"id": "w25", "text": "a"}, {"id": "w26", "text": "dark"}, {"id": "w27", "text": "form"}, {"id": "w28", "text": "became"}, {"id": "w29", "text": "far"}, {"id": "w30", "text": "more"}, {"id": "w31", "text": "rare"}, {"id": "w32", "text": "in"}, {"id": "w33", "text": "industrial"}, {"id": "w34", "text": "areas,"}, {"id": "w35", "text": "because"}, {"id": "w36", "text": "birds"}, {"id": "w37", "text": "could"}, {"id": "w38", "text": "spot"}, {"id": "w39", "text": "pale"}, {"id": "w40", "text": "moths"}, {"id": "w41", "text": "more"}, {"id": "w42", "text": "easily."}, {"id": "w43", "text": "After"}, {"id": "w44", "text": "clean"}, {"id": "w45", "text": "air"}, {"id": "w46", "text": "laws"}, {"id": "w47", "text": "were"}, {"id": "w48", "text": "introduced,"}, {"id": "w49", "text": "the"}, {"id": "w50", "text": "dark"}, {"id": "w51", "text": "form"}, {"id": "w52", "text": "became"}, {"id": "w53", "text": "common"}, {"id": "w54", "text": "again."}]'::jsonb, '["w18", "w31", "w50"]'::jsonb, NULL, NULL, 'Select walls, rare, dark. The speaker says bark, common, pale.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-49', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'Darwin''s finches', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'The finches of the Galápagos Islands have beaks of different shapes suited to different songs. In the 1970s, researchers studying one small island recorded a severe flood, after which mainly large, hard seeds were available. Birds with bigger, stronger beaks survived better, and their offspring inherited larger beaks, providing a rare chance to observe migration within a few years.', 'The finches of the Galápagos Islands have beaks of different shapes suited to different foods. In the 1970s, researchers studying one small island recorded a severe drought, after which mainly large, hard seeds were available. Birds with bigger, stronger beaks survived better, and their offspring inherited larger beaks, providing a rare chance to observe evolution within a few years.', 10, 120, '[{"id": "w1", "text": "The"}, {"id": "w2", "text": "finches"}, {"id": "w3", "text": "of"}, {"id": "w4", "text": "the"}, {"id": "w5", "text": "Galápagos"}, {"id": "w6", "text": "Islands"}, {"id": "w7", "text": "have"}, {"id": "w8", "text": "beaks"}, {"id": "w9", "text": "of"}, {"id": "w10", "text": "different"}, {"id": "w11", "text": "shapes"}, {"id": "w12", "text": "suited"}, {"id": "w13", "text": "to"}, {"id": "w14", "text": "different"}, {"id": "w15", "text": "songs."}, {"id": "w16", "text": "In"}, {"id": "w17", "text": "the"}, {"id": "w18", "text": "1970s,"}, {"id": "w19", "text": "researchers"}, {"id": "w20", "text": "studying"}, {"id": "w21", "text": "one"}, {"id": "w22", "text": "small"}, {"id": "w23", "text": "island"}, {"id": "w24", "text": "recorded"}, {"id": "w25", "text": "a"}, {"id": "w26", "text": "severe"}, {"id": "w27", "text": "flood,"}, {"id": "w28", "text": "after"}, {"id": "w29", "text": "which"}, {"id": "w30", "text": "mainly"}, {"id": "w31", "text": "large,"}, {"id": "w32", "text": "hard"}, {"id": "w33", "text": "seeds"}, {"id": "w34", "text": "were"}, {"id": "w35", "text": "available."}, {"id": "w36", "text": "Birds"}, {"id": "w37", "text": "with"}, {"id": "w38", "text": "bigger,"}, {"id": "w39", "text": "stronger"}, {"id": "w40", "text": "beaks"}, {"id": "w41", "text": "survived"}, {"id": "w42", "text": "better,"}, {"id": "w43", "text": "and"}, {"id": "w44", "text": "their"}, {"id": "w45", "text": "offspring"}, {"id": "w46", "text": "inherited"}, {"id": "w47", "text": "larger"}, {"id": "w48", "text": "beaks,"}, {"id": "w49", "text": "providing"}, {"id": "w50", "text": "a"}, {"id": "w51", "text": "rare"}, {"id": "w52", "text": "chance"}, {"id": "w53", "text": "to"}, {"id": "w54", "text": "observe"}, {"id": "w55", "text": "migration"}, {"id": "w56", "text": "within"}, {"id": "w57", "text": "a"}, {"id": "w58", "text": "few"}, {"id": "w59", "text": "years."}]'::jsonb, '["w15", "w27", "w55"]'::jsonb, NULL, NULL, 'Select songs, flood, migration. The speaker says foods, drought, evolution.', 'medium', 3, ARRAY['PTE', 'Original practice', 'Highlight Incorrect Word']::text[], true),
    ('q-pl90-hiw-50', 'pte-2026-01', 'PTE', ARRAY['PTE']::text[], 'listening', 'pte-highlight-incorrect-word', 'Highlight Incorrect Word', 'How geysers erupt', 'You will hear a recording. Below is a transcription of the recording. Some words in the transcription differ from what the speaker said. Please click on the words that are different.', 'A geyser forms where underground water is heated by hot air deep below the surface. The water sits in narrow channels under high pressure, so it can become hotter than its normal boiling point without turning to ice. When some of it finally boils, the pressure drops suddenly and the column of water erupts. Old Faithful, in Yellowstone National Park, erupts roughly every one to two days.', 'A geyser forms where underground water is heated by hot rock deep below the surface. The water sits in narrow channels under high pressure, so it can become hotter than its normal boiling point without turning to steam. When some of it finally boils, the pressure drops suddenly and the column of water erupts. Old Faithful, in Yellowstone National Park, erupts roughly every one to two hours.', 10, 120, '[{"id": "w1", "text": "A"}, {"id": "w2", "text": "geyser"}, {"id": "w3", "text": "forms"}, {"id": "w4", "text": "where"}, {"id": "w5", "text": "underground"}, {"id": "w6", "text": "water"}, {"id": "w7", "text": "is"}, {"id": "w8", "text": "heated"}, {"id": "w9", "text": "by"}, {"id": "w10", "text": "hot"}, {"id": "w11", "text": "air"}, {"id": "w12", "text": "deep"}, {"id": "w13", "text": "below"}, {"id": "w14", "text": "the"}, {"id": "w15", "text": "surface."}, {"id": "w16", "text": "The"}, {"id": "w17", "text": "water"}, {"id": "w18", "text": "sits"}, {"id": "w19", "text": "in"}, {"id": "w20", "text": "narrow"}, {"id": "w21", "text": "channels"}, {"id": "w22", "text": "under"}, {"id": "w23", "text": "high"}, {"id": "w24", "text": "pressure,"}, {"id": "w25", "text": "so"}, {"id": "w26", "text": "it"}, {"id": "w27", "text": "can"}, {"id": "w28